(window.CLAVE_TODO=window.CLAVE_TODO||{})[18]=[{"a":"Artículo 40","q":[{"i":"18-1","p":"Código Penal. La pena de inhabilitación especial tendrá una duración de:","o":["3 meses a 20 años.","6 meses a 20 años.","1 mes a 10 años.","3 meses a 10 años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">3 meses a 20 años.</mark></span><span class=\"ref-norma\">Art. 40 · De las Penas</span>. - Según el artículo 40 del Código Penal, la inhabilitación especial tiene duración de 3 meses a 20 años."},{"i":"18-67","p":"Código Penal. De las penas privativas de derechos. La pena de privación del derecho a conducir vehículos a motor y ciclomotores tendrá una duración de:","o":["De 3 meses a 10 años.","De 1 día a 10 años","De 3 meses a 30 años","De 10 meses a 10 años"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">De 3 meses a 10 años</mark></span>Según el <span class=\"ref-norma\">art. 40 del Código Penal</span>: <span class=\"ref-concepto\">\"tendrán una duración de tres meses a 10 años\"</span> (verificado con el texto del temario oficial)."},{"i":"18-90","p":"Código Penal. Penas privativas de derecho. La pena de inhabilitación absoluta:","o":["Tendrá una duración de 3 meses a 10 años","Tendrá una duración de 2 meses a 6 años","Tendrá una duración de 3 meses a 20 años","Tendrá una duración de 6 a 20 años"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Tendrá una duración de 6 a 20 años</mark></span>- La inhabilitación absoluta tiene duración de 6 a 20 años."},{"i":"18-ia-1212","p":"Código Penal. Duración de las penas privativas de derechos. La pena de inhabilitación absoluta tendrá una duración de:","o":["tres meses a 20 años.","seis a 20 años.","seis a 10 años.","tres a 20 años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">seis a 20 años</mark></span>El <span class=\"ref-norma\">art. 40.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La pena de inhabilitación absoluta tendrá una duración de seis a 20 años\"</span>. Inhabilitación absoluta: seis a 20 años. Inhabilitación especial: tres meses a 20 años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1213","p":"Código Penal. Duración de las penas privativas de derechos. La suspensión de empleo o cargo público tendrá una duración de:","o":["tres meses a seis años.","seis meses a diez años, previo informe de la unidad policial competente.","tres meses a 20 años.","un año a seis años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">tres meses a seis años</mark></span>El <span class=\"ref-norma\">art. 40.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"la de suspensión de empleo o cargo público, de tres meses a seis años\"</span>. Suspensión de empleo o cargo público: tres meses a seis años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1214","p":"Código Penal. Duración de las penas privativas de derechos. La pena de privación del derecho a conducir vehículos a motor y ciclomotores, y la de privación del derecho a la tenencia y porte de armas, tendrán una duración de:","o":["seis meses a 10 años.","tres meses a seis años.","un año a 10 años.","tres meses a 10 años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tres meses a 10 años</mark></span>El <span class=\"ref-norma\">art. 40.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"tendrán una duración de tres meses a 10 años\"</span>. Tres meses a 10 años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1215","p":"Código Penal. Duración de las penas privativas de derechos. La prohibición de aproximarse a la víctima o a aquellos de sus familiares u otras personas, o de comunicarse con ellas, tendrá una duración de:","o":["tres meses a 10 años.","un día a un año.","un mes a 10 años.","hasta 10 años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">un mes a 10 años</mark></span>El <span class=\"ref-norma\">art. 40.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"tendrá una duración de un mes a 10 años\"</span>. Un mes a 10 años; la privación del derecho a residir en determinados lugares o acudir a ellos es de hasta 10 años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1216","p":"Código Penal. Duración de las penas privativas de derechos. La pena de trabajos en beneficio de la comunidad tendrá una duración de:","o":["un mes a un año.","un día a un año.","un día a dos años.","diez días a un año."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">un día a un año</mark></span>El <span class=\"ref-norma\">art. 40.4 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La pena de trabajos en beneficio de la comunidad tendrá una duración de un día a un año\"</span>. Un día a un año. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"De las Penas","q":[{"i":"18-2","p":"Código Penal. No se reputarán penas:","o":["La detención y prisión preventiva y las demás medidas cautelares de naturaleza penal.","Las multas y demás correcciones que, en uso de atribuciones gubernativas o disciplinarias, se impongan a los subordinados o administrados.","Las privaciones de derechos y las sanciones reparadoras que establezcan las leyes civiles o administrativas.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 34 del Código Penal</span>: <span class=\"ref-concepto\">\"Las multas y demás correcciones que, en uso de atribuciones gubernativas o disciplinarias, se impongan a los subordinados o administrados\"</span> (verificado con el texto del temario oficial)."},{"i":"18-36","p":"Código Penal. La pena de intervención judicial para salvaguardar los derechos de los trabajadores o de los acreedores por el tiempo que se estime necesario, no podrá exceder de:","o":["Dos años","Tres años","Cuatro años","Todas son incorrectas"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son incorrectas</mark></span>El máximo es de cinco años: ninguna de las tres cifras (dos, tres o cuatro años) es correcta. Según el <span class=\"ref-norma\">art. 33 del Código Penal</span>: <span class=\"ref-concepto\">\"g) Intervención judicial para salvaguardar los derechos de los trabajadores o de los acreedores por el tiempo que se estime necesario, que no podrá exceder de cinco años\"</span> (verificado con el texto del temario oficial)."},{"i":"18-103","p":"Código Penal. Los modelos de organización y gestión que el órgano de administración haya adoptado y ejecutado con diligencia, antes de la comisión del delito, modelos de organización y gestión que incluyen las medidas de vigilancia y control idóneas para prevenir delitos de la misma naturaleza o para reducir de forma significativa el riesgo de su comisión; deberán cumplir los siguientes requisitos:","o":["Identificar las actividades en cuyo ámbito puedan ser cometidos los delitos que deben ser prevenidos","Establecer los protocolos o procedimientos que concreten el proceso de formación de la voluntad de la persona jurídica, de adopción de decisiones y de ejecución de las mismas con relación a aquéllos","Disponer de modelos de gestión de los recursos financieros adecuados para impedir la comisión de los delitos que deben ser prevenidos","Todas son correctas"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>- Todos son requisitos para los modelos de organización y gestión preventivos."},{"i":"18-105","p":"Los condenados que hayan extinguido su responsabilidad penal tienen derecho a obtener del Ministerio de Justicia, de oficio o a instancia de parte, la cancelación de sus antecedentes penales, cuando hayan transcurrido sin haber vuelto a delinqüir los siguientes plazos: Señale la correcta.","o":["Dos años para las penas que no exceden de doce meses y las impuestas por delitos imprudentes.","Tres años para las restantes penas menos graves inferiores a tres años.","Siete años para las restantes penas menos graves iguales o siguientes a tres años.","Las respuestas A y B son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las respuestas A y B son correctas</mark></span>La opción C es falsa: son cinco años (no siete) para las menos graves iguales o superiores a tres años. Según el <span class=\"ref-norma\">art. 136 del Código Penal</span>: <span class=\"ref-concepto\">\"b) Dos años para las penas que no excedan de doce meses y las impuestas por delitos imprudentes. c) Tres años para las restantes penas menos graves inferiores a tres años\"</span> (verificado con el texto del temario oficial)."},{"i":"18-108","p":"Ley Orgánica 10/1995, de 23 de noviembre, del Código Penal. Quedará exento de responsabilidad penal por el delito intentado: Señale la correcta.","o":["Cuando el sujeto de comienzo a la ejecución del delito, se arrepienta o impida la producción del resultado.","Cuando el sujeto de comienzo a la ejecución del delito y sin embargo éste no se produzca.","Cuando el sujeto de comienzo a la ejecución del delito, se arrepienta y destina de la ejecución ya iniciada.","Quien evita voluntariamente la consumación del delito, bien desistiendo de la ejecución ya iniciada, bien impidiendo la producción del resultado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Quien evita voluntariamente la consumación del delito, bien desistiendo de la ejecución ya iniciada, bien impidiendo la producción del resultado</mark></span>Según el <span class=\"ref-norma\">art. 16 del Código Penal</span>: <span class=\"ref-concepto\">\"Quedará exento de responsabilidad penal por el delito intentado quien evite voluntariamente la consumación del delito, bien desistiendo de la ejecución ya iniciada, bien impidiendo la producción del resultado\"</span> (verificado con el texto del temario oficial)."},{"i":"18-128","p":"Código Penal. ¿En qué momento se considera que hay tentativa de delito?","o":["Cuando el sujeto piensa en cometer el delito.","Cuando el sujeto da principio a la ejecución del delito por hechos internos.","Cuando el sujeto completa todos los actos necesarios para el delito.","Cuando el sujeto da principio a la ejecución del delito directamente por hechos exteriores, practicando todos o parte de los actos que objetivamente deberían producir el resultado y sin embargo éste no se produce por causas independientes de la voluntad del autor."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuando el sujeto da principio a la ejecución del delito directamente por hechos exteriores, practicando todos o parte de los actos que obje…</mark></span>(Esta es la definición legal de tentativa)."},{"i":"18-234","p":"Código Penal. ¿Quién comunicará al ministerio fiscal, con suficiente antelación, la próxima extinción de la pena o medida de seguridad impuesta?","o":["El Tribunal sentenciador.","El Juez de instrucción.","El Juez sentenciador.","El Juez de Vigilancia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Juez de Vigilancia.</mark></span><span class=\"ref-norma\">Art. 98 · De las Penas</span>. (El Artículo 98 del CP establece que es el Juez de Vigilancia Penitenciaria quien debe realizar esta comunicación)."},{"i":"18-245","p":"Código Penal. Si la persona condenada lo fuera a pena de prisión y el Juez o Tribunal acordara la imposición de una o varias de dichas prohibiciones, lo hará por un tiempo superior entre uno y diez años al de la duración de la pena de prisión impuesta en la sentencia, si el delito fuera grave, y entre uno y cinco años, si fuera menos grave. En este supuesto, la pena de prisión y las prohibiciones antes citadas se cumplirán necesariamente por la persona condenada:","o":["Coordinadamente.","Ordenadamente.","Simultáneamente.","Predeterminadamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Simultáneamente.</mark></span><span class=\"ref-norma\">Art. 57.2 · De las Penas</span>. (El Artículo 57.2 del CP establece que se cumplirán simultáneamente)."},{"i":"18-ia-1146","p":"Código Penal. Penas aplicables a las personas jurídicas. Las penas aplicables a las personas jurídicas, que tienen todas la consideración de:","o":["graves o menos graves, según su duración y la gravedad del delito cometido.","menos graves, son las siguientes: multa, disolución y clausura de locales y establecimientos.","graves, son las siguientes: multa, disolución y suspensión de actividades, con exclusión de la intervención judicial, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente.","graves, son las siguientes: multa por cuotas o proporcional, disolución, suspensión de actividades, clausura de locales, prohibición de actividades, inhabilitación e intervención judicial."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">graves, son las siguientes: multa por cuotas o proporcional, disolución, suspensión de actividades, clausura de locales, prohibición de actividades, inhabilitación e intervención judicial</mark></span>El <span class=\"ref-norma\">art. 33.7 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Las penas aplicables a las personas jurídicas, que tienen todas la consideración de graves, son las siguientes\"</span>. Todas las penas de las personas jurídicas son graves. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1160","p":"Código Penal. Pena de prisión. Señale la INCORRECTA. Cuando la duración de la pena de prisión impuesta sea superior a cinco años, la clasificación del condenado en el tercer grado no podrá efectuarse hasta el cumplimiento de la mitad de la misma en los delitos de:","o":["Terrorismo del Capítulo VII del Título XXII del Libro II.","Hurto y robo con fuerza en las cosas.","Los cometidos en el seno de una organización o grupo criminal.","Los del artículo 181."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Hurto y robo con fuerza en las cosas</mark></span>El <span class=\"ref-norma\">art. 36.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"En cualquier caso, cuando la duración de la pena de prisión impuesta sea superior a cinco años y se trate de los delitos enumerados a continuación, la clasificación del condenado en el tercer grado de tratamiento penitenciario no podrá efectuarse hasta el cumplimiento de la mitad de la misma\"</span>. El periodo de seguridad obligatorio se refiere a terrorismo, organización o grupo criminal, delitos sexuales y los del artículo 181, no al hurto o robo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1205","p":"Código Penal. Pena de prisión. Señale cuál de los siguientes delitos NO figura entre los enumerados para los que, si la pena de prisión impuesta es superior a cinco años, la clasificación en tercer grado no podrá efectuarse hasta el cumplimiento de la mitad de la misma:","o":["Delitos contra la Hacienda Pública y contra la Seguridad Social.","Delitos cometidos en el seno de una organización o grupo criminal.","Delitos referentes a organizaciones y grupos terroristas y delitos de terrorismo.","Delitos del artículo 181."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Delitos contra la Hacienda Pública y contra la Seguridad Social</mark></span>El <span class=\"ref-norma\">art. 36.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Delitos referentes a organizaciones y grupos terroristas y delitos de terrorismo del Capítulo VII del Título XXII del Libro II de este Código. b) Delitos cometidos en el seno de una organización o grupo criminal\"</span>. No figuran los delitos contra la Hacienda Pública y contra la Seguridad Social. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1219","p":"Código Penal. Suspensión de empleo o cargo público. La suspensión de empleo o cargo público priva de su ejercicio al penado:","o":["de forma definitiva.","durante el tiempo de la condena y los dos años siguientes.","durante el tiempo de la condena.","hasta que lo rehabilite el órgano que lo nombró."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">durante el tiempo de la condena</mark></span>El <span class=\"ref-norma\">art. 43 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La suspensión de empleo o cargo público priva de su ejercicio al penado durante el tiempo de la condena\"</span>. Durante el tiempo de la condena. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1220","p":"Código Penal. Inhabilitación especial para el derecho de sufragio pasivo. La inhabilitación especial para el derecho de sufragio pasivo priva al penado, durante el tiempo de la condena, del derecho:","o":["a elegir a los titulares de cargos públicos.","a ser elegido para cargos públicos.","a ejercer cualquier cargo público, sea o no electivo.","a participar como interventor en procesos electorales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a ser elegido para cargos públicos</mark></span>El <span class=\"ref-norma\">art. 44 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"priva al penado, durante el tiempo de la condena, del derecho a ser elegido para cargos públicos\"</span>. Sufragio pasivo: derecho a ser elegido. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1221","p":"Código Penal. Inhabilitación especial para profesión, oficio, industria o comercio. La inhabilitación especial para profesión, oficio, industria o comercio u otras actividades, sean o no retribuidas, o cualquier otro derecho, ha de concretarse en la sentencia de forma:","o":["expresa y motivada.","genérica y razonada.","expresa, previo informe del Ministerio Fiscal.","motivada, previa audiencia del colegio profesional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">expresa y motivada</mark></span>El <span class=\"ref-norma\">art. 45 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"que ha de concretarse expresa y motivadamente en la sentencia\"</span>. Debe concretarse expresa y motivadamente en la sentencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1222","p":"Código Penal. Inhabilitación especial para profesión, oficio, industria o comercio. La autoridad judicial podrá restringir la inhabilitación a determinadas actividades o funciones de la profesión u oficio, retribuido o no, permitiendo, si ello fuera posible:","o":["el ejercicio de las funciones de carácter meramente administrativo.","el ejercicio de la profesión bajo la supervisión del colegio profesional, sin perjuicio de lo previsto en la normativa vigente.","el ejercicio de funciones docentes relacionadas con la profesión.","el ejercicio de aquellas funciones no directamente relacionadas con el delito cometido."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el ejercicio de aquellas funciones no directamente relacionadas con el delito cometido</mark></span>El <span class=\"ref-norma\">art. 45 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"permitiendo, si ello fuera posible, el ejercicio de aquellas funciones no directamente relacionadas con el delito cometido\"</span>. Funciones no directamente relacionadas con el delito. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1223","p":"Código Penal. Inhabilitación especial para la patria potestad, tutela, curatela, guarda o acogimiento. La pena de privación de la patria potestad implica la pérdida de la titularidad de la misma, subsistiendo aquellos derechos de los que sea titular el hijo o la hija respecto de la persona condenada que:","o":["determine el Ministerio Fiscal.","se establezcan en el Código Civil.","se determinen judicialmente.","se fijen en convenio regulador."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">se determinen judicialmente</mark></span>El <span class=\"ref-norma\">art. 46 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"subsistiendo aquellos derechos de los que sea titular el hijo o la hija respecto de la persona condenada que se determinen judicialmente\"</span>. Los que se determinen judicialmente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1224","p":"Código Penal. Inhabilitación especial para la patria potestad, tutela, curatela, guarda o acogimiento. Para concretar qué derechos de las personas menores de edad o personas con discapacidad han de subsistir en caso de privación de la patria potestad, la autoridad judicial valorará:","o":["el informe de los servicios sociales y el parecer del Ministerio Fiscal en cada caso, en los términos que se determinen reglamentariamente.","el interés superior de la persona menor de edad o con discapacidad, en relación a las circunstancias del caso concreto.","la gravedad del delito cometido y la peligrosidad del condenado para los hijos.","la voluntad de la persona menor de edad, siempre que tenga más de doce años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el interés superior de la persona menor de edad o con discapacidad, en relación a las circunstancias del caso concreto</mark></span>El <span class=\"ref-norma\">art. 46 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"la autoridad judicial valorará el interés superior de la persona menor de edad o con discapacidad, en relación a las circunstancias del caso concreto\"</span>. El interés superior del menor o de la persona con discapacidad, en relación con las circunstancias del caso concreto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1230","p":"Código Penal. Trabajos en beneficio de la comunidad. Señale la INCORRECTA sobre las condiciones de los trabajos en beneficio de la comunidad:","o":["La ejecución se desarrollará bajo el control del Juez de Vigilancia Penitenciaria.","No atentará a la dignidad del penado.","Gozará de la protección dispensada a los penados por la legislación penitenciaria en materia de Seguridad Social.","Se podrá supeditar al logro de intereses económicos de la Administración que los facilite."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Se podrá supeditar al logro de intereses económicos de la Administración que los facilite</mark></span>El <span class=\"ref-norma\">art. 49 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"5.ª No se supeditará al logro de intereses económicos\"</span>. No se supeditará al logro de intereses económicos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1239","p":"Código Penal. Pena de multa. Si, después de la sentencia, variase la situación económica del penado, el juez o tribunal, excepcionalmente y tras la debida indagación de dicha situación, podrá modificar:","o":["únicamente los plazos para su pago, pero no el importe de las cuotas, en los términos que se determinen reglamentariamente.","el importe total de la multa y la extensión de la pena.","tanto el importe de las cuotas periódicas como los plazos para su pago.","únicamente el importe de las cuotas periódicas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">tanto el importe de las cuotas periódicas como los plazos para su pago</mark></span>El <span class=\"ref-norma\">art. 51 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"podrá modificar tanto el importe de las cuotas periódicas como los plazos para su pago\"</span>. Importe de las cuotas periódicas y plazos de pago. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1240","p":"Código Penal. Multa proporcional. Si, después de la sentencia, empeorase la situación económica del penado, el juez o tribunal, excepcionalmente y tras la debida indagación de dicha situación, podrá:","o":["dejar sin efecto la multa y sustituirla por trabajos en beneficio de la comunidad.","reducir el importe de la multa dentro de los límites señalados por la ley para el delito de que se trate, o autorizar su pago en los plazos que se determinen.","reducir el importe de la multa por debajo de los límites señalados por la ley para el delito, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente.","declarar extinguida la responsabilidad pecuniaria por insolvencia sobrevenida."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">reducir el importe de la multa dentro de los límites señalados por la ley para el delito de que se trate, o autorizar su pago en los plazos que se determinen</mark></span>El <span class=\"ref-norma\">art. 52.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"podrá reducir el importe de la multa dentro de los límites señalados por la ley para el delito de que se trate, o autorizar su pago en los plazos que se determinen\"</span>. Reducir el importe dentro de los límites legales o autorizar el pago fraccionado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1241","p":"Código Penal. Multa proporcional. Si no fuera posible calcular la multa proporcional de las personas jurídicas, las multas previstas se sustituirán por la de dos a cinco años:","o":["si el delito cometido por la persona física tiene prevista una pena de prisión de más de cinco años.","si el delito cometido por la persona física tiene prevista una pena de prisión de más de dos años.","en el resto de los casos.","si el delito cometido por la persona física tiene prevista una pena de prisión de más de diez años, sin perjuicio de lo previsto en la normativa vigente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">si el delito cometido por la persona física tiene prevista una pena de prisión de más de cinco años</mark></span>El <span class=\"ref-norma\">art. 52.4 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"a) Multa de dos a cinco años, si el delito cometido por la persona física tiene prevista una pena de prisión de más de cinco años\"</span>. Dos a cinco años: prisión de más de cinco años; uno a tres años: más de dos años; seis meses a dos años: resto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1248","p":"Código Penal. Penas accesorias. Las penas de inhabilitación son accesorias:","o":["en todos los casos en que se imponga pena de prisión superior a un año.","en los casos en que, no imponiéndolas especialmente, la Ley declare que otras penas las llevan consigo.","en los casos en que lo solicite el Ministerio Fiscal en su escrito de calificación.","cuando el juez o tribunal lo considere necesario atendiendo a la gravedad del delito, previo informe de la unidad policial competente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en los casos en que, no imponiéndolas especialmente, la Ley declare que otras penas las llevan consigo</mark></span>El <span class=\"ref-norma\">art. 54 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Las penas de inhabilitación son accesorias en los casos en que, no imponiéndolas especialmente, la Ley declare que otras penas las llevan consigo\"</span>. Cuando la Ley declare que otras penas las llevan consigo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1252","p":"Código Penal. Penas accesorias. Las autoridades judiciales, en determinados delitos, atendiendo a la gravedad de los hechos o al peligro que el delincuente represente, podrán acordar en sus sentencias la imposición de una o varias de las prohibiciones de residir en determinados lugares, aproximarse a la víctima o comunicarse con ella, por un tiempo que no excederá de __________ si el delito fuera grave, o de cinco si fuera menos grave:","o":["cinco años","diez años","quince años","veinte años"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">diez años</mark></span>El <span class=\"ref-norma\">art. 57.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"por un tiempo que no excederá de diez años si el delito fuera grave, o de cinco si fuera menos grave\"</span>. Diez años si el delito es grave; cinco si es menos grave. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1253","p":"Código Penal. Penas accesorias. Si la persona condenada lo fuera a pena de prisión y el Juez o Tribunal acordara la imposición de una o varias de dichas prohibiciones, lo hará por un tiempo superior al de la duración de la pena de prisión impuesta en la sentencia:","o":["entre uno y diez años, si el delito fuera grave, y entre uno y cinco años, si fuera menos grave.","entre uno y cinco años, si el delito fuera grave, y entre seis meses y tres años, si fuera menos grave.","entre uno y diez años, tanto si el delito fuera grave como menos grave.","entre dos y diez años, si el delito fuera grave, y entre uno y cinco años, si fuera menos grave."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">entre uno y diez años, si el delito fuera grave, y entre uno y cinco años, si fuera menos grave</mark></span>El <span class=\"ref-norma\">art. 57.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"lo hará por un tiempo superior entre uno y diez años al de la duración de la pena de prisión impuesta en la sentencia, si el delito fuera grave, y entre uno y cinco años, si fuera menos grave\"</span>. Entre uno y diez años (grave) y entre uno y cinco (menos grave); prisión y prohibiciones se cumplen simultáneamente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1258","p":"Código Penal. Disposiciones comunes. Cuando las medidas cautelares sufridas y la pena impuesta sean de distinta naturaleza, el Juez o Tribunal ordenará que se tenga por ejecutada la pena impuesta:","o":["en su totalidad.","en la mitad de su duración.","en la parte que solicite el penado, salvo que la autoridad judicial disponga otra cosa.","en aquella parte que estime compensada."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">en aquella parte que estime compensada</mark></span>El <span class=\"ref-norma\">art. 59 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el Juez o Tribunal ordenará que se tenga por ejecutada la pena impuesta en aquella parte que estime compensada\"</span>. En la parte que estime compensada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1259","p":"Código Penal. Disposiciones comunes. Cuando, después de pronunciada sentencia firme, se aprecie en el penado una situación duradera de trastorno mental grave que le impida conocer el sentido de la pena, el Juez de Vigilancia Penitenciaria:","o":["declarará extinguida la responsabilidad criminal del penado por enfermedad sobrevenida.","acordará el cumplimiento de la pena en un centro hospitalario durante todo el tiempo de la condena, previo informe de la unidad policial competente.","suspenderá la ejecución de la pena privativa de libertad que se le hubiera impuesto, garantizando que reciba la asistencia médica precisa.","propondrá al Gobierno el indulto del penado por razones de salud."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">suspenderá la ejecución de la pena privativa de libertad que se le hubiera impuesto, garantizando que reciba la asistencia médica precisa</mark></span>El <span class=\"ref-norma\">art. 60.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el Juez de Vigilancia Penitenciaria suspenderá la ejecución de la pena privativa de libertad que se le hubiera impuesto, garantizando que reciba la asistencia médica precisa\"</span>. Suspende la ejecución garantizando la asistencia médica precisa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1260","p":"Código Penal. Disposiciones comunes. Restablecida la salud mental del penado, éste cumplirá la sentencia si la pena no hubiere prescrito, sin perjuicio de que el Juez o Tribunal, por razones de equidad, pueda:","o":["sustituir la pena por una medida de seguridad de internamiento por el tiempo restante, sin perjuicio de lo previsto en la normativa vigente.","dar por extinguida la condena o reducir su duración, en la medida en que el cumplimiento de la pena resulte innecesario o contraproducente.","suspender indefinidamente el cumplimiento de la condena pendiente.","reducir la duración de la condena a la mitad de la pena pendiente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">dar por extinguida la condena o reducir su duración, en la medida en que el cumplimiento de la pena resulte innecesario o contraproducente</mark></span>El <span class=\"ref-norma\">art. 60.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"sin perjuicio de que el Juez o Tribunal, por razones de equidad, pueda dar por extinguida la condena o reducir su duración, en la medida en que el cumplimiento de la pena resulte innecesario o contraproducente\"</span>. Por razones de equidad puede extinguir o reducir la condena. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1261","p":"Código Penal. Reglas generales para la aplicación de las penas. Cuando la Ley establece una pena, se entiende que la impone:","o":["a los autores de la infracción consumada.","a los autores y cómplices de la infracción consumada.","a los autores de la infracción consumada o intentada.","a los responsables criminales de la infracción en grado de tentativa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a los autores de la infracción consumada</mark></span>El <span class=\"ref-norma\">art. 61 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Cuando la Ley establece una pena, se entiende que la impone a los autores de la infracción consumada\"</span>. A los autores de la infracción consumada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 31 quinquies ✱","q":[{"i":"18-4","p":"Código Penal. Las disposiciones relativas a la responsabilidad penal de las personas jurídicas no serán aplicables: señale la INCORRECTA.","o":["Las Agencias y Entidades públicas Empresariales.","Las Organizaciones públicas territoriales e institucionales.","Los Organismos Reguladores.","Las Organizaciones Internacionales de derecho público."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Las Organizaciones públicas territoriales e institucionales</mark></span>No se dice «Administraciones públicas territoriales e institucionales» sino «Organizaciones públicas…»: la opción B altera el texto. Según el <span class=\"ref-norma\">art. 31 quinquies del Código Penal</span>: <span class=\"ref-concepto\">\"Las disposiciones relativas a la responsabilidad penal de las personas jurídicas no serán aplicables al Estado, a las Administraciones públicas territoriales e institucionales, a los Organismos Reguladores, las Agencias y Entidades públicas Empresariales, a las organizaciones internacionales de derecho público\"</span> (verificado con el texto del temario oficial)."},{"i":"18-144","p":"Código Penal. Las disposiciones relativas a la responsabilidad penal de las personas jurídicas no serán aplicables: señale la INCORRECTA.","o":["A las organizaciones internacionales de derecho público.","Al Estado.","A los Organismos Reguladores.","A las Sociedades mercantiles públicas que ejecuten políticas públicas o presten servicios de interés económico general."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A las Sociedades mercantiles públicas que ejecuten políticas públicas o presten servicios de interés económico general</mark></span>A las Sociedades mercantiles públicas sí se les pueden imponer las penas de las letras a) y g) del apartado 7 del artículo 33. Según el <span class=\"ref-norma\">art. 31 quinquies del Código Penal</span>: <span class=\"ref-concepto\">\"Las disposiciones relativas a la responsabilidad penal de las personas jurídicas no serán aplicables al Estado, a las Administraciones públicas territoriales e institucionales, a los Organismos Reguladores, las Agencias y Entidades públicas Empresariales, a las organizaciones internacionales de derecho público\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1127","p":"Código Penal. Exclusión de la responsabilidad penal de personas jurídicas. Las disposiciones relativas a la responsabilidad penal de las personas jurídicas no serán aplicables a:","o":["el Estado y las Administraciones públicas territoriales, pero sí a las institucionales, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente.","el Estado, las Administraciones públicas y las Sociedades mercantiles públicas.","el Estado, las Administraciones públicas territoriales e institucionales, los Organismos Reguladores, las Agencias y Entidades públicas Empresariales.","los partidos políticos y los sindicatos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el Estado, las Administraciones públicas territoriales e institucionales, los Organismos Reguladores, las Agencias y Entidades públicas Empresariales</mark></span>El <span class=\"ref-norma\">art. 31 quinquies.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"no serán aplicables al Estado, a las Administraciones públicas territoriales e institucionales, a los Organismos Reguladores, las Agencias y Entidades públicas Empresariales\"</span>. No se aplican al Estado ni a las Administraciones públicas territoriales e institucionales, entre otros. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 115","q":[{"i":"18-5","p":"Código Penal. De la responsabilidad civil y su extensión. Señale la INCORRECTA:","o":["Los Jueces y Tribunales al declarar la existencia de responsabilidad civil, establecerán razonadamente, en sus resoluciones las bases en que fundamenten la cuantía de los daños e indemnizaciones, pudiendo haber sido reclamadas en el momento de cumplimiento.","La responsabilidad civil exige el cumplimiento de obligaciones de dar, de hacer o de no hacer que el Juez o Tribunal establecen atendiendo a la naturaleza de aquél y a las condiciones personales y patrimoniales del culpable, determinando si han de ser cumplidas por el mismo o pueden ser ejecutadas a su costa.","La indemnización de perjuicios materiales y morales comprenderá no sólo los que se hubiesen causado al agraviado, sino también los que se hubiesen irrogado a sus familiares o a terceros.","Debe restituirse, siempre que sea posible, el mismo bien, con abono de los deterioros y menoscabos que el juez o tribunal determinen. La restitución tendrá lugar aunque el bien se halle en poder de tercero y éste lo haya adquirido legalmente y de buena fe, dejando a salvo su derecho de repetición contra quien corresponda, en su caso, el de ser indemnizado por el responsable civil del delito."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los Jueces y Tribunales al declarar la existencia de responsabilidad civil, establecerán razonadamente, en sus resoluciones las bases en qu…</mark></span>- Los daños deben ser reclamados durante el proceso, no en el momento de cumplimiento."},{"i":"18-139","p":"Código Penal. ¿Qué deben establecer razonadamente los Jueces y Tribunales al declarar la existencia de responsabilidad civil?","o":["Las bases para la cuantía de los daños o indemnizaciones.","La responsabilidad de la víctima.","El momento de ejecución de la indemnización.","Las circunstancias del daño causado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las bases para la cuantía de los daños o indemnizaciones.</mark></span>(Deben establecer las bases para determinar la cuantía de los daños e indemnizaciones)."}]},{"a":"Artículo 31 quater ✱","q":[{"i":"18-6","p":"Código Penal. Sólo podrán considerarse circunstancias atenuantes de la responsabilidad penal de las personas jurídicas haber realizado, con posterioridad a la comisión del delito y a través de sus representantes legales, las siguientes actividades: señale la INCORRECTA.","o":["Haber procedido, después de conocer que el procedimiento judicial se dirige contra ella, a confesar la infracción a las autoridades.","Haber colaborado en la investigación del hecho aportando pruebas, en cualquier momento del proceso, que fueran nuevas y decisivas para esclarecer las responsabilidades penales dimanantes de los hechos.","Haber procedido en cualquier momento del procedimiento y con anterioridad al juicio oral a reparar o disminuir el daño causado por el delito.","Haber establecido, antes del comienzo del juicio oral, medidas eficaces para prevenir y descubrir los delitos que en el futuro pudieran cometerse con los medios o bajo la cobertura de la persona jurídica."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Haber procedido, después de conocer que el procedimiento judicial se dirige contra ella, a confesar la infracción a las autoridades.</mark></span>- La confesión debe ser anterior al conocimiento del procedimiento judicial, no posterior."},{"i":"18-209","p":"Código Penal. Sólo podrán considerarse circunstancias atenuantes de la responsabilidad penal de las personas jurídicas haber realizado, con posterioridad a la comisión del delito y a través de sus representantes legales, las siguientes actividades. Indique la CORRECTA:","o":["Haber establecido, después del comienzo del juicio oral, medidas eficaces para prevenir y descubrir los delitos que en el futuro pudieran cometerse con los medios o bajo la cobertura de la persona jurídica.","Haber colaborado en la investigación del hecho aportando pruebas, en cualquier momento del proceso, que fueran nuevas y decisivas para endurecer las responsabilidades penales dimanantes de los hechos.","Haber procedido, en cualquier momento del procedimiento y con anterioridad al juicio oral, a reparar o disminuir el daño causado por el delito.","Haber colaborado en la investigación del hecho aportando pruebas parciales para endurecer las responsabilidades penales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Haber procedido, en cualquier momento del procedimiento y con anterioridad al juicio oral, a reparar o disminuir el daño causado por el delito</mark></span>Según el <span class=\"ref-norma\">art. 31 quater del Código Penal</span>: <span class=\"ref-concepto\">\"Haber procedido en cualquier momento del procedimiento y con anterioridad al juicio oral a reparar o disminuir el daño causado por el delito\"</span> (verificado con el texto del temario oficial)."},{"i":"18-253","p":"Código Penal. Atenuantes de las personas jurídicas. Sólo podrán considerarse circunstancias atenuantes de la responsabilidad penal de las personas jurídicas haber colaborado en la investigación del hecho aportando pruebas, en cualquier momento del proceso, que fueran nuevas y decisivas para:","o":["Acreditar la inexistencia del deber de supervisión, vigilancia y control.","Determinar la cuantía de la multa que corresponda a la persona jurídica.","Demostrar la participación de sus representantes legales en el delito.","Esclarecer las responsabilidades penales dimanantes de los hechos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Esclarecer las responsabilidades penales dimanantes de los hechos</mark></span>El <span class=\"ref-norma\">art. 31 quater.b) de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"Haber colaborado en la investigación del hecho aportando pruebas, en cualquier momento del proceso, que fueran nuevas y decisivas para esclarecer las responsabilidades penales dimanantes de los hechos\"</span>"},{"i":"18-ia-1125","p":"Código Penal. Atenuantes de las personas jurídicas. Sólo podrán considerarse circunstancias atenuantes de la responsabilidad penal de las personas jurídicas haber realizado, con posterioridad a la comisión del delito y a través de sus representantes legales, determinadas actividades. Señale la INCORRECTA:","o":["Haber procedido a indemnizar a las víctimas en el plazo de un año desde la comisión del delito.","Haber procedido, antes de conocer que el procedimiento judicial se dirige contra ella, a confesar la infracción a las autoridades.","Haber colaborado en la investigación del hecho aportando pruebas, en cualquier momento del proceso, que fueran nuevas y decisivas para esclarecer las responsabilidades penales.","Haber establecido, antes del comienzo del juicio oral, medidas eficaces para prevenir y descubrir los delitos que en el futuro pudieran cometerse con los medios o bajo la cobertura de la persona jurídica."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Haber procedido a indemnizar a las víctimas en el plazo de un año desde la comisión del delito</mark></span>El <span class=\"ref-norma\">art. 31 quater.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"c) Haber procedido en cualquier momento del procedimiento y con anterioridad al juicio oral a reparar o disminuir el daño causado por el delito\"</span>. La atenuante es reparar o disminuir el daño en cualquier momento del procedimiento y antes del juicio oral; no hay plazo de un año. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1126","p":"Código Penal. Atenuantes de las personas jurídicas. Es circunstancia atenuante de la responsabilidad penal de las personas jurídicas haber establecido, antes del comienzo del juicio oral, medidas eficaces para:","o":["sancionar disciplinariamente a quienes hayan cometido el delito en su seno.","prevenir los delitos que en el futuro pudieran cometerse por sus representantes legales, en los términos que se determinen reglamentariamente.","reparar el daño causado a las víctimas y colaborar con las autoridades.","prevenir y descubrir los delitos que en el futuro pudieran cometerse con los medios o bajo la cobertura de la persona jurídica."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">prevenir y descubrir los delitos que en el futuro pudieran cometerse con los medios o bajo la cobertura de la persona jurídica</mark></span>El <span class=\"ref-norma\">art. 31 quater.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"d) Haber establecido, antes del comienzo del juicio oral, medidas eficaces para prevenir y descubrir los delitos que en el futuro pudieran cometerse con los medios o bajo la cobertura de la persona jurídica\"</span>. Medidas eficaces para prevenir y descubrir futuros delitos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 116","q":[{"i":"18-8","p":"Código Penal. Toda persona criminalmente responsable de un delito:","o":["Lo es también civilmente salvo que del hecho no se deriven daños o perjuicios.","Lo es también civilmente si del hecho se derivan daños o perjuicios.","Lo es también civilmente si incluyen la víctima o el perjudicado.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Lo es también civilmente si del hecho se derivan daños o perjuicios.</mark></span>- La responsabilidad civil deriva de la existencia de daños o perjuicios causados por el delito."},{"i":"18-17","p":"Código Penal. Los autores y los cómplices, cada uno dentro de su respectiva clase, serán responsables:","o":["Subsidiariamente entre sí por sus cuotas.","Subsidiariamente por las correspondientes a los demás responsables.","Solidariamente entre sí por sus cuotas, y subsidiariamente por las correspondientes a los demás responsables.","A y B son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Solidariamente entre sí por sus cuotas, y subsidiariamente por las correspondientes a los demás responsables</mark></span>Solidarios entre sí por sus cuotas y subsidiarios por las de los demás. Según el <span class=\"ref-norma\">art. 116 del Código Penal</span>: <span class=\"ref-concepto\">\"serán responsables solidariamente entre sí por sus cuotas, y subsidiariamente por las correspondientes a los demás responsables\"</span> (verificado con el texto del temario oficial)."},{"i":"18-42","p":"Código Penal. Responsabilidad civil y su extensión. Los autores y los cómplices, cada uno dentro de su respectiva clase, serán responsables:","o":["Solidariamente personalmente, y subsidiariamente por las correspondientes a los demás responsables","Subsidiariamente entre sí por sus cuotas, y subsidiariamente por las correspondientes a los demás responsables","Solidariamente entre sí por sus cuotas, y subsidiariamente por las correspondientes a los demás responsables","Ninguna es correcta"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Solidariamente entre sí por sus cuotas, y subsidiariamente por las correspondientes a los demás responsables</mark></span>- Responden solidariamente dentro de su clase y subsidiariamente por los demás responsables."},{"i":"18-ia-1438","p":"Código Penal. Personas civilmente responsables. Toda persona criminalmente responsable de un delito lo es también civilmente si del hecho se derivaren daños o perjuicios. Si son dos o más los responsables de un delito:","o":["responderán todos por partes iguales.","responderá en primer lugar el autor y después los cómplices por partes iguales.","el Ministerio Fiscal propondrá el reparto de las cuotas.","los jueces o tribunales señalarán la cuota de que deba responder cada uno."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los jueces o tribunales señalarán la cuota de que deba responder cada uno</mark></span>El <span class=\"ref-norma\">art. 116.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Si son dos o más los responsables de un delito los jueces o tribunales señalarán la cuota de que deba responder cada uno\"</span>. Los jueces o tribunales señalan la cuota de cada uno. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1439","p":"Código Penal. Personas civilmente responsables. Los autores y los cómplices, cada uno dentro de su respectiva clase, serán responsables:","o":["subsidiariamente entre sí por sus cuotas, y solidariamente por las correspondientes a los demás responsables, sin perjuicio de lo previsto en la normativa vigente.","mancomunadamente por sus cuotas, sin responsabilidad por las de los demás.","solidariamente entre sí por sus cuotas, y subsidiariamente por las correspondientes a los demás responsables.","solidariamente por todas las cuotas, sin distinción de clases."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">solidariamente entre sí por sus cuotas, y subsidiariamente por las correspondientes a los demás responsables</mark></span>El <span class=\"ref-norma\">art. 116.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"serán responsables solidariamente entre sí por sus cuotas, y subsidiariamente por las correspondientes a los demás responsables\"</span>. Solidarios dentro de su clase por sus cuotas y subsidiarios por las de los demás. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1440","p":"Código Penal. Personas civilmente responsables. La responsabilidad subsidiaria se hará efectiva:","o":["primero, en los bienes de los cómplices, y después, en los de los autores.","primero, en los bienes de los autores, y después, en los de los cómplices.","simultáneamente, en los bienes de autores y cómplices.","primero, en los bienes del responsable civil directo, y después, en los de los autores."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">primero, en los bienes de los autores, y después, en los de los cómplices</mark></span>El <span class=\"ref-norma\">art. 116.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La responsabilidad subsidiaria se hará efectiva: primero, en los bienes de los autores, y después, en los de los cómplices\"</span>. Primero autores y después cómplices. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1441","p":"Código Penal. Personas civilmente responsables. La responsabilidad penal de una persona jurídica llevará consigo su responsabilidad civil en los términos establecidos en el Código de forma:","o":["solidaria con las personas físicas que fueren condenadas por los mismos hechos.","subsidiaria respecto de las personas físicas que fueren condenadas por los mismos hechos.","mancomunada con las personas físicas condenadas por los mismos hechos.","directa y exclusiva, sin responsabilidad de las personas físicas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">solidaria con las personas físicas que fueren condenadas por los mismos hechos</mark></span>El <span class=\"ref-norma\">art. 116.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"llevará consigo su responsabilidad civil en los términos establecidos en el artículo 110 de este Código de forma solidaria con las personas físicas que fueren condenadas por los mismos hechos\"</span>. Solidaria con las personas físicas condenadas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 22 EX","q":[{"i":"18-9","p":"Ley Orgánica 10/1995 de 23 de noviembre, del Código Penal. Son circunstancias agravantes:","o":["Ejecutar el hecho con alevosía.","Ejecutar el hecho con premeditación.","Ejecutar el hecho con nocturnidad.","Todas las opciones son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Ejecutar el hecho con alevosía</mark></span>La premeditación y la nocturnidad no figuran como agravantes. Según el <span class=\"ref-norma\">art. 22 del Código Penal</span>: <span class=\"ref-concepto\">\"1.ª Ejecutar el hecho con alevosía\"</span> (verificado con el texto del temario oficial)."},{"i":"18-106","p":"Ley Orgánica 10/1995, de 23 de noviembre, del Código Penal. Son circunstancias agravantes: Señale la correcta.","o":["Prevalerse del carácter privado que tenga el culpable.","Obrar con abuso de autoridad.","Ejecutar el hecho mediante disfraz, con abuso de superioridad o aprovechando las circunstancias de lugar, tiempo o auxilio de otras personas que debiliten la defensa del ofendido o faciliten la impunidad del delincuente.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Ejecutar el hecho mediante disfraz, con abuso de superioridad o aprovechando las circunstancias de lugar, tiempo o auxilio de otras personas que debiliten la defensa del ofendido o faciliten la impunidad del delincuente</mark></span>Según el <span class=\"ref-norma\">art. 22 del Código Penal</span>: <span class=\"ref-concepto\">\"2.ª Ejecutar el hecho mediante disfraz, con abuso de superioridad o aprovechando las circunstancias de lugar, tiempo o auxilio de otras personas que debiliten la defensa del ofendido o faciliten la impunidad del delincuente\"</span> (verificado con el texto del temario oficial)."},{"i":"18-131","p":"Código Penal. ¿Qué caracteriza la alevosía en la ejecución de un delito?","o":["La premeditación y la planificación detallada del delito.","El empleo en la ejecución de medios, modos o formas que tiendan directa o especialmente a asegurarla, sin el riesgo que para su persona pudiera proceder de la defensa por parte del ofendido.","La habitualidad en delitos similares.","La colaboración de dos o más personas en la ejecución del delito."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El empleo en la ejecución de medios, modos o formas que tiendan directa o especialmente a asegurarla, sin el riesgo que para su persona pud…</mark></span> (Esta es la definición legal de alevosía como circunstancia agravante). TEST 10"},{"i":"18-148","p":"Código Penal. ¿Cuál de las siguientes afirmaciones sobre la reincidencia es CORRECTA?","o":["Se considera reincidente al culpable que ha sido condenado por cualquier delito anterior, sin importar su naturaleza.","La reincidencia se aplica incluso si los antecedentes penales han sido cancelados o deberán haberlo sido.","Las condenas en otros Estados de la Unión Europea no tienen efecto en la reincidencia según el Derecho español.","La reincidencia exige que, al delinquir, el culpable haya sido condenado ejecutoriamente por un delito comprendido en el mismo título de este Código, siempre que sea de la misma naturaleza."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La reincidencia exige que, al delinquir, el culpable haya sido condenado ejecutoriamente por un delito comprendido en el mismo título de es…</mark></span>(La reincidencia requiere condena anterior por delito del mismo título y naturaleza)."},{"i":"18-196","p":"Código Penal. De las circunstancias que agravan la responsabilidad criminal. Es una circunstancia agravante ejecutar el hecho con alevosía. Hay alevosía cuando:","o":["El culpable comete cualquier daño, empleando en la ejecución medios, modos o formas que tiendan directa o especialmente a asegurarla, sin el riesgo que para su persona pudiera proceder de la defensa por parte del ofendido.","El culpable comete cualquier daño, empleando en la ejecución medios, modos o formas que tiendan directa o especialmente a asegurarla, asumiendo conscientemente el riesgo que para su persona pudiera proceder de la defensa por parte del ofendido.","El culpable comete cualquier daño, empleando en la ejecución medios, modos o formas que tiendan indirectamente a asegurarla, sin el riesgo que para su persona pudiera proceder de la defensa por parte del ofendido.","El culpable comete cualquier daño de forma imprudente, sin que medien medios, modos o formas que tiendan a asegurar la ejecución del hecho."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El culpable comete cualquier daño, empleando en la ejecución medios, modos o formas que tiendan directa o especialmente a asegurarla, sin e…</mark></span><span class=\"ref-norma\">Art. 22.1 · De las Penas</span>. (y b y d, ya que son idénticas). La definición correcta de alevosía (Artículo 22.1 CP) es cuando se emplean medios, modos o formas en la ejecución que tiendan directa y especialmente a asegurarla, sin riesgo para el agresor por la defensa del ofendido. Las opciones a, b y d, aunque repetidas, contienen esta definición correcta. La c) es incorrecta al decir &quot;indirectamente&quot;.*"},{"i":"18-215","p":"Código Penal. Son circunstancias agravantes... indique la respuesta INCORRECTA.","o":["Ejecutar el hecho con alevosía.","Ejecutar el hecho mediante disfraz, con abuso de superioridad o aprovechando las circunstancias de lugar, tiempo o auxilio de otras personas que debiliten la defensa del ofendido o faciliten la impunidad del delincuente.","Ejecutar el hecho mediante negativa a declarar.","Obrar con abuso de confianza."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Ejecutar el hecho mediante negativa a declarar.</mark></span><span class=\"ref-norma\">Art. 22 · De las Circunstancias que Modifican la Responsabilidad Criminal</span>. (La &quot;negativa a declarar&quot; no está contemplada como circunstancia agravante en el Artículo 22 del CP. Es un derecho fundamental)."},{"i":"18-ia-1059","p":"Código Penal. Agravantes. Hay alevosía cuando el culpable comete cualquiera de los delitos contra las personas empleando en la ejecución medios, modos o formas que tiendan directa o especialmente a asegurarla, sin el riesgo que para su persona pudiera proceder de:","o":["la intervención de terceras personas.","la resistencia del ofendido o de terceros.","la defensa por parte del ofendido.","la reacción de la autoridad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la defensa por parte del ofendido</mark></span>El <span class=\"ref-norma\">art. 22.1ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"sin el riesgo que para su persona pudiera proceder de la defensa por parte del ofendido\"</span>. Alevosía: sin riesgo derivado de la defensa del ofendido. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1060","p":"Código Penal. Agravantes. Es circunstancia agravante ejecutar el hecho mediante disfraz, con abuso de superioridad o aprovechando las circunstancias de lugar, tiempo o auxilio de otras personas que:","o":["anulen la defensa del ofendido o aseguren la impunidad del delincuente.","debiliten la defensa del ofendido o faciliten la impunidad del delincuente.","debiliten la defensa del ofendido, aunque no faciliten la impunidad.","faciliten la comisión del delito o dificulten la identificación del delincuente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">debiliten la defensa del ofendido o faciliten la impunidad del delincuente</mark></span>El <span class=\"ref-norma\">art. 22.2ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"que debiliten la defensa del ofendido o faciliten la impunidad del delincuente\"</span>. Debilitan la defensa o facilitan la impunidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1061","p":"Código Penal. Agravantes. Es circunstancia agravante ejecutar el hecho mediante:","o":["precio, recompensa o promesa.","precio o recompensa, con exclusión de la promesa.","engaño, precio o recompensa.","ánimo de lucro, precio o promesa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">precio, recompensa o promesa</mark></span>El <span class=\"ref-norma\">art. 22.3ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Ejecutar el hecho mediante precio, recompensa o promesa\"</span>. Precio, recompensa o promesa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1062","p":"Código Penal. Agravantes. Señale la INCORRECTA. Es circunstancia agravante cometer el delito por motivos racistas, antisemitas, antigitanos u otra clase de discriminación referente a:","o":["la ideología, religión o creencias de la víctima.","la orientación o identidad sexual o de género, razones de género, de aporofobia o de exclusión social.","la enfermedad que padezca o su discapacidad.","la nacionalidad política del ofendido."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la nacionalidad política del ofendido</mark></span>El <span class=\"ref-norma\">art. 22.4ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"motivos racistas, antisemitas, antigitanos u otra clase de discriminación referente a la ideología, religión o creencias de la víctima, la etnia, raza o nación a la que pertenezca, su sexo, edad, orientación o identidad sexual o de género, razones de género, de aporofobia o de exclusión social, la enfermedad que padezca o su discapacidad\"</span>. La «nacionalidad política» no figura entre los motivos de discriminación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1063","p":"Código Penal. Agravantes. Es circunstancia agravante aumentar deliberada e inhumanamente el sufrimiento de la víctima, causando a ésta:","o":["lesiones de especial gravedad.","padecimientos que excedan de los necesarios para su ejecución.","padecimientos innecesarios para la ejecución del delito.","daños físicos o psíquicos permanentes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">padecimientos innecesarios para la ejecución del delito</mark></span>El <span class=\"ref-norma\">art. 22.5ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"causando a ésta padecimientos innecesarios para la ejecución del delito\"</span>. Padecimientos innecesarios para la ejecución del delito. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1064","p":"Código Penal. Agravantes. Hay reincidencia cuando, al delinquir, el culpable haya sido condenado ejecutoriamente por un delito comprendido en el mismo título de este código, siempre que sea:","o":["de igual gravedad.","de la misma naturaleza.","doloso.","castigado con pena grave."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">de la misma naturaleza</mark></span>El <span class=\"ref-norma\">art. 22.8ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"por un delito comprendido en el mismo título de este código, siempre que sea de la misma naturaleza\"</span>. Mismo título del Código y misma naturaleza. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1065","p":"Código Penal. Agravantes. A los efectos de la reincidencia no se computarán los antecedentes penales cancelados o que debieran serlo, ni los que correspondan a:","o":["delitos leves, salvo lo dispuesto para los tipos agravados por multirreincidencia de delitos leves.","delitos imprudentes, salvo lo dispuesto para los tipos agravados por multirreincidencia, salvo que la autoridad judicial disponga otra cosa.","delitos menos graves, salvo que la pena impuesta hubiera sido de prisión.","delitos leves, sin excepción alguna."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">delitos leves, salvo lo dispuesto para los tipos agravados por multirreincidencia de delitos leves</mark></span>El <span class=\"ref-norma\">art. 22.8ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"ni los que correspondan a delitos leves, salvo lo dispuesto para los tipos agravados por multirreincidencia de delitos leves\"</span>. No se computan los de delitos leves, con la salvedad de la multirreincidencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1066","p":"Código Penal. Agravantes. Las condenas firmes de jueces o tribunales impuestas en otros Estados de la Unión Europea producirán los efectos de reincidencia salvo que el antecedente penal haya sido:","o":["cancelado con arreglo al Derecho del Estado que las impuso.","cumplido íntegramente antes de la comisión del nuevo delito.","impuesto por un delito no tipificado en el Derecho español.","cancelado o pudiera serlo con arreglo al Derecho español."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">cancelado o pudiera serlo con arreglo al Derecho español</mark></span>El <span class=\"ref-norma\">art. 22.8ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"salvo que el antecedente penal haya sido cancelado o pudiera serlo con arreglo al Derecho español\"</span>. Cancelación conforme al Derecho español. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"RECUERDA del temario · Código Penal (R11 a R20) R11 R12 R13 R14 R15 R16 R17 R18 R19 R20","q":[{"i":"18-10","p":"Código Penal. La provocación existe:","o":["Cuando se exponen a una o varias personas, ideas o doctrinas que ensalcen el crimen","Cuando directamente se incita a una o varias personas a perpetuar un hecho delictivo","Cuando directamente se incita por medio de la imprenta, la radiodifusión o cualquier otro medio de eficacia semejante, que facilite la publicidad o ante una concurrencia de personas, a la perpetración de un delito.","Cuando se exponen por medio de la imprenta, radiodifusión o medio semejante que facilite la publicidad o ante una concurrencia de personas, ideas o doctrinas que ensalcen el crimen"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cuando directamente se incita por medio de la imprenta, la radiodifusión o cualquier otro medio de eficacia semejante, que facilite la publ…</mark></span>- La provocación requiere incitación directa mediante medios de publicidad."},{"i":"18-20","p":"Código Penal. Será calificada, como pena menos grave, la prohibición de aproximarse a la víctima o a aquellos de sus familiares u otras personas que determine el juez o tribunal, por tiempo de:","o":["Hasta seis meses.","Hasta un año.","De uno a cinco años.","De seis meses a tres años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">De uno a cinco años.</mark></span>- La prohibición de aproximación de 1 a 5 años se considera pena menos grave."},{"i":"18-31","p":"Código Penal. De las medidas de seguridad. Las medidas de seguridad que se pueden imponer con arreglo a este Código son:","o":["Privativas y no privativas de libertad.","Privativas, no privativas de libertad y multa.","Privativas, no privativas de libertad y localización permanente.","Privativas, no privativas de libertad y la responsabilidad penal subsidiaria por impago de multas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Privativas y no privativas de libertad.</mark></span>- Las medidas de seguridad pueden ser privativas o no privativas de libertad."},{"i":"18-43","p":"Código Penal. De los delitos. La exposición, ante una concurrencia de personas o por cualquier medio de difusión, de ideas o doctrinas que ensalcen el crimen o enaltezcan a su autor se considera:","o":["Comprensión","Apología","Redacción","Prosecución"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Apología</mark></span>- Se considera apología del delito."},{"i":"18-70","p":"Código Penal. De las multas. La cuota diaria de las multas impuestas a las personas jurídicas tendrá un mínimo de 30 y un máximo de:","o":["3000 euros","6000 euros","2000 euros","5000 euros"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">5000 euros</mark></span>- La cuota diaria para personas jurídicas va de 30 a 5000 euros."},{"i":"18-84","p":"Código Penal. De las penas. Respecto a la pena de multa, ¿qué pena de multa podrá imponerse a personas físicas?:","o":["Pena de 15 días de multa con cuota de un euro diario","Pena de 7 días de multa con cuota de 350 euros diarios","Pena de 30 días de multa con cuota de quinientos euros diarios","Pena de dos años de multa con cuota de cuatrocientos euros diarios"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Pena de dos años de multa con cuota de cuatrocientos euros diarios</mark></span>Extensión: de diez días a dos años; cuota: de 2 a 400 euros. Una cuota de 500 euros excede el máximo; 15 días con 1 euro y 7 días no alcanzan los mínimos. Según el <span class=\"ref-norma\">art. 50 del Código Penal</span>: <span class=\"ref-concepto\">\"La cuota diaria tendrá un mínimo de dos y un máximo de 400 euros\"</span> (verificado con el texto del temario oficial)."},{"i":"18-89","p":"Código Penal. De las penas privativas de libertad. Son penas privativas de libertad:","o":["La responsabilidad personal subsidiaria por impago de multa","La privación del derecho a la tenencia y porte de armas","La privación del derecho a residir en determinados lugares o acudir a ellos","La prisión permanente revisable"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La prisión permanente revisable</mark></span>- La prisión permanente revisable es pena privativa de libertad."},{"i":"18-96","p":"Código Penal. De las personas criminalmente responsables de los delitos. También serán considerados autores:","o":["Los que inducen directamente a otro u otros a ejecutarlo.","Los que cooperan a su ejecución con un acto sin el cual no se habría efectuado.","Los cómplices.","A y B son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>Los cómplices (art. 29) no son autores. Según el <span class=\"ref-norma\">art. 28 del Código Penal</span>: <span class=\"ref-concepto\">\"También serán considerados autores: a) Los que inducen directamente a otro u otros a ejecutarlo. b) Los que cooperan a su ejecución con un acto sin el cual no se habría efectuado\"</span> (verificado con el texto del temario oficial)."},{"i":"18-98","p":"Código Penal. De las penas, sus clases y efectos. ¿En qué tipo de penas se incluyen las inhabilitaciones especiales por tiempo superior a cinco años?:","o":["Esta pena no está recogida en el Código Penal","Penas graves","Penas leves","Penas menos graves"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Penas graves</mark></span>- Las inhabilitaciones especiales superiores a 5 años son penas graves."},{"i":"18-134","p":"Código Penal. NO se reputarán penas: señale la INCORRECTA.","o":["La detención y prisión preventiva y las demás medidas cautelares de naturaleza penal.","Las multas de hasta tres meses.","Las privaciones de derechos que establezcan las leyes civiles o administrativas.","Las sanciones reparadoras que establezcan las leyes civiles o administrativas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Las multas de hasta tres meses.</mark></span>(Las multas sí son penas, mientras que las otras opciones no se reputan penas)."},{"i":"18-140","p":"Código Penal. ¿Cuál es el plazo necesario para que una persona condenada por un delito leve pueda solicitar la cancelación de sus antecedentes penales?","o":["Seis meses.","Un año.","Dos años.","Cinco años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Seis meses.</mark></span>(Para delitos leves, el plazo de cancelación es de seis meses)."},{"i":"18-150","p":"Código Penal. NO son penas menos graves:","o":["La prisión de tres meses hasta cinco años.","Las penas que no sean graves ni leves.","Las penas de localización permanente de hasta cinco años.","Las penas de trabajos en beneficio de la comunidad de hasta 360 días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La prisión de tres meses hasta cinco años.</mark></span> (La prisión de tres meses a cinco años SÍ es pena menos grave, por lo que esta opción es incorrecta). TEST 11"},{"i":"18-153","p":"Código Penal. ¿Quiénes son considerados cómplices?:","o":["Los que realizan el hecho por sí solos.","Los que inducen directamente a otro a ejecutar el hecho.","Los que no siendo autores cooperan a la ejecución del hecho con actos anteriores o simultáneos.","Los que son testigos del hecho."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los que no siendo autores cooperan a la ejecución del hecho con actos anteriores o simultáneos.</mark></span>(Los cómplices son quienes cooperan en la ejecución del delito sin ser autores)."},{"i":"18-173","p":"Código Penal. De las penas y sus clases. Las penas que pueden imponerse con arreglo a este Código, bien con carácter principal bien como accesorias, son:","o":["Privativas de libertad.","Privativas de otros derechos.","Multas.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span>(El Código Penal establece estos tres tipos de penas)."},{"i":"18-178","p":"Código penal. De las personas criminalmente responsables de los delitos. Señale la INCORRECTA:","o":["Son responsables criminalmente de los delitos los autores y los cómplices.","Son autores quienes realizan el hecho por sí solos, conjuntamente o por medio de otro del que se sirven como instrumento.","Serán considerados autores los que cooperen en la ejecución del delito.","Serán considerados autores los que induzcan directamente a otro u otros a ejecutarlo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Serán considerados autores los que cooperen en la ejecución del delito.</mark></span>(Quienes cooperan en la ejecución son cómplices, no autores)."},{"i":"18-192","p":"Código Penal. Si a la provocación hubiese seguido la perpetración del delito, se castigará como:","o":["Consecución.","Proposición.","Apología.","Inducción. *"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Inducción. *</mark></span><span class=\"ref-norma\">Art. 18 · De las Personas Criminalmente Responsables de los Delitos</span>. Inducción. (Según el Artículo 18 del Código Penal, si los actos de provocación, conspiración o proposición son seguidos de la perpetración del delito, se castigarán exclusivamente como autores o cómplices del delito cometido. La &quot;inducción&quot; es una forma de autoría).*"},{"i":"18-198","p":"Código Penal. A los efectos penales se reputará ______ al que por sí solo o como miembro de alguna corporación, tribunal u órgano colegiado tenga mando o ejerza jurisdicción propia.","o":["Agente de la autoridad.","Autoridad.","Miembro de la autoridad.","Funcionario público. *"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Autoridad.</mark></span><span class=\"ref-norma\">Art. 24 · De las Penas</span>. Autoridad. (La definición proviene del Artículo 24 del Código Penal).*"},{"i":"18-199","p":"Código Penal. De la pena de multa. Su extensión mínima será de diez días y la máxima de:","o":["Dos años.","Un año.","Siete meses.","Cinco años. *"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Dos años.</mark></span><span class=\"ref-norma\">Art. 50.1 · De las Penas</span>. Dos años. (Según el Artículo 50.1 del Código Penal, la multa tendrá una duración mínima de diez días y máxima de dos años).*"},{"i":"18-210","p":"Código Penal. Señale la respuesta INCORRECTA: Las penas que pueden imponerse con arreglo a este Código, bien con carácter principal bien como accesorias, son:","o":["Privativas de libertad","Privativas de otros derechos","Privativas de deberes","Multa"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Privativas de deberes</mark></span><span class=\"ref-norma\">Art. 33 · De las Penas</span>. (El Artículo 33 del CP clasifica las penas en privativas de libertad, privativas de otros derechos y multa. No existe la categoría &quot;privativas de deberes&quot;)."},{"i":"18-213","p":"Código Penal. Las penas de suspensión de empleo o cargo público, ¿qué duración tendrán? Señala la opción CORRECTA:","o":["De tres meses a un año.","De tres meses a cinco años.","De tres meses a seis años.","De tres meses a quince años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">De tres meses a seis años.</mark></span><span class=\"ref-norma\">Art. 42 · De las Penas</span>. (Según el Artículo 42 del CP, la duración de la suspensión de empleo o cargo público es de tres meses a seis años)."},{"i":"18-221","p":"Código Penal. El tribunal, por causa justificada, podrá autorizar el pago de la multa dentro de un plazo que no exceda de __ desde la firmeza de la sentencia, bien de una vez o en los plazos que se determinen.","o":["Dos años","Un año","Tres años","Cinco años"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Dos años</mark></span><span class=\"ref-norma\">Art. 52 · De las Penas</span>. (El Artículo 52 del CP establece un plazo máximo de dos años para el pago fraccionado de la multa)."},{"i":"18-232","p":"Código Penal. La localización permanente tendrá una duración de:","o":["Más de seis meses.","Hasta seis meses.","Hasta tres meses.","Hasta doce meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Hasta seis meses.</mark></span><span class=\"ref-norma\">Art. 37.2 · De las Penas</span>. (El Artículo 37.2 del CP establece que la localización permanente tiene una duración de un día a seis meses)."},{"i":"18-233","p":"Código Penal. De las penas privativas de libertad. La localización permanente tendrá una duración de hasta ______.","o":["Cuatro meses.","Tres meses.","Seis meses.","Cinco meses."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Seis meses.</mark></span><span class=\"ref-norma\">Art. 37.2 · De las Penas</span>. (Confirmado por el Artículo 37.2 del CP, la duración máxima es de seis meses)."},{"i":"18-246","p":"Código Penal. Se entenderá que el delito se ha cometido en el contexto de una actividad delictiva continuada siempre que en el período de ______ anterior al momento en que se inició el procedimiento en el que ha sido condenado, hubiera sido condenado por dos o más delitos de los que hubiera derivado la obtención de un beneficio económico, o por un delito continuado que incluya, al menos, dos infracciones penales de las que ha derivado la obtención de un beneficio económico.","o":["Siete años.","Cinco años.","Tres años.","Dos años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cinco años.</mark></span><span class=\"ref-norma\">Art. 301.3 · De las Penas</span>. (El Artículo 301.3 del CP establece un período de cinco años para esta consideración)."},{"i":"18-251","p":"Código Penal. Provocación. Si a la provocación hubiese seguido la perpetración del delito, se castigará como:","o":["Conspiración.","Inducción.","Proposición.","Apología."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Inducción</mark></span>El <span class=\"ref-norma\">art. 18.2 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"Si a la provocación hubiese seguido la perpetración del delito, se castigará como inducción\"</span>"},{"i":"18-261","p":"Código Penal. Penas de las personas jurídicas. La clausura de los locales y establecimientos de la persona jurídica se impondrá por un plazo que no podrá exceder de:","o":["Quince años.","Diez años.","Tres años.","Cinco años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cinco años</mark></span>El <span class=\"ref-norma\">art. 33.7.d) de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"Clausura de sus locales y establecimientos por un plazo que no podrá exceder de cinco años\"</span>"},{"i":"18-264","p":"Código Penal. Pena de multa. La pena de multa tendrá una extensión mínima de diez días y máxima de dos años. Las penas de multa imponibles a personas jurídicas tendrán una extensión máxima de:","o":["Cinco años.","Tres años, en los términos que determine la ley orgánica correspondiente.","Diez años.","Dos años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cinco años</mark></span>El <span class=\"ref-norma\">art. 50.3 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"Su extensión mínima será de diez días y la máxima de dos años. Las penas de multa imponibles a personas jurídicas tendrán una extensión máxima de cinco años\"</span>"},{"i":"18-ia-1038","p":"Código Penal. Provocación y apología. La provocación se castigará exclusivamente en los casos en que la Ley así lo prevea. Si a la provocación hubiese seguido la perpetración del delito:","o":["se castigará como cooperación necesaria.","se castigará como encubrimiento.","se castigará como conspiración.","se castigará como inducción."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">se castigará como inducción</mark></span>El <span class=\"ref-norma\">art. 18.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Si a la provocación hubiese seguido la perpetración del delito, se castigará como inducción\"</span>. Provocación seguida del delito = inducción. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1103","p":"Código Penal. Autores. Señale la INCORRECTA. También serán considerados autores:","o":["Los que inducen directamente a otro u otros a ejecutarlo.","Los que cooperan a su ejecución con un acto sin el cual no se habría efectuado.","Los que cooperan a su ejecución con un acto anterior o simultáneo.","Los que realizan el hecho por medio de otro del que se sirven como instrumento."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los que cooperan a su ejecución con un acto anterior o simultáneo</mark></span>El <span class=\"ref-norma\">art. 28 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"También serán considerados autores: a) Los que inducen directamente a otro u otros a ejecutarlo. b) Los que cooperan a su ejecución con un acto sin el cual no se habría efectuado\"</span>. La cooperación con actos anteriores o simultáneos es complicidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1104","p":"Código Penal. Autores. Los que cooperan a la ejecución de un hecho con un acto sin el cual no se habría efectuado son considerados:","o":["cómplices.","autores.","encubridores.","cómplices necesarios en grado de tentativa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">autores</mark></span>El <span class=\"ref-norma\">art. 28 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"b) Los que cooperan a su ejecución con un acto sin el cual no se habría efectuado\"</span>. El cooperador necesario es autor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1132","p":"Código Penal. Penas graves. Son penas graves las inhabilitaciones especiales por tiempo superior a:","o":["tres años, sin perjuicio de lo previsto en la normativa vigente.","cinco años.","ocho años.","diez años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cinco años</mark></span>El <span class=\"ref-norma\">art. 33.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"d) Las inhabilitaciones especiales por tiempo superior a cinco años\"</span>. Inhabilitaciones especiales graves: más de cinco años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1134","p":"Código Penal. Penas graves. Es pena grave la prohibición de aproximarse a la víctima o a aquellos de sus familiares u otras personas que determine el juez o tribunal, por tiempo superior a:","o":["ocho años, en los términos que se determinen reglamentariamente.","tres años.","diez años.","cinco años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">cinco años</mark></span>El <span class=\"ref-norma\">art. 33.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"i) La prohibición de aproximarse a la víctima o a aquellos de sus familiares u otras personas que determine el juez o tribunal, por tiempo superior a cinco años\"</span>. La aproximación es grave por más de cinco años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1148","p":"Código Penal. Penas aplicables a las personas jurídicas. La suspensión de las actividades de una persona jurídica, como pena, lo será por un plazo que no podrá exceder de:","o":["diez años.","cinco años.","quince años.","tres años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cinco años</mark></span>El <span class=\"ref-norma\">art. 33.7 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"c) Suspensión de sus actividades por un plazo que no podrá exceder de cinco años\"</span>. Suspensión: hasta cinco años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1163","p":"Código Penal. Localización permanente. La localización permanente tendrá una duración de hasta:","o":["tres meses, en los términos que se determinen reglamentariamente.","un año.","seis meses.","doce meses."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">seis meses</mark></span>El <span class=\"ref-norma\">art. 37.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La localización permanente tendrá una duración de hasta seis meses\"</span>. Hasta seis meses; como pena leve, de un día a tres meses. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1207","p":"Código Penal. Localización permanente. La localización permanente tendrá una duración de hasta:","o":["tres meses, salvo que la autoridad judicial disponga otra cosa.","un año.","seis meses.","dos años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">seis meses</mark></span>El <span class=\"ref-norma\">art. 37.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La localización permanente tendrá una duración de hasta seis meses\"</span>. Hasta seis meses. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1233","p":"Código Penal. Pena de multa. La extensión de la pena de multa tendrá un mínimo de diez días y un máximo de:","o":["dos años.","un año.","cinco años.","dieciocho meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">dos años</mark></span>El <span class=\"ref-norma\">art. 50.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Su extensión mínima será de diez días y la máxima de dos años\"</span>. Mínimo diez días, máximo dos años; para las personas jurídicas, máximo cinco años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1234","p":"Código Penal. Pena de multa. Las penas de multa imponibles a personas jurídicas tendrán una extensión máxima de:","o":["dos años.","tres años, previo informe de la unidad policial competente.","diez años.","cinco años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">cinco años</mark></span>El <span class=\"ref-norma\">art. 50.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Las penas de multa imponibles a personas jurídicas tendrán una extensión máxima de cinco años\"</span>. Cinco años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1235","p":"Código Penal. Pena de multa. La cuota diaria de la multa tendrá un mínimo de dos y un máximo de 400 euros, excepto en el caso de las multas imponibles a las personas jurídicas, en las que la cuota diaria tendrá:","o":["un mínimo de 100 y un máximo de 5.000 euros.","un mínimo de 30 y un máximo de 10.000 euros.","un mínimo de 30 y un máximo de 5.000 euros.","un mínimo de 50 y un máximo de 4.000 euros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">un mínimo de 30 y un máximo de 5.000 euros</mark></span>El <span class=\"ref-norma\">art. 50.4 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"la cuota diaria tendrá un mínimo de 30 y un máximo de 5.000 euros\"</span>. Personas jurídicas: de 30 a 5.000 euros. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1245","p":"Código Penal. Responsabilidad personal subsidiaria por impago de multa. Esta responsabilidad subsidiaria no se impondrá a los condenados a pena privativa de libertad superior a:","o":["cinco años.","tres años, en los términos que se determinen reglamentariamente.","dos años.","diez años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cinco años</mark></span>El <span class=\"ref-norma\">art. 53.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Esta responsabilidad subsidiaria no se impondrá a los condenados a pena privativa de libertad superior a cinco años\"</span>. Cinco años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1246","p":"Código Penal. Responsabilidad personal subsidiaria por impago de multa. Podrá ser fraccionado el pago de la multa impuesta a una persona jurídica, durante un periodo de hasta:","o":["dos años.","tres años, salvo que la autoridad judicial disponga otra cosa.","diez años.","cinco años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">cinco años</mark></span>El <span class=\"ref-norma\">art. 53.5 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Podrá ser fraccionado el pago de la multa impuesta a una persona jurídica, durante un período de hasta cinco años\"</span>. Hasta cinco años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1254","p":"Código Penal. Penas accesorias. También podrán imponerse esas prohibiciones por la comisión de los mismos delitos cuando tengan la consideración de delitos leves, por un periodo de tiempo que no excederá de:","o":["tres meses, previo informe de la unidad policial competente.","un año.","dos años.","seis meses."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">seis meses</mark></span>El <span class=\"ref-norma\">art. 57.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"por un periodo de tiempo que no excederá de seis meses, por la comisión de los delitos mencionados en el primer párrafo del apartado 1 de este artículo que tengan la consideración de delitos leves\"</span>. Seis meses. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1426","p":"Código Penal. Inhabilitación profesional. La autoridad judicial podrá decretar razonadamente la medida de inhabilitación para el ejercicio de determinado derecho, profesión, oficio, industria o comercio, cargo o empleo u otras actividades, sean o no retribuidas, por un tiempo de:","o":["tres meses a cinco años.","uno a diez años.","seis meses a tres años.","uno a cinco años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">uno a cinco años</mark></span>El <span class=\"ref-norma\">art. 107 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"por un tiempo de uno a cinco años, cuando la persona haya cometido con abuso de dicho ejercicio\"</span>. Uno a cinco años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"De las Causas que Eximen la Responsabilidad Criminal","q":[{"i":"18-11","p":"Código Penal. La exención de la responsabilidad criminal declarada en los números 1, 2, 3, 5, 6 y 8 del artículo 20, no comprende la de la responsabilidad civil, de la que serán responsables:","o":["En el caso del que obre impulsado por miedo insuperable, exclusivamente los que hayan causado el miedo.","En el caso del que obre impulsado por miedo insuperable, exclusivamente los que hayan ejecutado el hecho.","En el caso del que obre impulsado por miedo insuperable, responderán principalmente los que hayan causado el miedo, y a defecto de ellos, los que hayan ejecutado el hecho.","En el caso del que obre impulsado por miedo insuperable, responderán principalmente los que hayan ejecutado el hecho, y a defecto de ellos, los que hayan causado el miedo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En el caso del que obre impulsado por miedo insuperable, responderán principalmente los que hayan causado el miedo, y a defecto de ellos, l…</mark></span>- Responden principalmente los causantes del miedo, y subsidiariamente los ejecutores."},{"i":"18-ia-1048","p":"Código Penal. Estado de necesidad. Está exento de responsabilidad criminal el que, en estado de necesidad, para evitar un mal propio o ajeno lesione un bien jurídico de otra persona o infrinja un deber. Señale la INCORRECTA entre los requisitos:","o":["Que el mal causado no sea mayor que el que se trate de evitar.","Que el mal causado sea igual o menor que el que se trate de evitar.","Que la situación de necesidad no haya sido provocada intencionadamente por el sujeto.","Que el necesitado no tenga, por su oficio o cargo, obligación de sacrificarse."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Que el mal causado sea igual o menor que el que se trate de evitar</mark></span>El <span class=\"ref-norma\">art. 20.5º del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Primero. Que el mal causado no sea mayor que el que se trate de evitar\"</span>. El requisito es que el mal causado no sea mayor que el que se trate de evitar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 120","q":[{"i":"18-13","p":"Código Penal. Son también responsables civilmente, en defecto de los que lo sean criminalmente, entre otras: señale la INCORRECTA.","o":["Las personas con facultades de representación plena que convivan con la persona o quien presten apoyo aunque no haya por su parte culpa o negligencia.","Las personas naturales o jurídicas, en los casos de delitos cometidos en los establecimientos de los que sean titulares, cuando por parte de los que los dirigen o administren, o de sus dependientes o empleados, se hayan infringido los reglamentos de policía o las disposiciones de la autoridad que estén relacionados con el hecho punible cometido, de modo que éste no se hubiera producido sin dicha infracción.","Las personas naturales o jurídicas dedicadas a cualquier género de industria o comercio, por los delitos que hayan cometido sus empleados o dependientes, representantes o gestores en el desempeño de sus obligaciones o servicios.","Las personas naturales o jurídicas titulares de vehículos susceptibles de crear riesgos para terceros, por los delitos cometidos en la utilización de aquéllos por sus dependientes o representantes o personas autorizadas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las personas con facultades de representación plena que convivan con la persona o quien presten apoyo aunque no haya por su parte culpa o n…</mark></span>- No existe responsabilidad civil sin culpa o negligencia por parte del representante."},{"i":"18-81","p":"Código Penal. De la responsabilidad civil, ¿quiénes serán responsables civilmente, en defecto de los que lo sean criminalmente?:","o":["Los padres o tutores, por los daños y perjuicios causados por los delitos cometidos por los mayores de dieciocho años sujetos a su patria potestad","Los padres, tutores por los daños y perjuicios causados por los delitos cometidos por los mayores de dieciocho años sujetos a su tutela","Las personas naturales o jurídicas, en los casos de delitos cometidos en los establecimientos de los que sean titulares, cuando por parte de los que los dirijan o administren, o de sus dependientes o empleados, se hayan infringido los reglamentos de Policía","Las personas naturales o jurídicas titulares de vehículos susceptibles de crear riesgos para terceros, por delitos cometidos en la utilización de aquellos por personas no autorizadas"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las personas naturales o jurídicas, en los casos de delitos cometidos en los establecimientos de los que sean titulares, cuando por parte d…</mark></span>- Los titulares de establecimientos responden civilmente cuando se infringen reglamentos de policía."},{"i":"18-102","p":"Código Penal. Son responsables civilmente, en defecto de los que lo sean criminalmente:","o":["Las personas naturales o jurídicas titulares de editoriales, periódicos, revistas, estaciones de radio o televisión o de cualquier otro medio de difusión escrita, hablada o visual, por los delitos cometidos utilizando los medios de los que sean titulares, dejando a salvo lo dispuesto en el artículo 212.","Las personas naturales o jurídicas, en los casos de delitos cometidos en los establecimientos de los que sean titulares, cuando por parte de los que los dirijan o administren, o de sus dependientes o empleados, se hayan infringido los reglamentos de policía o las disposiciones de la autoridad que estén relacionados con el hecho punible cometido, de modo que éste no se hubiera producido sin dicha infracción","Las personas naturales o jurídicas dedicadas a cualquier género de industria o comercio, por los delitos que hayan cometido sus empleados o dependientes, representantes o gestores en el desempeño de sus obligaciones o servicios","Todas son correctas"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 120 del Código Penal</span>: <span class=\"ref-concepto\">\"2.º Las personas naturales o jurídicas titulares de editoriales, periódicos, revistas, estaciones de radio o televisión o de cualquier otro medio de difusión escrita, hablada o visual, por los delitos cometidos utilizando los medios de los que sean titulares, dejando a salvo lo dispuesto en el artículo 212\"</span> (verificado con el texto del temario oficial)."},{"i":"18-286","p":"Código Penal. Responsabilidad civil subsidiaria. Son también responsables civilmente, en defecto de los que lo sean criminalmente, entre otros:","o":["Los curadores con facultades de representación plena, aunque no haya por su parte culpa o negligencia, en los términos que determine la ley orgánica correspondiente.","Los profesores y maestros respecto de los delitos cometidos por sus alumnos menores de edad.","Los curadores con facultades de representación plena que convivan con la persona a quien prestan apoyo, siempre que haya por su parte culpa o negligencia.","Las personas que convivan con el condenado, en proporción a sus ingresos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los curadores con facultades de representación plena que convivan con la persona a quien prestan apoyo, siempre que haya por su parte culpa o negligencia</mark></span>El <span class=\"ref-norma\">art. 120.1.º de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"Son también responsables civilmente, en defecto de los que lo sean criminalmente: 1.º Los curadores con facultades de representación plena que convivan con la persona a quien prestan apoyo, siempre que haya por su parte culpa o negligencia\"</span>"},{"i":"18-ia-1445","p":"Código Penal. Personas civilmente responsables. Señale la INCORRECTA. Son también responsables civilmente, en defecto de los que lo sean criminalmente:","o":["Los profesores y maestros, por los delitos cometidos por sus alumnos menores de edad dentro del centro docente.","Los curadores con facultades de representación plena que convivan con la persona a quien prestan apoyo, siempre que haya por su parte culpa o negligencia.","Las personas naturales o jurídicas titulares de editoriales, periódicos, revistas, estaciones de radio o televisión, por los delitos cometidos utilizando los medios de los que sean titulares.","Las personas naturales o jurídicas titulares de vehículos susceptibles de crear riesgos para terceros, por los delitos cometidos en la utilización de aquellos por sus dependientes o representantes o personas autorizadas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los profesores y maestros, por los delitos cometidos por sus alumnos menores de edad dentro del centro docente</mark></span>El <span class=\"ref-norma\">art. 120 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"1.º Los curadores con facultades de representación plena que convivan con la persona a quien prestan apoyo, siempre que haya por su parte culpa o negligencia\"</span>. Los profesores no figuran en el listado del art. 120. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 30 ✱","q":[{"i":"18-14","p":"Código Penal. En los delitos que se cometan utilizando medios o soportes de difusión mecánicos:","o":["Responderán criminalmente solo los propietarios de dichos medios o soportes.","Responderán criminalmente los autores y los cómplices.","Responderán criminalmente los autores y quienes los hubieren favorecido personal o realmente.","No responden criminalmente ni los cómplices ni quienes los hubieran favorecido personal o realmente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Responderán criminalmente los autores y quienes los hubieren favorecido personal o realmente.</mark></span>- Responden los autores y quienes hayan favorecido la comisión del delito."},{"i":"18-91","p":"Código Penal. De las personas criminalmente responsables de los delitos. Cuando para la comisión de un hecho delictivo se utilizan medios o soportes de difusión mecánicos, responderá como autor en primer lugar:","o":["Los directores de la publicación o programa en que se difunda","Los que realmente hayan redactado el texto o producido el signo de que se trate","Los directores de la publicación en que se difunda","Los que realmente hayan redactado el texto o producido el signo de que se trate y quienes les hayan inducido a realizarlo"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los que realmente hayan redactado el texto o producido el signo de que se trate y quienes les hayan inducido a realizarlo</mark></span> Responden en primer lugar los autores materiales y quienes les indujeron. TEST 7"},{"i":"18-113","p":"Código Penal. En los delitos que se cometan utilizando medios o soportes de difusión mecánicos: Señala la correcta.","o":["No responden criminalmente los cómplices.","No responden criminalmente quienes los hubieren favorecido personal o realmente.","A y B son correctas.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>Según el <span class=\"ref-norma\">art. 30 del Código Penal</span>: <span class=\"ref-concepto\">\"En los delitos que se cometan utilizando medios o soportes de difusión mecánicos no responderán criminalmente ni los cómplices ni quienes los hubieren favorecido personal o realmente\"</span> (verificado con el texto del temario oficial)."},{"i":"18-137","p":"Código Penal. Delitos utilizando medios o soportes de difusión mecánicos. ¿Quién responderá en tercer lugar?","o":["Los directores de la empresa editora, emisora o difusora.","Quien realmente haya elaborado el texto o producto de difusión.","Los directores de la publicación o programa en que se difunde.","Los directores de la empresa grabadora, reproductora o impresora."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los directores de la empresa grabadora, reproductora o impresora.</mark></span>(Los directores de empresas grabadoras, reproductoras o impresoras responden en tercer lugar)."},{"i":"18-ia-1106","p":"Código Penal. Delitos cometidos por medios de difusión. En los delitos que se cometan utilizando medios o soportes de difusión mecánicos no responderán criminalmente:","o":["ni los inductores ni quienes los hubieren favorecido personal o realmente.","ni los cómplices ni los directores de la empresa editora.","ni los cooperadores necesarios ni quienes los hubieren encubierto.","ni los cómplices ni quienes los hubieren favorecido personal o realmente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">ni los cómplices ni quienes los hubieren favorecido personal o realmente</mark></span>El <span class=\"ref-norma\">art. 30.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"no responderán criminalmente ni los cómplices ni quienes los hubieren favorecido personal o realmente\"</span>. Quedan fuera los cómplices y los favorecedores personales o reales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1107","p":"Código Penal. Delitos cometidos por medios de difusión. Los autores de los delitos que se cometan utilizando medios o soportes de difusión mecánicos responderán de forma:","o":["solidaria, cumulativa y subsidiaria, salvo que la autoridad judicial disponga otra cosa.","escalonada, cumulativa y solidaria.","escalonada, excluyente y subsidiaria.","excluyente, solidaria y subsidiaria."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">escalonada, excluyente y subsidiaria</mark></span>El <span class=\"ref-norma\">art. 30.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"responderán de forma escalonada, excluyente y subsidiaria de acuerdo con el siguiente orden\"</span>. La responsabilidad es escalonada, excluyente y subsidiaria. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1108","p":"Código Penal. Delitos cometidos por medios de difusión. En los delitos cometidos por medios o soportes de difusión mecánicos, responderán en primer lugar:","o":["los directores de la publicación o programa en que se difunda.","los que realmente hayan redactado el texto o producido el signo de que se trate, y quienes les hayan inducido a realizarlo.","los directores de la empresa editora, emisora o difusora.","los que realmente hayan redactado el texto o producido el signo de que se trate, con exclusión de los inductores, previo informe de la unidad policial competente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los que realmente hayan redactado el texto o producido el signo de que se trate, y quienes les hayan inducido a realizarlo</mark></span>El <span class=\"ref-norma\">art. 30.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"1.º Los que realmente hayan redactado el texto o producido el signo de que se trate, y quienes les hayan inducido a realizarlo\"</span>. El primer escalón son los redactores y quienes les hayan inducido. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1109","p":"Código Penal. Delitos cometidos por medios de difusión. En los delitos cometidos por medios de difusión mecánicos, el orden escalonado de responsabilidad de los autores es el siguiente. Señale el CORRECTO:","o":["Redactores e inductores; directores de la publicación o programa; directores de la empresa editora, emisora o difusora; directores de la empresa grabadora, reproductora o impresora.","Directores de la publicación o programa; redactores e inductores; directores de la empresa editora, emisora o difusora; directores de la empresa grabadora, reproductora o impresora, sin perjuicio de lo previsto en la normativa vigente.","Redactores e inductores; directores de la empresa editora, emisora o difusora; directores de la publicación o programa; directores de la empresa grabadora, reproductora o impresora.","Redactores e inductores; directores de la publicación o programa; directores de la empresa grabadora, reproductora o impresora; directores de la empresa editora, emisora o difusora."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Redactores e inductores; directores de la publicación o programa; directores de la empresa editora, emisora o difusora; directores de la empresa grabadora, reproductora o impresora</mark></span>El <span class=\"ref-norma\">art. 30.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"1.º Los que realmente hayan redactado el texto o producido el signo de que se trate, y quienes les hayan inducido a realizarlo. 2.º Los directores de la publicación o programa en que se difunda. 3.º Los directores de la empresa editora, emisora o difusora. 4.º Los directores de la empresa grabadora, reproductora o impresora\"</span>. El orden es: redactores e inductores, directores de publicación, directores de empresa editora y directores de empresa grabadora. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1111","p":"Código Penal. Delitos cometidos por medios de difusión. Cuando por cualquier motivo distinto de la extinción de la responsabilidad penal, incluso la declaración de rebeldía o la residencia fuera de España, no pueda perseguirse a ninguna de las personas comprendidas en alguno de los números del apartado anterior, se dirigirá el procedimiento contra:","o":["las mencionadas en el número inmediatamente anterior, salvo que la autoridad judicial disponga otra cosa.","las mencionadas en el último número del apartado.","las mencionadas en el número inmediatamente posterior.","los cómplices y quienes hubieren favorecido el hecho."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las mencionadas en el número inmediatamente posterior</mark></span>El <span class=\"ref-norma\">art. 30.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"se dirigirá el procedimiento contra las mencionadas en el número inmediatamente posterior\"</span>. Se pasa al escalón inmediatamente posterior. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 112","q":[{"i":"18-15","p":"Código Penal. De la responsabilidad civil derivada de los delitos y de las costas procesales. De la responsabilidad civil y su extensión. La responsabilidad civil comprenderá:","o":["La indemnización por los daños psicológicos.","La fianza.","La reparación del daño.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La reparación del daño.</mark></span>- La responsabilidad civil comprende principalmente la reparación del daño causado."},{"i":"18-21","p":"Código Penal. Responsabilidad civil y su extensión. La reparación del daño podrá consistir en:","o":["Obligaciones de dar.","Obligaciones de hacer.","Obligaciones de no hacer.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span>- La reparación puede consistir en obligaciones de dar, hacer o no hacer."},{"i":"18-ia-1435","p":"Código Penal. Responsabilidad civil. La reparación del daño podrá consistir en:","o":["obligaciones de dar o de hacer, que el Juez establecerá atendiendo exclusivamente a la naturaleza del daño, en los términos que se determinen reglamentariamente, salvo que la autoridad judicial disponga otra cosa.","obligaciones de dar, de hacer o de no hacer que fijará el perjudicado de común acuerdo con el culpable.","obligaciones de dar, de hacer o de no hacer que el Juez o Tribunal establecerá atendiendo a la naturaleza de aquél y a las condiciones personales y patrimoniales del culpable.","obligaciones de hacer o de no hacer, que se ejecutarán siempre por el propio culpable."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">obligaciones de dar, de hacer o de no hacer que el Juez o Tribunal establecerá atendiendo a la naturaleza de aquél y a las condiciones personales y patrimoniales del culpable</mark></span>El <span class=\"ref-norma\">art. 112 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La reparación del daño podrá consistir en obligaciones de dar, de hacer o de no hacer que el Juez o Tribunal establecerá atendiendo a la naturaleza de aquél y a las condiciones personales y patrimoniales del culpable\"</span>. Dar, hacer o no hacer. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"RECUERDA del temario · Código Penal (R21 a R29) R21 R22 R23 R24 R25 R26 R27 R28 R29","q":[{"i":"18-16","p":"Código Penal. De las medidas de seguridad. Señale la CORRECTA:","o":["En el caso de concurrencia de penas y medidas de seguridad privativas de libertad, el juez o tribunal ordenará el incumplimiento de la medida.","En el caso de concurrencia de penas y medidas de seguridad privativas de libertad, el juez o tribunal ordenará el cumplimiento de la medida, que no se abonará para el de la pena.","En el caso de concurrencia de penas y medidas de seguridad privativas de libertad, el juez o tribunal ordenará el cumplimiento de la medida, que se abonará para el de la pena.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En el caso de concurrencia de penas y medidas de seguridad privativas de libertad, el juez o tribunal ordenará el cumplimiento de la medida…</mark></span>- El tiempo de cumplimiento de la medida de seguridad se abona para el cómputo de la pena."},{"i":"18-22","p":"Código Penal. La responsabilidad criminal se extingue, entre otros:","o":["Por la muerte del reo.","Por el cumplimiento de la condena.","Por la prescripción del delito.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span>- Todas son causas de extinción de la responsabilidad criminal."},{"i":"18-23","p":"Código Penal. No se reputarán penas: Señale la INCORRECTA.","o":["La localización permanente y la responsabilidad personal subsidiaria por impago de multa.","La detención y prisión preventiva y las demás medidas cautelares de naturaleza penal.","Las multas y demás correcciones que, en uso de potestades gubernativas o disciplinarias, se impongan a los subordinados o administrados.","Las privaciones de derechos y las sanciones reparadoras que establezcan las leyes civiles o administrativas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La localización permanente y la responsabilidad personal subsidiaria por impago de multa.</mark></span>- La localización permanente SÍ es una pena según el Código Penal."},{"i":"18-27","p":"Código Penal. Se fundamentan en la peligrosidad criminal del sujeto al que se impongan, exteriorizada en la comisión de un hecho previsto como delito, las:","o":["Penas.","Medidas de seguridad.","Sanciones administrativas.","Multas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Medidas de seguridad.</mark></span>- Las medidas de seguridad se fundamentan en la peligrosidad criminal del sujeto."},{"i":"18-30","p":"Código Penal. Prescripción de delitos: señale la INCORRECTA.","o":["Cuando la pena señalada por la ley fuera compuesta, se estará, para la aplicación de las reglas comprendidas en esta ley, a la que exija mayor tiempo para la prescripción.","Los delitos de lesa humanidad y de genocidio y los delitos contra las personas y bienes protegidos en caso de conflicto armado, salvo los castigados en el artículo 614, no prescribirán en ningún caso.","Los delitos de terrorismo no prescribirán en ningún caso.","En los supuestos de concurso de infracciones o de infracciones conexas, el plazo de prescripción será el que corresponda al delito más grave."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los delitos de terrorismo no prescribirán en ningún caso</mark></span>Solo no prescriben los de terrorismo que hayan causado la muerte de una persona, no todos. Según el <span class=\"ref-norma\">art. 131 del Código Penal</span>: <span class=\"ref-concepto\">\"Tampoco prescribirán los delitos de terrorismo, si hubieren causado la muerte de una persona\"</span> (verificado con el texto del temario oficial)."},{"i":"18-34","p":"Código Penal. El tiempo de la prescripción se computará:","o":["Desde el día siguiente a aquel en que haya quedado firme la resolución en la que se impuso la medida o, en caso de cumplimiento sucesivo, desde que debió empezar a cumplirse.","Desde el día en que se dictó la resolución en la que se impuso la medida o, en caso de cumplimiento sucesivo, desde que debió empezar a cumplirse.","Desde el día en que haya quedado firme la resolución en la que se impuso la medida o, en caso de cumplimiento sucesivo, desde que debió empezar a cumplirse.","Todas son incorrectas"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Desde el día en que haya quedado firme la resolución en la que se impuso la medida o, en caso de cumplimiento sucesivo, desde que debió empezar a cumplirse</mark></span>Según el <span class=\"ref-norma\">art. 135 del Código Penal</span>: <span class=\"ref-concepto\">\"El tiempo de la prescripción se computará desde el día en que haya quedado firme la resolución en la que se impuso la medida o, en caso de cumplimiento sucesivo, desde que debió empezar a cumplirse\"</span> (verificado con el texto del temario oficial)."},{"i":"18-39","p":"Código Penal. La responsabilidad criminal se extingue, entre otras: señale la INCORRECTA","o":["Por la prescripción del delito","Por la prescripción de la pena","Por la prescripción de la instrucción","Por la prescripción de la medida de seguridad"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por la prescripción de la instrucción</mark></span>- No existe la &quot;prescripción de la instrucción&quot; como causa de extinción de la responsabilidad criminal."},{"i":"18-54","p":"Código Penal. De las consecuencias accesorias. El juez o tribunal ordenará también el decomiso de los bienes, efectos y ganancias pertenecientes a una persona condenada por alguno de los siguientes delitos cuando resuelva, a partir de indicios objetivos fundados, que los bienes o efectos provienen de una actividad delictiva, y no se acredite su origen lícito: señale la INCORRECTA","o":["Delitos de falsificación de moneda","Delitos de cohecho","Delitos de prevaricación","Delitos de malversación"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Delitos de prevaricación</mark></span>- La prevaricación no está específicamente mencionada entre los delitos que permiten este tipo de decomiso."},{"i":"18-75","p":"Código Penal. A los cómplices de un delito consumado se les impondrá:","o":["La pena inferior en su mitad inferior en todo caso","La pena inferior en dos grados a la señalada por la Ley para el delito consumado en todo caso","La pena inferior en un grado a la fijada por la Ley para el mismo delito","Todas son incorrectas"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La pena inferior en un grado a la fijada por la Ley para el mismo delito</mark></span>- A los cómplices se les impone la pena inferior en un grado."},{"i":"18-135","p":"Código Penal. ¿Desde qué momento se inicia el cómputo del tiempo de prescripción de una medida de seguridad?","o":["Desde que se dicta la resolución.","Desde el día en que haya quedado firme la resolución en la que se impuso la medida o, en caso de cumplimiento sucesivo, desde que debió empezar a cumplirse.","Desde que se notifica la resolución.","Desde que se apela la resolución."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Desde el día en que haya quedado firme la resolución en la que se impuso la medida o, en caso de cumplimiento sucesivo, desde que debió emp…</mark></span>(La prescripción comienza desde que la resolución queda firme o desde que debió empezar el cumplimiento)."},{"i":"18-159","p":"Código Penal. De las causas que extinguen la responsabilidad criminal. ¿Cuál es el plazo de prescripción para las medidas de seguridad privativas de libertad superiores a tres años?:","o":["A los 10 años.","A los 15 años.","A los 20 años.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A los 10 años.</mark></span>(Las medidas de seguridad privativas de libertad superiores a 3 años prescriben a los 10 años)."},{"i":"18-162","p":"Código Penal. La responsabilidad criminal NO se extingue:","o":["Por el perdón de la persona ofendida en todo caso.","Por la amnistía o el indulto.","Por el cumplimiento de la condena.","Por la prescripción de la pena."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Por el perdón de la persona ofendida en todo caso.</mark></span>(El perdón de la víctima no extingue la responsabilidad criminal en todos los casos, solo en algunos delitos)."},{"i":"18-166","p":"Código Penal. De las personas criminalmente responsables de los delitos. ¿Quiénes son responsables criminalmente de los delitos?","o":["Los autores.","Los cómplices.","Los testigos de los delitos.","A y B son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A y B son correctas.</mark></span>(Autores y cómplices son responsables criminalmente de los delitos)."},{"i":"18-167","p":"Código Penal. De las consecuencias accesorias. ¿Qué medida puede tomar la autoridad judicial para garantizar la efectividad del decomiso desde las primeras diligencias?","o":["Aprehender o embargar los bienes y ponerlos en depósito.","Transferir la propiedad de los bienes al estado inmediatamente.","Realizar una auditoría financiera de los bienes.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Aprehender o embargar los bienes y ponerlos en depósito.</mark></span> (Puede aprehender o embargar los bienes para garantizar el decomiso). TEST 12"},{"i":"18-174","p":"Código penal. De las medidas no privativas de libertad. Si el juez acuerda la expulsión de un extranjero del territorio nacional como sustitutiva de las medidas de seguridad que le sean aplicables, este no podrá regresar a España en un plazo de:","o":["15 años.","5 años.","10 años.","20 años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">10 años.</mark></span>(El plazo de prohibición de regreso es de 10 años)."},{"i":"18-176","p":"Código penal. De los siguientes delitos, ¿cuáles no prescriben nunca?","o":["Los cometidos por organizaciones criminales.","Los delitos contra las personas y bienes protegidos en caso de conflicto armado.","Los delitos de terrorismo.","Los delitos de apropiación, siempre que hubiesen causado la muerte de una persona."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los delitos contra las personas y bienes protegidos en caso de conflicto armado.</mark></span>(Los delitos de lesa humanidad y contra personas protegidas en conflictos armados no prescriben)."},{"i":"18-188","p":"Código Penal. Cuando el reo estuviere preso, la duración de las penas empezará a computarse desde el día en que la sentencia condenatoria:","o":["Haya quedado planteada ante el juez.","Haya sido implementada.","Haya quedado firme.","Haya sido estudiada por el juez. *"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Haya quedado firme.</mark></span><span class=\"ref-norma\">Art. 76.1 · De las Penas</span>. Haya quedado firme. (El cómputo de la pena de prisión se inicia desde la detención, pero se &quot;abona&quot; definitivamente desde que la sentencia condenatoria queda firme, de acuerdo con el Artículo 76.1 del Código Penal).*"},{"i":"18-203","p":"Código Penal. De la pena de multa. Si el condenado no satisficiere, voluntariamente o por vía de apremio, la multa impuesta, quedará sujeto a una responsabilidad personal subsidiaria de un día de privación de libertad por cada dos cuotas diarias no satisfechas, que, tratándose de delitos leves, podrá cumplirse:","o":["Mediante una pena no privativa de libertad.","Mediante localización permanente.","Mediante vigilancia temporal.","Mediante localización revisable. *"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Mediante localización permanente</mark></span>Según el <span class=\"ref-norma\">art. 53 del Código Penal</span>: <span class=\"ref-concepto\">\"que, tratándose de delitos leves, podrá cumplirse mediante localización permanente\"</span> (verificado con el texto del temario oficial)."},{"i":"18-214","p":"Código Penal. Si el condenado no satisficiere, voluntariamente o por vía de apremio, la multa impuesta, quedará sujeto a ¿qué responsabilidad?","o":["Una responsabilidad personal subsidiaria de un día de privación de libertad por cada dos cuotas diarias no satisfechas, que, tratándose de delitos leves, podrá cumplirse mediante localización permanente.","Una responsabilidad personal solidaria de un día de privación de libertad por cada dos cuotas diarias no satisfechas, que, tratándose de delitos leves, podrá cumplirse mediante vigilancia permanente.","Una responsabilidad personal pecuniaria de un día de privación de libertad por cada tres cuotas diarias no satisfechas, que, tratándose de delitos leves, podrá cumplirse mediante vigilancia permanente.","Una responsabilidad personal solidaria de un día de privación de libertad por cada tres cuotas diarias no satisfechas, que, tratándose de delitos leves, podrá cumplirse mediante localización permanente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Una responsabilidad personal subsidiaria de un día de privación de libertad por cada dos cuotas diarias no satisfechas, que, tratándose de …</mark></span><span class=\"ref-norma\">Art. 53 · De las Penas</span>. (El Artículo 53 del CP establece una responsabilidad personal subsidiaria de un día de privación de libertad por cada dos cuotas diarias no satisfechas)."},{"i":"18-243","p":"Código Penal. ¿Cuántas cuotas ha de dejar sin satisfacer de la multa impuesta el condenado, quedando este sujeto a una responsabilidad personal subsidiaria de un día de privación de libertad?","o":["Una cuota","Tres cuotas","Dos cuotas","Cinco cuotas"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Dos cuotas</mark></span><span class=\"ref-norma\">Art. 53 · De las Penas</span>. (El Artículo 53 del CP establece que es por cada dos cuotas diarias no satisfechas)."},{"i":"18-249","p":"Código Penal. Delito consumado y tentativa. Son punibles:","o":["Únicamente el delito consumado, salvo previsión expresa de la tentativa.","El delito consumado, la tentativa y los actos preparatorios en todo caso.","El delito consumado y la tentativa, solo si el resultado se hubiera producido en parte.","El delito consumado y la tentativa de delito."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El delito consumado y la tentativa de delito</mark></span>El <span class=\"ref-norma\">art. 15 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"Son punibles el delito consumado y la tentativa de delito\"</span>"},{"i":"18-282","p":"Código Penal. Expulsión de extranjeros. El extranjero no podrá regresar a España en un plazo de 10 años, contados:","o":["Desde la firmeza de la sentencia.","Desde la fecha de su ingreso en el centro de internamiento de extranjeros.","Desde la fecha de su expulsión.","Desde la fecha de la sentencia condenatoria."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Desde la fecha de su expulsión</mark></span>El <span class=\"ref-norma\">art. 108.2 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"El extranjero no podrá regresar a España en un plazo de 10 años, contados desde la fecha de su expulsión\"</span>"},{"i":"18-288","p":"Código Penal. Aprehensión de los bienes. A fin de garantizar la efectividad del decomiso, los bienes, medios, instrumentos y ganancias podrán ser aprehendidos o embargados y puestos en depósito por:","o":["La autoridad judicial desde el momento de las primeras diligencias.","El Ministerio Fiscal desde la apertura del juicio oral.","La policía judicial desde la detención del investigado.","El Juez de Vigilancia Penitenciaria desde la firmeza de la sentencia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La autoridad judicial desde el momento de las primeras diligencias</mark></span>El <span class=\"ref-norma\">art. 127 octies.1 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"podrán ser aprehendidos o embargados y puestos en depósito por la autoridad judicial desde el momento de las primeras diligencias\"</span>"},{"i":"18-290","p":"Código Penal. Personas jurídicas. No extingue la responsabilidad penal de la persona jurídica:","o":["La disolución real acordada por la junta general de socios.","La muerte de su administrador único.","La disolución encubierta o meramente aparente.","El cumplimiento de la pena de multa impuesta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La disolución encubierta o meramente aparente</mark></span>El <span class=\"ref-norma\">art. 130.2 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"No extingue la responsabilidad penal la disolución encubierta o meramente aparente de la persona jurídica\"</span>"},{"i":"18-ia-1006","p":"Código Penal. Ejecución de la pena. No podrá ejecutarse pena ni medida de seguridad sino en virtud de sentencia __________ dictada por el Juez o Tribunal competente, de acuerdo con las leyes procesales:","o":["definitiva","motivada","ejecutoria","firme"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">firme</mark></span>El <span class=\"ref-norma\">art. 3.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"No podrá ejecutarse pena ni medida de seguridad sino en virtud de sentencia firme dictada por el Juez o Tribunal competente, de acuerdo con las leyes procesales\"</span>. Se exige sentencia firme. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1029","p":"Código Penal. Grados de ejecución. Son punibles:","o":["el delito consumado y la tentativa de delito.","el delito consumado y el frustrado.","el delito consumado, la tentativa y los actos preparatorios.","el delito consumado y la tentativa, solo cuando sean graves."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el delito consumado y la tentativa de delito</mark></span>El <span class=\"ref-norma\">art. 15 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Son punibles el delito consumado y la tentativa de delito\"</span>. Solo consumación y tentativa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1101","p":"Código Penal. Responsables criminalmente. Son responsables criminalmente de los delitos:","o":["los autores y los cómplices.","los autores, los cómplices y los encubridores.","los autores y los cooperadores necesarios.","los autores, los inductores y los cómplices."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los autores y los cómplices</mark></span>El <span class=\"ref-norma\">art. 27 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Son responsables criminalmente de los delitos los autores y los cómplices\"</span>. Solo autores y cómplices. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1153","p":"Código Penal. Lo que no son penas. Señale la INCORRECTA. No se reputarán penas:","o":["La localización permanente impuesta por sentencia firme.","La detención y prisión preventiva y las demás medidas cautelares de naturaleza penal.","Las multas y demás correcciones que, en uso de atribuciones gubernativas o disciplinarias, se impongan a los subordinados o administrados.","Las privaciones de derechos y las sanciones reparadoras que establezcan las leyes civiles o administrativas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La localización permanente impuesta por sentencia firme</mark></span>El <span class=\"ref-norma\">art. 34 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"No se reputarán penas: 1. La detención y prisión preventiva y las demás medidas cautelares de naturaleza penal. 2. Las multas y demás correcciones que, en uso de atribuciones gubernativas o disciplinarias, se impongan a los subordinados o administrados. 3. Las privaciones de derechos y las sanciones reparadoras que establezcan las leyes civiles o administrativas\"</span>. La localización permanente es una pena privativa de libertad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1211","p":"Código Penal. Penas privativas de derechos. Señale cuál de las siguientes NO es una pena privativa de derechos:","o":["La inhabilitación absoluta.","La privación del derecho a la tenencia y porte de armas.","La localización permanente.","Los trabajos en beneficio de la comunidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La localización permanente</mark></span>El <span class=\"ref-norma\">art. 39 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Son penas privativas de derechos: a) La inhabilitación absoluta. b) Las de inhabilitación especial para empleo o cargo público, profesión, oficio, industria o comercio, u otras actividades, sean o no retribuidas\"</span>. La localización permanente es una pena privativa de libertad, no de derechos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1242","p":"Código Penal. Responsabilidad personal subsidiaria por impago de multa. Si el condenado no satisficiere, voluntariamente o por vía de apremio, la multa impuesta, quedará sujeto a una responsabilidad personal subsidiaria de:","o":["un día de privación de libertad por cada cuota diaria no satisfecha.","dos días de privación de libertad por cada cuota diaria no satisfecha.","un día de privación de libertad por cada tres cuotas diarias no satisfechas.","un día de privación de libertad por cada dos cuotas diarias no satisfechas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">un día de privación de libertad por cada dos cuotas diarias no satisfechas</mark></span>El <span class=\"ref-norma\">art. 53.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"quedará sujeto a una responsabilidad personal subsidiaria de un día de privación de libertad por cada dos cuotas diarias no satisfechas\"</span>. Un día por cada dos cuotas diarias no satisfechas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1429","p":"Código Penal. Expulsión de extranjeros. El extranjero expulsado no podrá regresar a España en un plazo de:","o":["10 años, contados desde la fecha de su expulsión.","5 años, contados desde la fecha de su expulsión.","10 años, contados desde la firmeza de la sentencia.","8 años, contados desde la fecha de su expulsión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">10 años, contados desde la fecha de su expulsión</mark></span>El <span class=\"ref-norma\">art. 108.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"El extranjero no podrá regresar a España en un plazo de 10 años, contados desde la fecha de su expulsión\"</span>. Diez años desde la fecha de expulsión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1433","p":"Código Penal. Responsabilidad civil. Señale la INCORRECTA. La responsabilidad civil derivada del delito comprende:","o":["La imposición de una multa pecuniaria al responsable civil.","La restitución.","La reparación del daño.","La indemnización de perjuicios materiales y morales, previo informe de la unidad policial competente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La imposición de una multa pecuniaria al responsable civil</mark></span>El <span class=\"ref-norma\">art. 110 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"1.º La restitución. 2.º La reparación del daño. 3.º La indemnización de perjuicios materiales y morales\"</span>. Solo comprende restitución, reparación del daño e indemnización de perjuicios. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1506","p":"Código Penal. Decomiso ampliado. Señale la INCORRECTA. El decomiso ampliado procede cuando la persona haya sido condenada por alguno de los siguientes delitos:","o":["Delitos de trata de seres humanos.","Delitos de blanqueo de capitales.","Delitos de cohecho.","Delitos de lesiones leves."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Delitos de lesiones leves</mark></span>El <span class=\"ref-norma\">art. 127 bis.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"a) Delitos de trata de seres humanos. a bis) Delitos de tráfico de órganos\"</span>. Los delitos de lesiones leves no figuran en el listado del decomiso ampliado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1520","p":"Código Penal. Aprehensión y destino de los bienes. A fin de garantizar la efectividad del decomiso, los bienes, medios, instrumentos y ganancias podrán ser aprehendidos o embargados y puestos en depósito por la autoridad judicial:","o":["desde el auto de procesamiento.","desde el momento de las primeras diligencias.","desde la sentencia de condena.","desde la firmeza de la sentencia, en los términos que se determinen reglamentariamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">desde el momento de las primeras diligencias</mark></span>El <span class=\"ref-norma\">art. 127 octies.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"podrán ser aprehendidos o embargados y puestos en depósito por la autoridad judicial desde el momento de las primeras diligencias\"</span>. Desde las primeras diligencias. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1538","p":"Código Penal. Prescripción de los delitos. Señale la INCORRECTA. No prescribirán en ningún caso:","o":["Los delitos de lesa humanidad y de genocidio.","Los delitos contra las personas y bienes protegidos en caso de conflicto armado, salvo los castigados en el artículo 614.","Los delitos de terrorismo, si hubieren causado la muerte de una persona.","Los delitos de terrorismo, en todo caso."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los delitos de terrorismo, en todo caso</mark></span>El <span class=\"ref-norma\">art. 131.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Tampoco prescribirán los delitos de terrorismo, si hubieren causado la muerte de una persona\"</span>. Solo los de terrorismo que hayan causado la muerte de una persona. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 132 ✱","q":[{"i":"18-18","p":"Código Penal. En los delitos de aborto no consentido, lesiones, contra la libertad, de torturas y contra la integridad moral, contra la intimidad, el derecho a la propia imagen y la inviolabilidad del domicilio, y contra las relaciones familiares, excluidos determinados delitos, cuando la víctima fuere menor de dieciocho años, los términos se computarán:","o":["Desde la fecha de la comisión del hecho delictivo.","Desde el día que la víctima haya alcanzado la mayoría de edad, y si falleciere antes de alcanzarla, a partir de la fecha del fallecimiento.","Desde el día que se tiene conocimiento del delito por parte de la autoridad judicial.","Desde el día que se tiene conocimiento del delito y si falleciere después de alcanzar la mayoría de edad, a partir del día siguiente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Desde el día que la víctima haya alcanzado la mayoría de edad, y si falleciere antes de alcanzarla, a partir de la fecha del fallecimiento.</mark></span>- En delitos contra menores, los plazos se computan desde que la víctima alcanza la mayoría de edad."},{"i":"18-132","p":"Código Penal. ¿Desde cuándo se computarán los términos de prescripción en los delitos de tentativa de homicidio, maltrato habitual, delitos contra la libertad sexual y trata de seres humanos cuando la víctima es menor de dieciocho años?","o":["Desde que la víctima cumpla los treinta y cinco años de edad.","Desde el día en que se cometió la infracción posible.","Desde la fecha del fallecimiento de la víctima, si ésta ocurre antes de alcanzar esa edad.","A y C son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A y C son correctas</mark></span>Es a los treinta y cinco años (no a los dieciocho) cuando la víctima era menor de edad. Según el <span class=\"ref-norma\">art. 132 del Código Penal</span>: <span class=\"ref-concepto\">\"los términos se computarán desde que la víctima cumpla los treinta y cinco años de edad, y si falleciere antes de alcanzar esa edad, a partir de la fecha del fallecimiento\"</span> (verificado con el texto del temario oficial)."},{"i":"18-292","p":"Código Penal. Cómputo de la prescripción. Los términos de prescripción de los delitos se computarán:","o":["Desde el día en que se haya cometido la infracción punible.","Desde el día en que se incoe el procedimiento penal, salvo que el órgano competente acuerde otra cosa de forma motivada.","Desde el día en que la víctima denuncie los hechos.","Desde el día en que la sentencia devenga firme."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Desde el día en que se haya cometido la infracción punible</mark></span>El <span class=\"ref-norma\">art. 132.1 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"los términos previstos en el artículo precedente se computarán desde el día en que se haya cometido la infracción punible\"</span>"},{"i":"18-293","p":"Código Penal. Interrupción de la prescripción. La presentación de querella o la denuncia ante un órgano judicial, en la que se atribuya a una persona determinada su presunta participación en un hecho delictivo, suspenderá el cómputo de la prescripción por un plazo máximo de:","o":["Tres meses, a contar desde la admisión a trámite de la querella o denuncia.","Un año, a contar desde la misma fecha de presentación de la querella o denuncia.","Dos meses, a contar desde la misma fecha de presentación de la querella o denuncia, conforme al procedimiento que reglamentariamente se establezca.","Seis meses, a contar desde la misma fecha de presentación de la querella o de formulación de la denuncia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Seis meses, a contar desde la misma fecha de presentación de la querella o de formulación de la denuncia</mark></span>El <span class=\"ref-norma\">art. 132.2.2.ª de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"suspenderá el cómputo de la prescripción por un plazo máximo de seis meses, a contar desde la misma fecha de presentación de la querella o de formulación de la denuncia\"</span>"},{"i":"18-ia-1540","p":"Código Penal. Cómputo de la prescripción de los delitos. En los casos de delito continuado, delito permanente, así como en las infracciones que exijan habitualidad, los términos de prescripción se computarán, respectivamente, desde el día en que se realizó la última infracción, desde que se eliminó la situación ilícita o:","o":["desde que se denunció la conducta.","desde que cesó la conducta.","desde que se tuvo conocimiento de la conducta.","desde el día en que se incoó el procedimiento."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">desde que cesó la conducta</mark></span>El <span class=\"ref-norma\">art. 132.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"tales términos se computarán, respectivamente, desde el día en que se realizó la última infracción, desde que se eliminó la situación ilícita o desde que cesó la conducta\"</span>. Última infracción, eliminación de la situación ilícita o cese de la conducta. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1541","p":"Código Penal. Cómputo de la prescripción de los delitos. En los delitos de tentativa de homicidio, de maltrato habitual, contra la libertad sexual y de trata de seres humanos, cuando la víctima fuere una persona menor de dieciocho años, los términos de prescripción se computarán desde que la víctima cumpla:","o":["los treinta y cinco años de edad.","los dieciocho años de edad, salvo que la autoridad judicial disponga otra cosa.","los veintiún años de edad.","los treinta años de edad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los treinta y cinco años de edad</mark></span>El <span class=\"ref-norma\">art. 132.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"los términos se computarán desde que la víctima cumpla los treinta y cinco años de edad, y si falleciere antes de alcanzar esa edad, a partir de la fecha del fallecimiento\"</span>. Treinta y cinco años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1542","p":"Código Penal. Cómputo de la prescripción de los delitos. En los delitos de aborto no consentido, lesiones, contra la libertad, de torturas y contra la integridad moral, contra la intimidad, y contra las relaciones familiares, cuando la víctima fuere una persona menor de dieciocho años, los términos de prescripción se computarán:","o":["desde que la víctima cumpla los veintiún años de edad.","desde el día en que se cometió la infracción, sin excepción, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente.","desde el día en que la víctima interponga la denuncia.","desde el día en que ésta haya alcanzado la mayoría de edad, y si falleciere antes de alcanzarla, a partir de la fecha del fallecimiento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">desde el día en que ésta haya alcanzado la mayoría de edad, y si falleciere antes de alcanzarla, a partir de la fecha del fallecimiento</mark></span>El <span class=\"ref-norma\">art. 132.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"los términos se computarán desde el día en que ésta haya alcanzado la mayoría de edad, y si falleciere antes de alcanzarla, a partir de la fecha del fallecimiento\"</span>. Desde la mayoría de edad de la víctima o su fallecimiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1543","p":"Código Penal. Interrupción de la prescripción. La prescripción se interrumpirá, quedando sin efecto el tiempo transcurrido, cuando el procedimiento se dirija contra la persona indiciariamente responsable del delito, comenzando a correr de nuevo:","o":["desde la firmeza de la resolución que acuerde la interrupción.","desde que se dicte sentencia en primera instancia.","desde que se paralice el procedimiento o termine sin condena.","desde que el imputado sea citado a declarar."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">desde que se paralice el procedimiento o termine sin condena</mark></span>El <span class=\"ref-norma\">art. 132.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"comenzando a correr de nuevo desde que se paralice el procedimiento o termine sin condena de acuerdo con las reglas siguientes\"</span>. Desde que se paralice el procedimiento o termine sin condena. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1544","p":"Código Penal. Interrupción de la prescripción. La presentación de querella o la denuncia formulada ante un órgano judicial, en la que se atribuya a una persona determinada su presunta participación en un hecho delictivo, suspenderá el cómputo de la prescripción por un plazo máximo de:","o":["tres meses, a contar desde la admisión a trámite de la querella o denuncia.","seis meses, a contar desde la misma fecha de presentación de la querella o de formulación de la denuncia.","un año, a contar desde la misma fecha de presentación de la querella o denuncia.","dos meses, a contar desde la misma fecha de presentación de la querella o denuncia, en los términos que se determinen reglamentariamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">seis meses, a contar desde la misma fecha de presentación de la querella o de formulación de la denuncia</mark></span>El <span class=\"ref-norma\">art. 132.2.2.ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"suspenderá el cómputo de la prescripción por un plazo máximo de seis meses, a contar desde la misma fecha de presentación de la querella o de formulación de la denuncia\"</span>. Seis meses desde la presentación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1545","p":"Código Penal. Interrupción de la prescripción. El cómputo del término de prescripción continuará desde la fecha de presentación de la querella o denuncia si, dentro del plazo de seis meses:","o":["recae resolución judicial firme de inadmisión a trámite de la querella o denuncia o por la que se acuerde no dirigir el procedimiento contra la persona querellada o denunciada.","se dicta resolución judicial de admisión a trámite de la querella o denuncia, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente.","el Ministerio Fiscal solicita el archivo de las diligencias.","se cita al querellado o denunciado como investigado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">recae resolución judicial firme de inadmisión a trámite de la querella o denuncia o por la que se acuerde no dirigir el procedimiento contra la persona querellada o denunciada</mark></span>El <span class=\"ref-norma\">art. 132.2.2.ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"si, dentro del plazo de seis meses, recae resolución judicial firme de inadmisión a trámite de la querella o denuncia o por la que se acuerde no dirigir el procedimiento contra la persona querellada o denunciada\"</span>. Inadmisión firme o resolución firme de no dirigir el procedimiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 20 EX","q":[{"i":"18-19","p":"Código Penal. Están exentos de responsabilidad criminal: señale la INCORRECTA.","o":["El que al tiempo de cometer la infracción penal, a causa de cualquier anomalía o alteración psíquica, no pueda comprender la ilicitud del hecho o actuar conforme a esa comprensión.","El que, en estado de necesidad, haya causado un mal mayor o ajeno para evitar un mal propio o ajeno, siempre que la situación de necesidad haya sido provocada intencionalmente por el sujeto.","El que, por sufrir alteraciones en la percepción desde el nacimiento o desde la infancia, tenga alterada gravemente la conciencia de la realidad.","El que obre en cumplimiento de un deber o en el ejercicio legítimo de un derecho, oficio o cargo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El que, en estado de necesidad, haya causado un mal mayor o ajeno para evitar un mal propio o ajeno, siempre que la situación de necesidad …</mark></span>- No existe exención cuando el sujeto ha provocado intencionalmente el estado de necesidad."},{"i":"18-62","p":"Código Penal. De las causas que eximen de la responsabilidad criminal. NO están exentos de responsabilidad criminal","o":["El que obre en cumplimiento de un deber o en el ejercicio legítimo de un derecho, oficio o cargo","El que actúe el culpable a causa de su grave adicción por el consumo de bebidas alcohólicas, drogas tóxicas, estupefacientes, sustancias psicotrópicas u otras que produzcan efectos análogos","El que, por sufrir alteraciones en la percepción desde el nacimiento o desde la infancia, tenga alterada gravemente la conciencia de la realidad","El que obre impulsado por miedo insuperable"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El que actúe el culpable a causa de su grave adicción por el consumo de bebidas alcohólicas, drogas tóxicas, estupefacientes, sustancias ps…</mark></span>- La adicción a drogas o alcohol no exime de responsabilidad criminal, aunque puede atenuarla."},{"i":"18-68","p":"Código Penal. De las causas que eximen de la responsabilidad criminal. Estará exento de responsabilidad criminal el que, en estado de necesidad, para evitar un mal propio o ajeno lesione un bien jurídico de otra persona o infrinja un deber, siempre que concurran los siguientes requisitos:","o":["Que el mal causado no sea mayor que el que se trate de evitar","El que obre impulsado por miedo insuperable","El que obre en cumplimiento de un deber o en el ejercicio legítimo de un derecho, oficio o cargo","Falta de provocación suficiente por parte del defensor"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Que el mal causado no sea mayor que el que se trate de evitar</mark></span>- En el estado de necesidad, el mal causado no debe ser mayor que el que se pretende evitar."},{"i":"18-76","p":"Código Penal. Derecho Penal. Parte General. Circunstancias modificativas de la Responsabilidad Criminal. Serán consideradas causa de eximente el que obre en defensa de la persona o derechos propios o ajenos, siempre que concurran los requisitos siguientes:","o":["Agresión ilegítima.","Necesidad racional del medio empleado para impedirla o repelerla.","Falta de provocación suficiente por parte del defensor.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Los tres requisitos de la legítima defensa son: agresión ilegítima, necesidad racional del medio y falta de provocación suficiente. Según el <span class=\"ref-norma\">art. 20 del Código Penal</span>: <span class=\"ref-concepto\">\"Segundo. Necesidad racional del medio empleado para impedirla o repelerla. Tercero. Falta de provocación suficiente por parte del defensor\"</span> (verificado con el texto del temario oficial)."},{"i":"18-175","p":"Código penal. Estará exento de responsabilidad criminal el que obre en defensa de la persona o derechos propios o ajenos, siempre que concurran los requisitos siguientes: señale la INCORRECTA.","o":["Agresión ilegítima.","Necesidad racional del medio empleado para impedirla o repelerla.","Falta de provocación suficiente por parte del defensor.","Que la situación de necesidad no haya sido provocada intencionadamente por el sujeto."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Que la situación de necesidad no haya sido provocada intencionadamente por el sujeto.</mark></span>(Este requisito corresponde a la legítima defensa, no al estado de necesidad)."},{"i":"18-224","p":"Código Penal. En caso de defensa de los bienes se reputará agresión ilegítima... indique la respuesta CORRECTA:","o":["El ataque a los mismos que constituya delito, exista o no peligro de deterioro o pérdida.","El ataque a los mismos que constituya delito y los ponga en peligro de deterioro o pérdida inminentes.","El ataque a los mismos que constituya delito y los ponga en grave peligro de deterioro o pérdida inminentes.","Ninguna de las respuestas anteriores es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El ataque a los mismos que constituya delito y los ponga en grave peligro de deterioro o pérdida inminentes.</mark></span><span class=\"ref-norma\">Art. 20.4 · De las Penas</span>. (El Artículo 20.4 del CP exige que el ataque constituya delito y ponga los bienes en &quot;grave peligro&quot; de deterioro o pérdida inminentes)."},{"i":"18-238","p":"Código Penal. En caso de defensa de la morada o sus dependencias, se reputará agresión ilegítima:","o":["La entrada indebida en aquélla o éstas.","El simple merodeo en las inmediaciones de la morada.","La entrada en la morada con el consentimiento del morador.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La entrada indebida en aquélla o éstas</mark></span>Según el <span class=\"ref-norma\">art. 20 del Código Penal</span>: <span class=\"ref-concepto\">\"En caso de defensa de la morada o sus dependencias, se reputará agresión ilegítima la entrada indebida en aquélla o éstas\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1040","p":"Código Penal. Anomalía psíquica. Están exentos de responsabilidad criminal el que al tiempo de cometer la infracción penal, a causa de cualquier anomalía o alteración psíquica, no pueda comprender la ilicitud del hecho o:","o":["controlar sus impulsos en ese momento.","actuar conforme a esa comprensión.","prever las consecuencias del hecho.","dirigir su voluntad al fin previsto."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">actuar conforme a esa comprensión</mark></span>El <span class=\"ref-norma\">art. 20.1º del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"no pueda comprender la ilicitud del hecho o actuar conforme a esa comprensión\"</span>. No poder comprender la ilicitud o actuar conforme a esa comprensión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1041","p":"Código Penal. Anomalía psíquica. El trastorno mental transitorio no eximirá de pena:","o":["cuando hubiese sido provocado por el sujeto con el propósito de cometer el delito o hubiera previsto o debido prever su comisión.","cuando el sujeto haya padecido anteriormente un trastorno de la misma naturaleza.","cuando hubiese sido provocado por el sujeto, aunque no tuviera propósito de cometer el delito, salvo que la autoridad judicial disponga otra cosa.","cuando el delito cometido sea grave."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cuando hubiese sido provocado por el sujeto con el propósito de cometer el delito o hubiera previsto o debido prever su comisión</mark></span>El <span class=\"ref-norma\">art. 20.1º del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"El trastorno mental transitorio no eximirá de pena cuando hubiese sido provocado por el sujeto con el propósito de cometer el delito o hubiera previsto o debido prever su comisión\"</span>. Excepción: trastorno provocado con propósito delictivo o previsible. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1042","p":"Código Penal. Intoxicación plena. Está exento de responsabilidad criminal el que al tiempo de cometer la infracción penal se halle en estado de intoxicación plena por el consumo de bebidas alcohólicas, drogas tóxicas, estupefacientes, sustancias psicotrópicas u otras que produzcan efectos análogos, siempre que:","o":["no haya sido buscado con el propósito de cometerla y se hubiera previsto su comisión.","no haya sido buscado con el propósito de cometerla, aun cuando se hubiese debido prever su comisión, previo informe de la unidad policial competente.","haya sido provocado por un tercero ajeno al sujeto.","no haya sido buscado con el propósito de cometerla o no se hubiese previsto o debido prever su comisión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no haya sido buscado con el propósito de cometerla o no se hubiese previsto o debido prever su comisión</mark></span>El <span class=\"ref-norma\">art. 20.2º del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"siempre que no haya sido buscado con el propósito de cometerla o no se hubiese previsto o debido prever su comisión\"</span>. La intoxicación plena exime si no fue buscada para delinquir o no se previó ni debió preverse. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1043","p":"Código Penal. Intoxicación plena. Está exento de responsabilidad criminal el que se halle bajo la influencia de un síndrome de abstinencia, a causa de su dependencia de tales sustancias, que le impida:","o":["controlar su conducta y prever las consecuencias de sus actos.","comprender la ilicitud del hecho y actuar conforme a esa comprensión, sin perjuicio de lo previsto en la normativa vigente.","comprender la ilicitud del hecho o actuar conforme a esa comprensión.","evitar la comisión del hecho, aunque comprenda su ilicitud."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">comprender la ilicitud del hecho o actuar conforme a esa comprensión</mark></span>El <span class=\"ref-norma\">art. 20.2º del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"que le impida comprender la ilicitud del hecho o actuar conforme a esa comprensión\"</span>. Se cumple con que le impida comprender la ilicitud o actuar conforme a esa comprensión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1044","p":"Código Penal. Alteraciones en la percepción. Está exento de responsabilidad criminal el que, por sufrir alteraciones en la percepción desde el nacimiento o desde la infancia, tenga alterada:","o":["parcialmente la capacidad de obrar.","gravemente la conciencia de la realidad.","totalmente la voluntad y el entendimiento.","de forma permanente la capacidad de comprender el hecho."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">gravemente la conciencia de la realidad</mark></span>El <span class=\"ref-norma\">art. 20.3º del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"tenga alterada gravemente la conciencia de la realidad\"</span>. Debe tener alterada gravemente la conciencia de la realidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1045","p":"Código Penal. Legítima defensa. Está exento de responsabilidad criminal el que obre en defensa de la persona o derechos propios o ajenos, siempre que concurran los requisitos siguientes. Señale la INCORRECTA:","o":["Proporcionalidad entre el mal causado y el mal que se trate de evitar.","Agresión ilegítima.","Necesidad racional del medio empleado para impedirla o repelerla, en los términos que se determinen reglamentariamente.","Falta de provocación suficiente por parte del defensor."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Proporcionalidad entre el mal causado y el mal que se trate de evitar</mark></span>El <span class=\"ref-norma\">art. 20.4º del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Primero. Agresión ilegítima. En caso de defensa de los bienes se reputará agresión ilegítima el ataque a los mismos que constituya delito y los ponga en grave peligro de deterioro o pérdida inminentes. En caso de defensa de la morada o sus dependencias, se reputará agresión ilegítima la entrada indebida en aquélla o éstas. Segundo. Necesidad racional del medio empleado para impedirla o repelerla. Tercero. Falta de provocación suficiente por parte del defensor\"</span>. Los requisitos son agresión ilegítima, necesidad racional del medio y falta de provocación suficiente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1046","p":"Código Penal. Legítima defensa. En caso de defensa de la morada o sus dependencias, se reputará agresión ilegítima:","o":["la entrada en aquélla o éstas con violencia o intimidación.","la entrada indebida en aquélla o éstas que ponga en peligro la vida de sus moradores.","la permanencia en aquélla o éstas tras requerimiento.","la entrada indebida en aquélla o éstas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la entrada indebida en aquélla o éstas</mark></span>El <span class=\"ref-norma\">art. 20.4º del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"En caso de defensa de la morada o sus dependencias, se reputará agresión ilegítima la entrada indebida en aquélla o éstas\"</span>. Basta la entrada indebida. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1047","p":"Código Penal. Legítima defensa. En caso de defensa de los bienes se reputará agresión ilegítima el ataque a los mismos que constituya delito y los ponga en:","o":["peligro de deterioro o pérdida.","grave peligro de destrucción total, salvo que la autoridad judicial disponga otra cosa.","grave peligro de deterioro o pérdida inminentes.","peligro inminente de sustracción."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">grave peligro de deterioro o pérdida inminentes</mark></span>El <span class=\"ref-norma\">art. 20.4º del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el ataque a los mismos que constituya delito y los ponga en grave peligro de deterioro o pérdida inminentes\"</span>. Debe constituir delito y poner los bienes en grave peligro de deterioro o pérdida inminentes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1049","p":"Código Penal. Estado de necesidad. Uno de los requisitos del estado de necesidad es que el necesitado no tenga, por su oficio o cargo, obligación de:","o":["sacrificarse.","intervenir.","denunciar.","auxiliar a terceros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">sacrificarse</mark></span>El <span class=\"ref-norma\">art. 20.5º del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Tercero. Que el necesitado no tenga, por su oficio o cargo, obligación de sacrificarse\"</span>. El necesitado no debe tener obligación de sacrificarse. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1050","p":"Código Penal. Miedo insuperable. Está exento de responsabilidad criminal el que obre impulsado por:","o":["temor racional y fundado.","miedo grave e inminente.","coacción o amenaza de un mal grave.","miedo insuperable."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">miedo insuperable</mark></span>El <span class=\"ref-norma\">art. 20.6º del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"El que obre impulsado por miedo insuperable\"</span>. La eximente exige miedo insuperable. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1051","p":"Código Penal. Cumplimiento de un deber. Está exento de responsabilidad criminal el que obre en cumplimiento de un deber o en el ejercicio legítimo de:","o":["un derecho o profesión.","una función pública o cargo.","un derecho, oficio o cargo.","un derecho, oficio o mandato."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">un derecho, oficio o cargo</mark></span>El <span class=\"ref-norma\">art. 20.7º del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"El que obre en cumplimiento de un deber o en el ejercicio legítimo de un derecho, oficio o cargo\"</span>. Derecho, oficio o cargo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1052","p":"Código Penal. Eximentes. En los supuestos de los tres primeros números del artículo que enumera las causas de exención de la responsabilidad criminal se aplicarán, en su caso:","o":["las penas inferiores en un grado.","las medidas de seguridad previstas en este Código.","las medidas cautelares previstas en la Ley de Enjuiciamiento Criminal.","las medidas de protección de la Ley Orgánica 1/1996."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las medidas de seguridad previstas en este Código</mark></span>El <span class=\"ref-norma\">art. 20 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"En los supuestos de los tres primeros números se aplicarán, en su caso, las medidas de seguridad previstas en este Código\"</span>. Los tres primeros números (anomalía, intoxicación, alteraciones de la percepción) llevan medidas de seguridad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 19","q":[{"i":"18-24","p":"Código Penal. De las causas que eximen de la responsabilidad criminal. Cuando un menor de dieciocho años cometa un hecho delictivo:","o":["Podrá ser responsable con arreglo a lo dispuesto en el presente Código.","No será responsable con arreglo a lo dispuesto en la ley que regula la responsabilidad penal del menor.","Podrá ser responsable con arreglo a lo dispuesto en la ley que regula la responsabilidad penal del menor.","Será responsable con arreglo a lo dispuesto en el presente Código."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Podrá ser responsable con arreglo a lo dispuesto en la ley que regula la responsabilidad penal del menor.</mark></span>- Los menores se rigen por la Ley Orgánica de Responsabilidad Penal del Menor."},{"i":"18-ia-1039","p":"Código Penal. Minoría de edad. Los menores de dieciocho años no serán responsables criminalmente con arreglo al Código Penal. Cuando un menor de dicha edad cometa un hecho delictivo:","o":["deberá ser puesto a disposición de la entidad pública de protección de menores, en los términos que se determinen reglamentariamente.","responderá con arreglo al Código Penal con la pena inferior en un grado.","podrá ser responsable con arreglo a lo dispuesto en la ley que regule la responsabilidad penal del menor.","quedará exento de toda responsabilidad, salvo la civil."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">podrá ser responsable con arreglo a lo dispuesto en la ley que regule la responsabilidad penal del menor</mark></span>El <span class=\"ref-norma\">art. 19 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Cuando un menor de dicha edad cometa un hecho delictivo podrá ser responsable con arreglo a lo dispuesto en la ley que regule la responsabilidad penal del menor\"</span>. El menor responde conforme a la ley que regula su responsabilidad penal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"De las Consecuencias Accesorias","q":[{"i":"18-25","p":"Código Penal. Los jueces y tribunales podrán acordar también el decomiso de los bienes, efectos y ganancias a que se refieren el Código que hayan sido transferidos a terceras personas, o de un valor equivalente a los mismos, en los siguientes casos:","o":["En el caso de los efectos y ganancias, cuando los hubieran adquirido con conocimiento de que proceden de una actividad ilícita o cuando una persona diligente habría tenido motivos para sospechar, en las circunstancias del caso, de su origen ilícito.","En el caso de otros bienes, cuando los hubieran adquirido con conocimiento de que de este modo se dificultaba su decomiso o cuando una persona diligente habría tenido motivos para sospechar, en las circunstancias del caso, que de ese modo se dificultaba su decomiso.","Cuando una persona diligente habría tenido motivos para sospechar, en las circunstancias del caso, que de ese modo se dificultaba su decomiso.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 127 quater del Código Penal</span>: <span class=\"ref-concepto\">\"a) En el caso de los efectos y ganancias, cuando los hubieran adquirido con conocimiento de que proceden de una actividad ilícita o cuando una persona diligente habría tenido motivos para sospechar, en las circunstancias del caso, de su origen ilícito\"</span> (verificado con el texto del temario oficial)."},{"i":"18-38","p":"Código Penal. El juez o tribunal ordenará también el decomiso de los bienes, efectos y ganancias pertenecientes a una persona condenada por alguno de los siguientes delitos cuando resuelva, a partir de indicios objetivos fundados, que los bienes o efectos provienen de una actividad delictiva, y no se acredite su origen lícito: señale la INCORRECTA.","o":["Delitos de falsedad documental","Delitos de trata de seres humanos","Delitos de corrupción en los negocios","Delitos de blanqueo de capitales"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Delitos de falsedad documental</mark></span>La falsedad documental no figura en el listado del decomiso ampliado. Según el <span class=\"ref-norma\">art. 127 bis del Código Penal</span>: <span class=\"ref-concepto\">\"a) Delitos de trata de seres humanos. a bis) Delitos de tráfico de órganos\"</span> (verificado con el texto del temario oficial)."},{"i":"18-50","p":"Código Penal. De las consecuencias accesorias. Hay tentativa cuando el sujeto","o":["Da principio a la ejecución del delito directamente por hechos exteriores, practicando todos o parte de los actos que objetivamente deberán producir o no el resultado y sin embargo éste no se produce","Da principio a la ejecución del delito directamente por hechos exteriores, practicando todos o parte de los actos que objetivamente deberán producir el resultado y sin embargo éste no se produce por causas dependientes del conocimiento del autor","Da principio a la ejecución del delito directamente por hechos exteriores, practicando todos o parte de los actos que objetivamente deberán producir el resultado y sin embargo éste no se produce por causas independientes de la voluntad del autor","Todas son incorrectas"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Da principio a la ejecución del delito directamente por hechos exteriores, practicando todos o parte de los actos que objetivamente deberán…</mark></span>- La tentativa requiere que el resultado no se produzca por causas ajenas a la voluntad del autor."},{"i":"18-73","p":"Código Penal. De las consecuencias accesorias. El Juez o Tribunal podrá acordar el decomiso aunque no medie sentencia de condena, cuando la situación patrimonial ilícita quede acreditada en un proceso contradictorio y se trate de alguno de los siguientes supuestos:","o":["Que el sujeto haya fallecido o sufra una enfermedad crónica que impida su enjuiciamiento y exista el riesgo de que puedan prescribir los hechos","Se encuentre en rebeldía y ello impida que los hechos puedan ser enjuiciados dentro de un plazo razonable","No se le imponga pena por estar exento de responsabilidad criminal o por haberse ésta extinguido.","Todas son correctas"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 127 ter del Código Penal</span>: <span class=\"ref-concepto\">\"c) no se le imponga pena por estar exento de responsabilidad criminal o por haberse ésta extinguido\"</span> (verificado con el texto del temario oficial)."},{"i":"18-79","p":"Código Penal. De las consecuencias accesorias. El juez o tribunal ordenará también el decomiso de los bienes, efectos y ganancias pertenecientes a una persona condenada por alguno de los siguientes delitos cuando resuelva, a partir de indicios objetivos fundados, que los bienes o efectos provienen de una actividad delictiva, y no se acredite su origen lícito:","o":["Delitos de trata de seres humanos","Delitos de tráfico de órganos","Delitos contra el patrimonio y contra el orden socioeconómico en los supuestos de continuidad delictiva y reincidencia","Todas son correctas"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>- Todos estos delitos permiten el decomiso cuando no se acredite el origen lícito de los bienes."},{"i":"18-ia-1509","p":"Código Penal. Decomiso sin sentencia. El juez o tribunal podrá acordar el decomiso aunque no medie sentencia de condena, cuando la situación patrimonial ilícita quede acreditada en un proceso contradictorio y, entre otros supuestos, cuando el sujeto:","o":["haya fallecido o sufra una enfermedad crónica que impida su enjuiciamiento y exista el riesgo de que puedan prescribir los hechos.","haya sido condenado en rebeldía a una pena inferior a un año, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente.","haya cumplido ya la pena privativa de libertad impuesta.","se encuentre en prisión provisional por los mismos hechos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">haya fallecido o sufra una enfermedad crónica que impida su enjuiciamiento y exista el riesgo de que puedan prescribir los hechos</mark></span>El <span class=\"ref-norma\">art. 127 ter.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"a) Que el sujeto haya fallecido o sufra una enfermedad crónica que impida su enjuiciamiento y exista el riesgo de que puedan prescribir los hechos\"</span>. Fallecimiento o enfermedad crónica, rebeldía, o ausencia de pena por exención o extinción. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1510","p":"Código Penal. Decomiso sin sentencia. El decomiso sin sentencia solamente podrá dirigirse contra quien haya sido formalmente acusado o contra el imputado:","o":["que haya sido detenido por los hechos, aunque no exista acusación formal, en los términos que se determinen reglamentariamente, salvo que la autoridad judicial disponga otra cosa.","con relación al que exista sentencia condenatoria no firme.","que sea titular de bienes de valor superior a 6.000 euros.","con relación al que existan indicios racionales de criminalidad cuando las situaciones previstas hubieran impedido la continuación del procedimiento penal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">con relación al que existan indicios racionales de criminalidad cuando las situaciones previstas hubieran impedido la continuación del procedimiento penal</mark></span>El <span class=\"ref-norma\">art. 127 ter.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"o contra el imputado con relación al que existan indicios racionales de criminalidad cuando las situaciones a que se refiere el apartado anterior hubieran impedido la continuación del procedimiento penal\"</span>. Acusado formalmente o imputado con indicios racionales de criminalidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1519","p":"Código Penal. Decomiso por valor equivalente. Si la ejecución del decomiso no hubiera podido llevarse a cabo, en todo o en parte, a causa de la naturaleza o situación de los bienes, efectos o ganancias, el juez o tribunal podrá, mediante auto, acordar el decomiso de otros bienes, incluso de origen lícito, que pertenezcan a los criminalmente responsables del hecho:","o":["por el doble del valor de la parte no ejecutada del decomiso.","por el valor total de los bienes inicialmente decomisados.","por un valor equivalente al de la parte no ejecutada del decomiso inicialmente acordado.","únicamente de origen ilícito, por el valor de la parte no ejecutada, sin perjuicio de lo previsto en la normativa vigente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por un valor equivalente al de la parte no ejecutada del decomiso inicialmente acordado</mark></span>El <span class=\"ref-norma\">art. 127 septies del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el juez o tribunal podrá, mediante auto, acordar el decomiso de otros bienes, incluso de origen lícito, que pertenezcan a los criminalmente responsables del hecho por un valor equivalente al de la parte no ejecutada del decomiso inicialmente acordado\"</span>. Por un valor equivalente a la parte no ejecutada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1521","p":"Código Penal. Aprehensión y destino de los bienes. Los bienes, instrumentos y ganancias decomisados por resolución firme, salvo que deban ser destinados al pago de indemnizaciones a las víctimas, serán adjudicados:","o":["al Estado, que les dará el destino que se disponga legal o reglamentariamente.","a la Administración de Justicia, para su subasta pública.","al Fondo de ayuda a las víctimas del delito.","a la Comunidad Autónoma en que se haya cometido el delito, salvo que la autoridad judicial disponga otra cosa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">al Estado, que les dará el destino que se disponga legal o reglamentariamente</mark></span>El <span class=\"ref-norma\">art. 127 octies.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"serán adjudicados al Estado, que les dará el destino que se disponga legal o reglamentariamente\"</span>. Se adjudican al Estado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1523","p":"Código Penal. Consecuencias accesorias a entidades sin personalidad jurídica. En caso de delitos cometidos en el seno, con la colaboración, a través o por medio de empresas, organizaciones, grupos o cualquier otra clase de entidades que, por carecer de personalidad jurídica, no estén comprendidas en el régimen de la responsabilidad penal de las personas jurídicas, el juez o tribunal podrá imponer motivadamente una o varias consecuencias accesorias a la pena que corresponda al autor del delito. Podrá también acordar:","o":["la disolución de la entidad y la liquidación de su patrimonio.","la prohibición temporal de llevar a cabo cualquier actividad por un máximo de cinco años.","la prohibición definitiva de llevar a cabo cualquier actividad, aunque sea lícita.","la inhabilitación de sus representantes legales por el mismo plazo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la prohibición definitiva de llevar a cabo cualquier actividad, aunque sea lícita</mark></span>El <span class=\"ref-norma\">art. 129.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Podrá también acordar la prohibición definitiva de llevar a cabo cualquier actividad, aunque sea lícita\"</span>. Prohibición definitiva de llevar a cabo cualquier actividad, aunque sea lícita. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1524","p":"Código Penal. Consecuencias accesorias a entidades sin personalidad jurídica. La clausura temporal de los locales o establecimientos, la suspensión de las actividades sociales y la intervención judicial podrán ser acordadas también por el Juez Instructor:","o":["únicamente en la sentencia condenatoria.","como medida cautelar durante la instrucción de la causa.","a petición exclusiva del Ministerio Fiscal, tras el juicio oral.","como pena accesoria de la privativa de libertad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">como medida cautelar durante la instrucción de la causa</mark></span>El <span class=\"ref-norma\">art. 129.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"podrán ser acordadas también por el Juez Instructor como medida cautelar durante la instrucción de la causa\"</span>. Como medida cautelar durante la instrucción. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1525","p":"Código Penal. Toma de muestras biológicas. Cuando de las circunstancias del hecho, antecedentes, valoración de su personalidad, o de otra información disponible pueda valorarse que existe un peligro relevante de reiteración delictiva, el juez o tribunal podrá acordar la toma de muestras biológicas y la realización de análisis para la obtención de identificadores de ADN e inscripción de los mismos en:","o":["la base de datos policial.","el Registro Central de Penados.","el registro de la Administración penitenciaria.","el Registro Civil."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la base de datos policial</mark></span>El <span class=\"ref-norma\">art. 129 bis del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"la toma de muestras biológicas de su persona y la realización de análisis para la obtención de identificadores de ADN e inscripción de los mismos en la base de datos policial\"</span>. En la base de datos policial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1526","p":"Código Penal. Toma de muestras biológicas. Únicamente podrán llevarse a cabo los análisis necesarios para obtener los identificadores que proporcionen, exclusivamente:","o":["información genética reveladora de la identidad y del origen étnico de la persona.","información genética reveladora de la identidad de la persona y de su estado de salud.","información genética reveladora de la filiación de la persona.","información genética reveladora de la identidad de la persona y de su sexo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">información genética reveladora de la identidad de la persona y de su sexo</mark></span>El <span class=\"ref-norma\">art. 129 bis del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"exclusivamente, información genética reveladora de la identidad de la persona y de su sexo\"</span>. Identidad y sexo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1527","p":"Código Penal. Toma de muestras biológicas. Si el afectado se opusiera a la recogida de las muestras, podrá imponerse su ejecución forzosa mediante el recurso a las medidas coactivas mínimas indispensables, que deberán ser en todo caso:","o":["autorizadas por el Juez de Vigilancia Penitenciaria y limitadas en el tiempo.","las que determine la autoridad policial bajo la supervisión del Ministerio Fiscal.","proporcionadas a las circunstancias del caso y respetuosas con su dignidad.","proporcionadas y ejecutadas por personal médico exclusivamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">proporcionadas a las circunstancias del caso y respetuosas con su dignidad</mark></span>El <span class=\"ref-norma\">art. 129 bis del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"que deberán ser en todo caso proporcionadas a las circunstancias del caso y respetuosas con su dignidad\"</span>. Proporcionadas y respetuosas con su dignidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 42","q":[{"i":"18-26","p":"Código Penal. ¿Qué pena produce la privación definitiva del empleo o cargo sobre el que recayere, aunque sea electivo, y de los honores que le sean anejos?:","o":["Inhabilitación especial para empleo o cargo público.","Inhabilitación absoluta para empleo o cargo público.","Suspensión de empleo o cargo público.","A y B son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Inhabilitación especial para empleo o cargo público</mark></span>La inhabilitación absoluta priva de «todos» los honores, empleos y cargos públicos; la que recae sobre «el empleo o cargo» concreto es la especial. Según el <span class=\"ref-norma\">art. 42 del Código Penal</span>: <span class=\"ref-concepto\">\"La pena de inhabilitación especial para empleo o cargo público produce la privación definitiva del empleo o cargo sobre el que recayere, aunque sea electivo, y de los honores que le sean anejos\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1218","p":"Código Penal. Inhabilitación especial para empleo o cargo público. La pena de inhabilitación especial para empleo o cargo público produce la privación definitiva del empleo o cargo sobre el que recayere, aunque sea electivo, y de los honores que le sean anejos. Produce, además, la incapacidad para obtener el mismo u otros análogos:","o":["de forma definitiva.","durante un plazo igual al de la condena incrementado en la mitad.","durante cinco años desde el cumplimiento de la condena.","durante el tiempo de la condena."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">durante el tiempo de la condena</mark></span>El <span class=\"ref-norma\">art. 42 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Produce, además, la incapacidad para obtener el mismo u otros análogos, durante el tiempo de la condena\"</span>. Durante el tiempo de la condena. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 33 ✱","q":[{"i":"18-32","p":"Código Penal. Los trabajos en beneficio de la comunidad de treinta y un días a un año es una pena:","o":["Leve.","Menos grave.","Grave.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Menos grave</mark></span>Según el <span class=\"ref-norma\">art. 33 del Código Penal</span>: <span class=\"ref-concepto\">\"l) Los trabajos en beneficio de la comunidad de treinta y un días a un año\"</span> (verificado con el texto del temario oficial)."},{"i":"18-53","p":"Código Penal. La clausura temporal de los locales o establecimientos, la suspensión de las actividades sociales y la intervención judicial podrán ser acordadas también por ______ como medida cautelar","o":["El Juez de Primera Instancia","El Juez Instructor","El Ministerio Fiscal","El Juez de lo Penal"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Juez Instructor</mark></span>- El Juez Instructor puede acordar estas medidas como medidas cautelares."},{"i":"18-77","p":"Código Penal. Cual de las siguientes Penas Graves NO se le puede aplicar a las personas jurídicas:","o":["Multa por cuota o proporcional","Inhabilitación Especial para cargo de Administrador hasta 5 años","Suspensión de sus actividades por un plazo de cuatro años","Clausura de sus locales y establecimientos por un plazo de cuatro años"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Inhabilitación Especial para cargo de Administrador hasta 5 años</mark></span>La suspensión de actividades no puede exceder de cinco años; la inhabilitación especial para cargo de administrador no figura entre las penas de las personas jurídicas. Según el <span class=\"ref-norma\">art. 33 del Código Penal</span>: <span class=\"ref-concepto\">\"c) Suspensión de sus actividades por un plazo que no podrá exceder de cinco años\"</span> (verificado con el texto del temario oficial)."},{"i":"18-99","p":"Código Penal. De las penas, sus clases y efectos. NO son penas menos graves:","o":["La privación del derecho a conducir vehículos a motor y ciclomotores","La prohibición de aproximarse a la víctima o a aquellos de sus familiares u otras personas que determine el juez o tribunal, por tiempo de seis meses a cinco años","La prohibición de comunicarse con la víctima o con aquellos de sus familiares u otras personas que determine el juez o tribunal, por tiempo de seis meses a cinco años","La privación del derecho a la tenencia y porte de armas de un año y un día a ocho años"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La privación del derecho a la tenencia y porte de armas de un año y un día a ocho años</mark></span>- La privación del derecho a tenencia y porte de armas de 1 año y 1 día a 8 años es pena grave."},{"i":"18-101","p":"Código Penal. De la responsabilidad civil y su extensión. La responsabilidad civil derivada de los delitos NO comprenderá:","o":["La restitución","La reparación del daño","La indemnización de perjuicios materiales y morales","La rehabilitación del derecho afectado"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La rehabilitación del derecho afectado</mark></span>- La rehabilitación del derecho afectado no forma parte de la responsabilidad civil."},{"i":"18-111","p":"Ley Orgánica 10/1995, de 23 de noviembre, del Código Penal. Las penas calificadas como graves: Señale la correcta.","o":["La suspensión de empleo o cargo público por tiempo superior a cinco años.","La multa de más de tres meses.","La prisión de tres meses hasta cinco años.","La localización permanente de un día a tres meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La suspensión de empleo o cargo público por tiempo superior a cinco años</mark></span>Las demás opciones son penas menos graves o leves. Según el <span class=\"ref-norma\">art. 33 del Código Penal</span>: <span class=\"ref-concepto\">\"e) La suspensión de empleo o cargo público por tiempo superior a cinco años\"</span> (verificado con el texto del temario oficial)."},{"i":"18-117","p":"Código Penal. ¿Cómo se clasifican las penas en función de su naturaleza y duración?","o":["Muy graves, graves y leves.","Simples, complejas y máximas.","Graves, menos graves y leves.","Temporales, permanentes y perpetuas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Graves, menos graves y leves.</mark></span>(Las penas se clasifican en graves, menos graves y leves según su naturaleza y duración)."},{"i":"18-164","p":"Código Penal. De las penas y sus clases. Las penas aplicables a las personas jurídicas tienen todas la consideración de:","o":["Graves.","Leves.","Menos graves.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Graves.</mark></span>(Todas las penas aplicables a personas jurídicas tienen consideración de graves)."},{"i":"18-169","p":"Código penal. De las penas y sus clases. La responsabilidad personal subsidiaria por impago de multa tendrá naturaleza:","o":["Grave, menos grave o leve, según la que corresponda a la pena que sustituya.","Grave o menos grave, según la que corresponda a la pena que sustituya.","Menos grave o leve, según la que corresponda a la pena que sustituya.","Leve, en todo caso."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Grave, menos grave o leve, según la que corresponda a la pena que sustituya.</mark></span>(La responsabilidad subsidiaria por impago de multa tiene la misma naturaleza que la pena sustituida)."},{"i":"18-195","p":"Código Penal. ¿Cuáles son las penas aplicables a las personas jurídicas, que tienen todas la consideración de graves? Señale la INCORRECTA:","o":["Multa por impago.","Disolución de la persona jurídica.","Suspensión de sus actividades por un plazo que no podrá exceder de cinco años.","Clausura de sus locales y establecimientos por un plazo que no podrá exceder de cinco años. *"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Multa por impago.</mark></span><span class=\"ref-norma\">Art. 33.7 · De las Personas Criminalmente Responsables de los Delitos</span>. Multa por impago. (&quot;Multa por impago&quot; no es una pena aplicable a personas jurídicas según el Artículo 33.7 del Código Penal. Las penas son multa (a secas), disolución, suspensión, clausura, etc.).*"},{"i":"18-201","p":"Código Penal. Son penas graves: señale la INCORRECTA.","o":["La privación de la patria potestad.","La prohibición de comunicarse con la víctima o con aquellos de sus familiares u otras personas que determine el juez o tribunal, por tiempo superior a cinco años.","La privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a cinco años.","La prisión permanente revisable. *"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a cinco años</mark></span>Es grave a partir de ocho años (no cinco); la privación de la patria potestad sí es grave. Según el <span class=\"ref-norma\">art. 33 del Código Penal</span>: <span class=\"ref-concepto\">\"f) La privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a ocho años\"</span> (verificado con el texto del temario oficial)."},{"i":"18-219","p":"Código Penal. Son penas menos graves... indique la que sea INCORRECTA:","o":["La prisión de tres meses hasta cinco años.","La privación de la patria potestad.","Las inhabilitaciones especiales hasta cinco años.","La suspensión de empleo o cargo público hasta cinco años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La privación de la patria potestad</mark></span>La privación de la patria potestad es pena grave (art. 33.2.k), no menos grave; la suspensión de empleo o cargo público hasta cinco años sí es menos grave. Según el <span class=\"ref-norma\">art. 33 del Código Penal</span>: <span class=\"ref-concepto\">\"k) La privación de la patria potestad\"</span> (verificado con el texto del temario oficial)."},{"i":"18-229","p":"Código Penal. ¿Cuál de las siguientes se considera como pena grave?","o":["Las inhabilitaciones especiales por tiempo superior a cinco años.","La privación del derecho a conducir vehículos a motor y ciclomotores de un año y un día a ocho años.","Inhabilitación especial para el ejercicio de profesión, oficio o comercio que tenga relación con los animales y para la tenencia de animales de un año y un día a cinco años.","La localización permanente de un día a tres meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las inhabilitaciones especiales por tiempo superior a cinco años.</mark></span><span class=\"ref-norma\">Art. 33.2 · De las Penas</span>. (Según el Artículo 33.2 del CP, las inhabilitaciones especiales superiores a cinco años son penas graves)."},{"i":"18-236","p":"Código Penal. La privación del derecho a la tenencia y porte de armas de un año y un día a ocho años, es una pena calificada como:","o":["Muy grave","Grave","Menos grave","Leve"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Grave</mark></span><span class=\"ref-norma\">Art. 33.2 · De las Penas</span>. (Según el Artículo 33.2 del CP, las penas de esta duración para este derecho son graves)."},{"i":"18-240","p":"Código Penal. La pena aplicable a las personas jurídicas sobre la prohibición de realizar en el futuro las actividades en cuyo ejercicio se haya cometido, favorecido o encubierto el delito. Esta prohibición podrá ser temporal o definitiva. Si fuere temporal el plazo no podrá exceder de:","o":["Diez años","Quince años","Cinco años","Veinte años"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Quince años</mark></span><span class=\"ref-norma\">Art. 33.7 · De las Personas Criminalmente Responsables de los Delitos</span>. (Según el Artículo 33.7 del CP, el plazo máximo para esta prohibición temporal es de quince años)."},{"i":"18-244","p":"Código Penal. Son penas menos graves: señale la INCORRECTA.","o":["La privación del derecho a conducir vehículos a motor y ciclomotores de un año y un día a ocho años.","La privación del derecho a la tenencia y porte de armas de un año y un día a ocho años.","Inhabilitación especial para el ejercicio de profesión, oficio o comercio que tenga relación con los animales y para la tenencia de animales de un año y un día a cinco años.","La privación del derecho a residir en determinados lugares o acudir a ellos, por tiempo de un año y un día a cinco años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La privación del derecho a residir en determinados lugares o acudir a ellos, por tiempo de un año y un día a cinco años</mark></span>Es de seis meses a cinco años (no de un año y un día a cinco). Según el <span class=\"ref-norma\">art. 33 del Código Penal</span>: <span class=\"ref-concepto\">\"g) La privación del derecho a residir en determinados lugares o acudir a ellos, por tiempo de seis meses a cinco años\"</span> (verificado con el texto del temario oficial)."},{"i":"18-254","p":"Código Penal. Penas graves. La privación del derecho a la tenencia y porte de armas es pena grave cuando se impone por tiempo superior a:","o":["Cinco años.","Diez años.","Ocho años.","Seis años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Ocho años</mark></span>El <span class=\"ref-norma\">art. 33.2.g) de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"La privación del derecho a la tenencia y porte de armas por tiempo superior a ocho años\"</span>"},{"i":"18-255","p":"Código Penal. Penas menos graves. La privación del derecho a conducir vehículos a motor y ciclomotores es pena menos grave cuando su duración es:","o":["De tres meses a un año.","De un año y un día a ocho años.","De seis meses a cinco años.","De un año y un día a cinco años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">De un año y un día a ocho años</mark></span>El <span class=\"ref-norma\">art. 33.3.d) de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"La privación del derecho a conducir vehículos a motor y ciclomotores de un año y un día a ocho años\"</span>"},{"i":"18-256","p":"Código Penal. Penas menos graves. La inhabilitación especial para el ejercicio de profesión, oficio o comercio que tenga relación con los animales y para la tenencia de animales es pena menos grave cuando su duración es:","o":["De un año y un día a cinco años.","De seis meses a cinco años.","De tres meses a un año.","De un año y un día a ocho años, salvo que el órgano competente acuerde otra cosa de forma motivada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">De un año y un día a cinco años</mark></span>El <span class=\"ref-norma\">art. 33.3.f) de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"Inhabilitación especial para el ejercicio de profesión, oficio o comercio que tenga relación con los animales y para la tenencia de animales de un año y un día a cinco años\"</span>"},{"i":"18-257","p":"Código Penal. Penas menos graves. La prohibición de aproximarse a la víctima o a aquellos de sus familiares u otras personas que determine el juez o tribunal es pena menos grave cuando se impone por tiempo de:","o":["Un mes a menos de seis meses.","Un año y un día a ocho años.","Tres meses a cinco años.","Seis meses a cinco años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Seis meses a cinco años</mark></span>El <span class=\"ref-norma\">art. 33.3.h) de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"La prohibición de aproximarse a la víctima o a aquellos de sus familiares u otras personas que determine el juez o tribunal, por tiempo de seis meses a cinco años\"</span>"},{"i":"18-258","p":"Código Penal. Penas menos graves. La prohibición de comunicarse con la víctima o con aquellos de sus familiares u otras personas que determine el juez o tribunal es pena menos grave cuando se impone por tiempo de:","o":["Un mes a menos de seis meses.","Un año y un día a ocho años.","Seis meses a cinco años.","Tres meses a cinco años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Seis meses a cinco años</mark></span>El <span class=\"ref-norma\">art. 33.3.i) de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"La prohibición de comunicarse con la víctima o con aquellos de sus familiares u otras personas que determine el juez o tribunal, por tiempo de seis meses a cinco años\"</span>"},{"i":"18-259","p":"Código Penal. Penas menos graves. La pena de multa es pena menos grave cuando es:","o":["De hasta tres meses.","De más de tres meses.","De más de seis meses, conforme al procedimiento que reglamentariamente se establezca.","De más de un año."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">De más de tres meses</mark></span>El <span class=\"ref-norma\">art. 33.3.j) de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"La multa de más de tres meses\"</span>"},{"i":"18-260","p":"Código Penal. Penas menos graves. La multa proporcional es pena menos grave:","o":["Cualquiera que fuese su cuantía, salvo lo dispuesto para las penas aplicables a las personas jurídicas.","Solo cuando su cuantía exceda de seis mil euros.","Solo cuando se imponga conjuntamente con una pena privativa de libertad.","Únicamente cuando el condenado sea una persona física con antecedentes penales, sin perjuicio de lo que establezcan los tratados internacionales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cualquiera que fuese su cuantía, salvo lo dispuesto para las penas aplicables a las personas jurídicas</mark></span>El <span class=\"ref-norma\">art. 33.3.k) de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"La multa proporcional, cualquiera que fuese su cuantía, salvo lo dispuesto en el apartado 7 de este artículo\"</span>"},{"i":"18-ia-1128","p":"Código Penal. Sociedades mercantiles públicas. En el caso de las Sociedades mercantiles públicas que ejecuten políticas públicas o presten servicios de interés económico general, solamente les podrán ser impuestas las penas de:","o":["multa y disolución de la persona jurídica.","multa e intervención judicial.","suspensión de actividades e intervención judicial.","multa y clausura de locales y establecimientos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">multa e intervención judicial</mark></span>El <span class=\"ref-norma\">art. 31 quinquies.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"solamente les podrán ser impuestas las penas previstas en las letras a) y g) del apartado 7 del artículo 33\"</span>. Las letras a) y g) son multa e intervención judicial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1130","p":"Código Penal. Clasificación de las penas. En función de su naturaleza y duración, las penas se clasifican en:","o":["graves, medias y leves.","principales, accesorias y leves.","graves y leves, según su naturaleza y duración.","graves, menos graves y leves."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">graves, menos graves y leves</mark></span>El <span class=\"ref-norma\">art. 33.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"En función de su naturaleza y duración, las penas se clasifican en graves, menos graves y leves\"</span>. Tres categorías: graves, menos graves y leves. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1131","p":"Código Penal. Penas graves. Señale la INCORRECTA. Son penas graves:","o":["La prisión permanente revisable.","La inhabilitación absoluta.","La prisión superior a tres años.","La privación de la patria potestad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La prisión superior a tres años</mark></span>El <span class=\"ref-norma\">art. 33.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"a) La prisión permanente revisable. b) La prisión superior a cinco años\"</span>. La prisión es pena grave cuando supera los cinco años, no los tres. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1133","p":"Código Penal. Penas graves. Es pena grave la privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a:","o":["ocho años.","cinco años.","seis años.","diez años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">ocho años</mark></span>El <span class=\"ref-norma\">art. 33.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a ocho años\"</span>. Conducción y armas: más de ocho años; residencia, aproximación y comunicación: más de cinco. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1135","p":"Código Penal. Penas menos graves. Son penas menos graves la prisión de:","o":["seis meses hasta cinco años, salvo que la autoridad judicial disponga otra cosa.","tres meses hasta tres años.","tres meses hasta cinco años.","un año hasta cinco años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">tres meses hasta cinco años</mark></span>El <span class=\"ref-norma\">art. 33.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"a) La prisión de tres meses hasta cinco años\"</span>. Prisión menos grave: de tres meses hasta cinco años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1136","p":"Código Penal. Penas menos graves. Es pena menos grave la privación del derecho a conducir vehículos a motor y ciclomotores de:","o":["un año a ocho años.","un año y un día a ocho años.","seis meses a ocho años.","un año y un día a cinco años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">un año y un día a ocho años</mark></span>El <span class=\"ref-norma\">art. 33.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"d) La privación del derecho a conducir vehículos a motor y ciclomotores de un año y un día a ocho años\"</span>. De un año y un día a ocho años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1137","p":"Código Penal. Penas menos graves. Son penas menos graves los trabajos en beneficio de la comunidad de:","o":["treinta y un días a un año.","uno a treinta días.","treinta días a un año.","treinta y un días a dos años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">treinta y un días a un año</mark></span>El <span class=\"ref-norma\">art. 33.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"l) Los trabajos en beneficio de la comunidad de treinta y un días a un año\"</span>. Menos grave: treinta y un días a un año; leve: uno a treinta días. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1138","p":"Código Penal. Penas menos graves. Señale la INCORRECTA. Son penas menos graves:","o":["La multa de más de tres meses.","La multa proporcional, cualquiera que fuese su cuantía, salvo lo dispuesto en el apartado 7 de este artículo.","La suspensión de empleo o cargo público hasta cinco años.","La multa de hasta tres meses."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La multa de hasta tres meses</mark></span>El <span class=\"ref-norma\">art. 33.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"g) La multa de hasta tres meses\"</span>. La multa de hasta tres meses es pena leve; la de más de tres meses es menos grave. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1139","p":"Código Penal. Penas menos graves. Es pena menos grave la prohibición de comunicarse con la víctima o con aquellos de sus familiares u otras personas que determine el juez o tribunal, por tiempo de:","o":["un mes a cinco años.","seis meses a tres años, previo informe de la unidad policial competente.","seis meses a cinco años.","un año a cinco años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">seis meses a cinco años</mark></span>El <span class=\"ref-norma\">art. 33.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"i) La prohibición de comunicarse con la víctima o con aquellos de sus familiares u otras personas que determine el juez o tribunal, por tiempo de seis meses a cinco años\"</span>. Menos grave: seis meses a cinco años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1140","p":"Código Penal. Penas leves. Es pena leve la localización permanente de:","o":["un día a seis meses, sin perjuicio de lo previsto en la normativa vigente.","un día a tres meses.","un mes a tres meses.","tres meses a un año."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">un día a tres meses</mark></span>El <span class=\"ref-norma\">art. 33.4 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"h) La localización permanente de un día a tres meses\"</span>. Leve: un día a tres meses. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1141","p":"Código Penal. Penas leves. Es pena leve la privación del derecho a conducir vehículos a motor y ciclomotores de:","o":["tres meses a un año.","un mes a un año.","seis meses a un año.","tres meses a dos años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">tres meses a un año</mark></span>El <span class=\"ref-norma\">art. 33.4 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"a) La privación del derecho a conducir vehículos a motor y ciclomotores de tres meses a un año\"</span>. Leve: tres meses a un año. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1142","p":"Código Penal. Penas leves. Es pena leve la prohibición de aproximarse a la víctima o a aquellos de sus familiares u otras personas que determine el juez o tribunal, por tiempo de:","o":["tres meses a menos de seis meses.","un mes a un año.","uno a treinta días.","un mes a menos de seis meses."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">un mes a menos de seis meses</mark></span>El <span class=\"ref-norma\">art. 33.4 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"e) La prohibición de aproximarse a la víctima o a aquellos de sus familiares u otras personas que determine el juez o tribunal, por tiempo de un mes a menos de seis meses\"</span>. Leve: de un mes a menos de seis meses. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1143","p":"Código Penal. Penas leves. Es pena leve la privación del derecho a residir en determinados lugares o acudir a ellos, por tiempo:","o":["de un mes a seis meses.","inferior a tres meses.","inferior a seis meses.","no superior a un año."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">inferior a seis meses</mark></span>El <span class=\"ref-norma\">art. 33.4 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"d) La privación del derecho a residir en determinados lugares o acudir a ellos, por tiempo inferior a seis meses\"</span>. Leve: inferior a seis meses. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1144","p":"Código Penal. Responsabilidad personal subsidiaria. La responsabilidad personal subsidiaria por impago de multa tendrá naturaleza menos grave o leve, según:","o":["la cuantía de la multa impagada.","la que corresponda a la pena que sustituya.","la que decida el Juez o Tribunal.","la situación económica del condenado, en los términos que se determinen reglamentariamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la que corresponda a la pena que sustituya</mark></span>El <span class=\"ref-norma\">art. 33.5 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"tendrá naturaleza menos grave o leve, según la que corresponda a la pena que sustituya\"</span>. Su naturaleza depende de la pena que sustituye. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1145","p":"Código Penal. Penas accesorias. Las penas accesorias tendrán la duración que respectivamente tenga la pena principal, excepto:","o":["lo que dispongan expresamente otros preceptos del Código.","lo que decida motivadamente el Juez o Tribunal.","cuando la pena principal sea superior a cinco años, salvo que la autoridad judicial disponga otra cosa.","cuando concurran circunstancias atenuantes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">lo que dispongan expresamente otros preceptos del Código</mark></span>El <span class=\"ref-norma\">art. 33.6 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"excepto lo que dispongan expresamente otros preceptos de este Código\"</span>. La excepción debe estar prevista expresamente en otros preceptos del Código. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1147","p":"Código Penal. Penas aplicables a las personas jurídicas. La disolución de la persona jurídica producirá:","o":["la pérdida temporal de su personalidad jurídica y la prohibición de realizar actividades ilícitas.","la pérdida definitiva de su personalidad jurídica, pero no de su capacidad para llevar a cabo actividades lícitas, en los términos que se determinen reglamentariamente, salvo que la autoridad judicial disponga otra cosa.","la pérdida definitiva de su personalidad jurídica, así como la de su capacidad de actuar de cualquier modo en el tráfico jurídico, o llevar a cabo cualquier clase de actividad, aunque sea lícita.","la suspensión de su capacidad de actuar en el tráfico jurídico por un plazo máximo de cinco años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la pérdida definitiva de su personalidad jurídica, así como la de su capacidad de actuar de cualquier modo en el tráfico jurídico, o llevar a cabo cualquier clase de actividad, aunque sea lícita</mark></span>El <span class=\"ref-norma\">art. 33.7 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La disolución producirá la pérdida definitiva de su personalidad jurídica, así como la de su capacidad de actuar de cualquier modo en el tráfico jurídico, o llevar a cabo cualquier clase de actividad, aunque sea lícita\"</span>. Pérdida definitiva de la personalidad jurídica y de la capacidad de actuar, aunque la actividad sea lícita. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1149","p":"Código Penal. Penas aplicables a las personas jurídicas. La prohibición de realizar en el futuro las actividades en cuyo ejercicio se haya cometido, favorecido o encubierto el delito podrá ser temporal o definitiva. Si fuere temporal, el plazo no podrá exceder de:","o":["quince años.","cinco años.","diez años.","veinte años, previo informe de la unidad policial competente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">quince años</mark></span>El <span class=\"ref-norma\">art. 33.7 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Esta prohibición podrá ser temporal o definitiva. Si fuere temporal, el plazo no podrá exceder de quince años\"</span>. Prohibición temporal: hasta quince años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1150","p":"Código Penal. Penas aplicables a las personas jurídicas. La inhabilitación para obtener subvenciones y ayudas públicas, para contratar con el sector público y para gozar de beneficios e incentivos fiscales o de la Seguridad Social se impone a las personas jurídicas por un plazo que no podrá exceder de:","o":["cinco años.","diez años.","veinte años, sin perjuicio de lo previsto en la normativa vigente.","quince años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">quince años</mark></span>El <span class=\"ref-norma\">art. 33.7 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Inhabilitación para obtener subvenciones y ayudas públicas, para contratar con el sector público y para gozar de beneficios e incentivos fiscales o de la Seguridad Social, por un plazo que no podrá exceder de quince años\"</span>. Inhabilitación: hasta quince años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1151","p":"Código Penal. Penas aplicables a las personas jurídicas. La intervención judicial de una persona jurídica para salvaguardar los derechos de los trabajadores o de los acreedores podrá afectar:","o":["únicamente a la totalidad de la organización.","a la dirección de la empresa, con exclusión de sus instalaciones.","a la totalidad de la organización o limitarse a alguna de sus instalaciones, secciones o unidades de negocio.","a la totalidad de la organización por un plazo máximo de diez años, en los términos que se determinen reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">a la totalidad de la organización o limitarse a alguna de sus instalaciones, secciones o unidades de negocio</mark></span>El <span class=\"ref-norma\">art. 33.7 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La intervención podrá afectar a la totalidad de la organización o limitarse a alguna de sus instalaciones, secciones o unidades de negocio\"</span>. Puede ser total o limitarse a instalaciones, secciones o unidades de negocio. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1152","p":"Código Penal. Penas aplicables a las personas jurídicas. La clausura temporal de los locales o establecimientos, la suspensión de las actividades sociales y la intervención judicial podrán ser acordadas también por el Juez Instructor:","o":["como pena accesoria en el auto de procesamiento.","como medida cautelar durante la instrucción de la causa.","como medida de seguridad durante el juicio oral.","como medida cautelar, previa audiencia del Ministerio Fiscal y por un máximo de seis meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">como medida cautelar durante la instrucción de la causa</mark></span>El <span class=\"ref-norma\">art. 33.7 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"podrán ser acordadas también por el Juez Instructor como medida cautelar durante la instrucción de la causa\"</span>. El Juez Instructor puede acordarlas como medida cautelar durante la instrucción. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 31","q":[{"i":"18-33","p":"Código Penal. Responsabilidad civil y su extensión. El que actúe como ______ de hecho o de derecho de una persona jurídica, o en nombre o representación legal o voluntaria de otro, responderá personalmente, aunque no concurran en él las condiciones, cualidades o relaciones que la correspondiente figura de delito requiera para poder ser sujeto activo del mismo, si tales circunstancias se dan en la entidad o persona en cuyo nombre o representación obre","o":["Persona jurídica","Administrador","Responsable","Todas son incorrectas"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Administrador</mark></span>- El administrador de hecho o de derecho responde personalmente por los delitos cometidos en nombre de la persona jurídica."},{"i":"18-63","p":"Código Penal. De las personas criminalmente responsables de los delitos. El que actúe como administrador de hecho o de derecho de una persona jurídica, o en nombre o representación legal o voluntaria de otro, responderá ____ aunque no concurran en él las condiciones, cualidades o relaciones que la correspondiente figura de delito requiera para poder ser sujeto activo del mismo, si tales circunstancias se dan en la entidad o persona en cuyo nombre o representación obre","o":["Según su grado de implicación","Solidariamente","En el propio nombre","Personalmente"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Personalmente</mark></span>- El administrador responde personalmente por los delitos cometidos en representación de la persona jurídica."},{"i":"18-ia-1112","p":"Código Penal. Actuación en nombre de otro. El que actúe como administrador de hecho o de derecho de una persona jurídica, o en nombre o representación legal o voluntaria de otro, responderá personalmente, aunque no concurran en él las condiciones, cualidades o relaciones que la correspondiente figura de delito requiera para poder ser sujeto activo del mismo, si tales circunstancias se dan en:","o":["el órgano de administración de la entidad.","la entidad o persona en cuyo nombre o representación obre.","los socios o accionistas de la entidad en cuyo nombre obre.","la persona física que haya otorgado la representación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la entidad o persona en cuyo nombre o representación obre</mark></span>El <span class=\"ref-norma\">art. 31 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"si tales circunstancias se dan en la entidad o persona en cuyo nombre o representación obre\"</span>. Las circunstancias deben darse en la entidad o persona representada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 122","q":[{"i":"18-35","p":"Código Penal. El que por título lucrativo hubiere participado de los efectos de un delito, está obligado a la restitución de la cosa o al resarcimiento del daño:","o":["Hasta la cuantía de su participación","Hasta la cuantía de su participación total de los integrantes","Hasta la cuantía determinada por el Juez o Tribunal","Todas son incorrectas"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Hasta la cuantía de su participación</mark></span>- Responde hasta la cuantía de su participación en los efectos del delito."},{"i":"18-142","p":"Código Penal. ¿Qué obligación tiene alguien que ha participado de los efectos de un delito por título lucrativo?","o":["Debe pagar una multa.","Debe comparecer ante la autoridad judicial.","Debe restituir la cosa o resarcir el daño.","Debe colaborar con la investigación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Debe restituir la cosa o resarcir el daño.</mark></span>(Quien se lucra con un delito debe restituir lo obtenido o resarcir el daño)."},{"i":"18-ia-1501","p":"Código Penal. Participación a título lucrativo. El que por título lucrativo hubiere participado de los efectos de un delito, está obligado a la restitución de la cosa o al resarcimiento del daño:","o":["hasta la cuantía de su participación.","por el valor total de los efectos del delito.","solidariamente con el autor del delito.","hasta la mitad del valor de los efectos recibidos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">hasta la cuantía de su participación</mark></span>El <span class=\"ref-norma\">art. 122 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"está obligado a la restitución de la cosa o al resarcimiento del daño hasta la cuantía de su participación\"</span>. Hasta la cuantía de su participación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 136 EXOF","q":[{"i":"18-40","p":"Código Penal. De la cancelación de los antecedentes delictivos. Los condenados que hayan extinguido su responsabilidad penal tienen derecho a obtener del _____ de oficio o a instancia de parte, la cancelación de sus antecedentes penales","o":["Ministerio de Interior","Delegado del Gobierno","Ministerio de Justicia","Ministerio Fiscal"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Ministerio de Justicia</mark></span>- Corresponde al Ministerio de Justicia la cancelación de antecedentes penales."},{"i":"18-87","p":"Código Penal. Extinción de la Responsabilidad Criminal y sus efectos. Las Penas impuestas a las personas jurídicas y las consecuencias accesorias se cancelarán en el plazo que corresponda, salvo que se hubiese acordado la liquidación o la prohibición definitiva de actividades, en cuyo caso se cancelarán las anotaciones:","o":["Transcurridos veinticinco años computables desde el día siguiente a la firmeza de la sentencia.","Transcurridos veinte años computables desde el día siguiente a la firmeza de la sentencia","Transcurridos quince años computables desde el día siguiente a la firmeza de la sentencia","Transcurridos cincuenta años computables desde el día siguiente a la firmeza de la sentencia"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Transcurridos cincuenta años computables desde el día siguiente a la firmeza de la sentencia</mark></span>El texto vigente dice cincuenta años (no veinte). Según el <span class=\"ref-norma\">art. 136 del Código Penal</span>: <span class=\"ref-concepto\">\"se cancelarán las anotaciones transcurridos cincuenta años computados desde el día siguiente a la firmeza de la sentencia\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1551","p":"Código Penal. Cancelación de antecedentes delictivos. Los condenados que hayan extinguido su responsabilidad penal tienen derecho a obtener del Ministerio de Justicia, de oficio o a instancia de parte, la cancelación de sus antecedentes penales, cuando hayan transcurrido sin haber vuelto a delinquir seis meses para:","o":["las penas que no excedan de doce meses.","las impuestas por delitos imprudentes.","las penas leves.","las restantes penas menos graves."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las penas leves</mark></span>El <span class=\"ref-norma\">art. 136.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"a) Seis meses para las penas leves\"</span>. Seis meses: penas leves. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1552","p":"Código Penal. Cancelación de antecedentes delictivos. El plazo para cancelar los antecedentes penales es de dos años para:","o":["las penas leves.","las penas que no excedan de doce meses y las impuestas por delitos imprudentes.","las restantes penas menos graves inferiores a tres años, previo informe de la unidad policial competente.","las penas graves."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las penas que no excedan de doce meses y las impuestas por delitos imprudentes</mark></span>El <span class=\"ref-norma\">art. 136.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"b) Dos años para las penas que no excedan de doce meses y las impuestas por delitos imprudentes\"</span>. Dos años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1553","p":"Código Penal. Cancelación de antecedentes delictivos. El plazo para cancelar los antecedentes penales es de cinco años para:","o":["las restantes penas menos graves iguales o superiores a tres años.","las restantes penas menos graves inferiores a tres años, sin perjuicio de lo previsto en la normativa vigente.","las penas graves.","las penas que no excedan de doce meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">las restantes penas menos graves iguales o superiores a tres años</mark></span>El <span class=\"ref-norma\">art. 136.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"d) Cinco años para las restantes penas menos graves iguales o superiores a tres años\"</span>. Cinco años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1554","p":"Código Penal. Cancelación de antecedentes delictivos. El plazo para cancelar los antecedentes penales es de diez años para:","o":["las penas menos graves iguales o superiores a tres años.","las penas de prisión superiores a cinco años.","las penas impuestas por delitos dolosos.","las penas graves."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las penas graves</mark></span>El <span class=\"ref-norma\">art. 136.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"e) Diez años para las penas graves\"</span>. Diez años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1555","p":"Código Penal. Cancelación de antecedentes delictivos. Las penas impuestas a las personas jurídicas y las consecuencias accesorias se cancelarán en el plazo que corresponda, salvo que se hubiese acordado la disolución o la prohibición definitiva de actividades. En estos casos, se cancelarán las anotaciones transcurridos:","o":["veinticinco años computados desde el día siguiente a la firmeza de la sentencia.","treinta años computados desde el cumplimiento de la pena.","cincuenta años computados desde el día siguiente a la firmeza de la sentencia.","diez años computados desde el día siguiente a la firmeza de la sentencia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">cincuenta años computados desde el día siguiente a la firmeza de la sentencia</mark></span>El <span class=\"ref-norma\">art. 136.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"se cancelarán las anotaciones transcurridos cincuenta años computados desde el día siguiente a la firmeza de la sentencia\"</span>. Cincuenta años desde el día siguiente a la firmeza. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1556","p":"Código Penal. Cancelación de antecedentes delictivos. Las inscripciones de antecedentes penales en las distintas secciones del Registro Central de Penados y Rebeldes:","o":["serán públicas durante su vigencia.","no serán públicas.","serán públicas para los operadores jurídicos.","serán públicas una vez cumplida la pena."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">no serán públicas</mark></span>El <span class=\"ref-norma\">art. 136.4 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Las inscripciones de antecedentes penales en las distintas secciones del Registro Central de Penados y Rebeldes no serán públicas\"</span>. No son públicas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1557","p":"Código Penal. Cancelación de antecedentes delictivos. En los casos en que, a pesar de cumplirse los requisitos establecidos para la cancelación, ésta no se haya producido, el juez o tribunal, acreditadas tales circunstancias:","o":["no tendrá en cuenta dichos antecedentes.","tendrá en cuenta dichos antecedentes como agravante.","solicitará su cancelación de oficio al Ministerio de Justicia.","valorará dichos antecedentes con atenuación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no tendrá en cuenta dichos antecedentes</mark></span>El <span class=\"ref-norma\">art. 136.5 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el juez o tribunal, acreditadas tales circunstancias, no tendrá en cuenta dichos antecedentes\"</span>. No los tendrá en cuenta. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 74 ✱","q":[{"i":"18-41","p":"Código Penal. ¿Cuándo el juez o tribunal podrá imponer motivadamente la pena superior en uno o dos grados, en la extensión que estime conveniente en las infracciones contra el patrimonio?","o":["Si el hecho no revistiere notoria gravedad y hubiere perjudicado a una generalidad de personas","Si el hecho revistiere notoria gravedad y hubiere perjudicado a una generalidad de personas","Si el hecho revistiere notoria gravedad y hubiere perjudicado a una sola persona","Todas son correctas"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Si el hecho revistiere notoria gravedad y hubiere perjudicado a una generalidad de personas</mark></span>Según el <span class=\"ref-norma\">art. 74 del Código Penal</span>: <span class=\"ref-concepto\">\"si el hecho revistiere notoria gravedad y hubiere perjudicado a una generalidad de personas\"</span> (verificado con el texto del temario oficial)."},{"i":"18-193","p":"Código Penal. De los delitos. Señale la INCORRECTA:","o":["Son delitos graves las infracciones que la Ley castiga con pena grave.","Son delitos menos graves las infracciones que la Ley castiga con pena menos grave.","Son delitos muy graves las infracciones que la Ley castiga con pena muy grave.","Son delitos leves las infracciones que la Ley castiga con pena leve. *"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Son delitos muy graves las infracciones que la Ley castiga con pena muy grave.</mark></span>Son delitos muy graves las infracciones que la Ley castiga con pena muy grave. (La clasificación tripartita del Código Penal español es: delitos graves, menos graves y faltas/delitos leves. No existe la categoría &quot;muy graves&quot;).*"},{"i":"18-274","p":"Código Penal. Delito continuado. Quedan exceptuadas de las reglas del delito continuado las ofensas a bienes eminentemente personales, salvo las constitutivas de infracciones contra el honor y la libertad e indemnidad sexuales que afecten:","o":["A distintos sujetos pasivos.","A una generalidad de personas.","Al mismo sujeto pasivo.","A personas menores de edad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Al mismo sujeto pasivo</mark></span>El <span class=\"ref-norma\">art. 74.3 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"salvo las constitutivas de infracciones contra el honor y la libertad e indemnidad sexuales que afecten al mismo sujeto pasivo\"</span>"},{"i":"18-ia-1319","p":"Código Penal. Delito continuado. El que, en ejecución de un plan preconcebido o aprovechando idéntica ocasión, realice una pluralidad de acciones u omisiones que ofendan a uno o varios sujetos e infrinjan el mismo precepto penal o preceptos de igual o semejante naturaleza, será castigado como autor de un delito continuado con la pena señalada para la infracción más grave, que se impondrá:","o":["en su mitad inferior, pudiendo llegar hasta la mitad superior de la pena señalada, sin perjuicio de lo previsto en la normativa vigente.","en su mitad superior, sin que pueda llegar a la pena superior en grado.","en su mitad superior, pudiendo llegar hasta la mitad inferior de la pena superior en grado.","en su grado máximo, pudiendo llegar hasta la pena superior en un grado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en su mitad superior, pudiendo llegar hasta la mitad inferior de la pena superior en grado</mark></span>El <span class=\"ref-norma\">art. 74.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"con la pena señalada para la infracción más grave, que se impondrá en su mitad superior, pudiendo llegar hasta la mitad inferior de la pena superior en grado\"</span>. Mitad superior, pudiendo llegar a la mitad inferior de la pena superior en grado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1320","p":"Código Penal. Delito continuado. Si se tratare de infracciones contra el patrimonio, se impondrá la pena teniendo en cuenta el perjuicio total causado. En estas infracciones el Juez o Tribunal impondrá, motivadamente, la pena superior en uno o dos grados, en la extensión que estime conveniente, si el hecho revistiere notoria gravedad y:","o":["hubiere sido cometido por una organización criminal.","hubiere perjudicado a una generalidad de personas.","el perjuicio causado excediera de 50.000 euros.","hubiere causado un perjuicio a la Administración pública."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">hubiere perjudicado a una generalidad de personas</mark></span>El <span class=\"ref-norma\">art. 74.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"si el hecho revistiere notoria gravedad y hubiere perjudicado a una generalidad de personas\"</span>. Notoria gravedad y perjuicio a una generalidad de personas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1321","p":"Código Penal. Delito continuado. Quedan exceptuadas de lo establecido en el delito continuado las ofensas a bienes eminentemente personales, salvo las constitutivas de infracciones contra:","o":["el honor y la libertad e indemnidad sexuales que afecten al mismo sujeto pasivo.","la vida y la integridad física que afecten al mismo sujeto pasivo.","el honor y la intimidad que afecten a distintos sujetos pasivos.","la libertad e indemnidad sexuales, aunque afecten a distintos sujetos pasivos, en los términos que se determinen reglamentariamente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el honor y la libertad e indemnidad sexuales que afecten al mismo sujeto pasivo</mark></span>El <span class=\"ref-norma\">art. 74.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"salvo las constitutivas de infracciones contra el honor y la libertad e indemnidad sexuales que afecten al mismo sujeto pasivo\"</span>. Honor y libertad e indemnidad sexuales que afecten al mismo sujeto pasivo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 58","q":[{"i":"18-45","p":"Código Penal. Disposiciones comunes de las penas, sus clases y sus efectos","o":["Sólo procederá el abono de prisión provisional sufrida en otra causa cuando dicha medida cautelar sea anterior a los hechos delictivos que motivan la pena a la que se pretende abonar","Sólo procederá el abono de prisión provisional sufrida en una causa cuando dicha medida cautelar sea posterior a los hechos delictivos que motivan la pena a la que se pretende abonar","Sólo procederá el abono de prisión provisional sufrida en otra causa cuando dicha medida cautelar sea posterior a los hechos delictivos que motivan la pena a la que se pretende abonar","Marcar como duda"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Sólo procederá el abono de prisión provisional sufrida en otra causa cuando dicha medida cautelar sea posterior a los hechos delictivos que…</mark></span>- Sólo se abona la prisión provisional sufrida en otra causa cuando es posterior a los hechos delictivos."},{"i":"18-ia-1255","p":"Código Penal. Disposiciones comunes. El tiempo de privación de libertad sufrido provisionalmente será abonado en su totalidad por el Juez o Tribunal sentenciador para el cumplimiento de la pena o penas impuestas en la causa en que dicha privación fue acordada. En ningún caso un mismo periodo de privación de libertad podrá ser abonado:","o":["en causa distinta de la que se decretó.","si ha coincidido con una privación de libertad impuesta en otra causa.","en más de una causa.","sin audiencia del Ministerio Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en más de una causa</mark></span>El <span class=\"ref-norma\">art. 58.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"En ningún caso un mismo periodo de privación de libertad podrá ser abonado en más de una causa\"</span>. Un mismo periodo no puede abonarse en más de una causa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1256","p":"Código Penal. Disposiciones comunes. El abono de prisión provisional en causa distinta de la que se decretó será acordado de oficio o a petición del penado y previa comprobación de que no ha sido abonada en otra causa, por:","o":["el Juez o Tribunal sentenciador de la causa en la que se pretende el abono, previa audiencia del penado, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente.","el Juez de Vigilancia Penitenciaria de la jurisdicción de la que dependa el centro penitenciario en que se encuentre el penado, previa audiencia del ministerio fiscal.","el Juez de Instrucción que acordó la prisión provisional, previo informe del Ministerio Fiscal.","la Audiencia Provincial a la que corresponda la ejecutoria, previa audiencia del Ministerio Fiscal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el Juez de Vigilancia Penitenciaria de la jurisdicción de la que dependa el centro penitenciario en que se encuentre el penado, previa audiencia del ministerio fiscal</mark></span>El <span class=\"ref-norma\">art. 58.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"será acordado de oficio o a petición del penado y previa comprobación de que no ha sido abonada en otra causa, por el Juez de Vigilancia Penitenciaria de la jurisdicción de la que dependa el centro penitenciario en que se encuentre el penado, previa audiencia del ministerio fiscal\"</span>. Corresponde al Juez de Vigilancia Penitenciaria del centro donde se encuentre el penado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1257","p":"Código Penal. Disposiciones comunes. Sólo procederá el abono de prisión provisional sufrida en otra causa cuando dicha medida cautelar sea:","o":["posterior a los hechos delictivos que motivaron la pena a la que se pretende abonar.","anterior a los hechos delictivos que motivaron la pena a la que se pretende abonar.","simultánea a los hechos delictivos que motivaron la pena a la que se pretende abonar.","posterior a la sentencia que impuso la pena a la que se pretende abonar."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">posterior a los hechos delictivos que motivaron la pena a la que se pretende abonar</mark></span>El <span class=\"ref-norma\">art. 58.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Sólo procederá el abono de prisión provisional sufrida en otra causa cuando dicha medida cautelar sea posterior a los hechos delictivos que motivaron la pena a la que se pretende abonar\"</span>. Posterior a los hechos delictivos que motivaron la pena. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"De las Medidas de Seguridad","q":[{"i":"18-46","p":"Código Penal. La libertad vigilada consistirá en el sometimiento del condenado a control judicial a través del cumplimiento por su parte de medidas como: Señale la CORRECTA","o":["La de comunicar inmediatamente, en el plazo máximo y por el medio que el Juez o Tribunal señale a tal efecto, cada cambio del lugar de residencia o del lugar o puesto de trabajo","La obligación de presentarse periódicamente en el lugar que el Juez o Tribunal establezca","La obligación de estar siempre localizable mediante aparatos electrónicos que permitan su seguimiento permanente","Todas son correctas"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>- Todas las medidas mencionadas son propias de la libertad vigilada."},{"i":"18-64","p":"Código Penal. Medidas de seguridad. Cuando se trate de una medida de seguridad privativa de libertad o de una medida de libertad vigilada que deba ejecutarse después del cumplimiento de una pena privativa de libertad, la propuesta de mantenimiento, cese, sustitución o suspensión de la misma, se elevará por:","o":["El Juez de Vigilancia Penitenciaria al menos anualmente","El Juez o Tribunal sentenciador al menos anualmente","El Juez de Primera Instancia al menos trimestralmente","El Juez instructor"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Juez de Vigilancia Penitenciaria al menos anualmente</mark></span>- Corresponde al Juez de Vigilancia Penitenciaria elevar la propuesta al menos anualmente."},{"i":"18-80","p":"Código Penal. De las medidas de seguridad. Cuando se trata de una medida de seguridad privativa de libertad o de una medida de libertad vigilada que deba ejecutarse después del cumplimiento de una pena privativa de libertad, ¿quién estará obligado a elevar al menos anualmente, una propuesta de mantenimiento, cese, sustitución o suspensión de la misma?:","o":["El Juez sentenciador","Juez de Vigilancia Penitenciaria","El Juez de Instrucción del lugar donde se cumpla la condena","La Audiencia Provincial del lugar donde se cumpla la condena"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Juez de Vigilancia Penitenciaria</mark></span>- Corresponde al Juez de Vigilancia Penitenciaria."},{"i":"18-95","p":"Código Penal. Disposiciones generales sobre los delitos, las personas responsables, las penas, medidas de seguridad y demás consecuencias de la infracción penal. Hay tentativa cuando:","o":["El sujeto da principio a la ejecución del delito directa o indirectamente por hechos exteriores, practicando todos o parte de los actos que objetivamente deberían producir el resultado y, sin embargo ésta no se produce por causas independientes de la voluntad del autor","El sujeto da principio a la ejecución del delito directamente por hechos exteriores, practicando todos o parte de los actos que objetivamente deberían producir el resultado y, sin embargo éste se produce por causas independientes de la voluntad del autor","El sujeto da principio a la ejecución del delito directamente por hechos exteriores, practicando todos o parte de los actos que objetivamente deberían producir el resultado y, sin embargo éste no se produce por causas independientes de la voluntad del autor","El sujeto da principio a la ejecución del delito directamente por hechos exteriores, practicando todos los actos que deberían producir el resultado y, sin embargo, éste se produce igualmente, sin que medien causas independientes de la voluntad del autor."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El sujeto da principio a la ejecución del delito directamente por hechos exteriores, practicando todos o parte de los actos que objetivamen…</mark></span>- La tentativa requiere el principio de ejecución y la no producción del resultado por causas ajenas a la voluntad del autor."},{"i":"18-120","p":"Código Penal. ¿Con qué frecuencia debe el Juez de Vigilancia Penitenciaria elevar una propuesta de mantenimiento, cese o sustitución respecto a la medida de seguridad privativa de libertad o de libertad vigilada?","o":["Mensualmente.","Trimestralmente.","Anualmente.","Cada cinco años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Anualmente.</mark></span>(El Juez de Vigilancia debe elevar la propuesta anualmente)."},{"i":"18-ia-1411","p":"Código Penal. Medidas privativas de libertad. Al sujeto que sea declarado exento de responsabilidad criminal por anomalía o alteración psíquica se le podrá aplicar, si fuere necesaria, la medida de internamiento para tratamiento médico o educación especial. El internamiento no podrá exceder:","o":["de la mitad del tiempo que habría durado la pena privativa de libertad, en los términos que se determinen reglamentariamente.","de cinco años en todo caso.","del tiempo que habría durado la pena privativa de libertad, si hubiera sido declarado responsable el sujeto.","del tiempo que fije el Juez de Vigilancia Penitenciaria."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">del tiempo que habría durado la pena privativa de libertad, si hubiera sido declarado responsable el sujeto</mark></span>El <span class=\"ref-norma\">art. 101.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"El internamiento no podrá exceder del tiempo que habría durado la pena privativa de libertad, si hubiera sido declarado responsable el sujeto, y a tal efecto el Juez o Tribunal fijará en la sentencia ese límite máximo\"</span>. No puede exceder del tiempo de la pena que habría correspondido; el límite se fija en la sentencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1412","p":"Código Penal. Medidas privativas de libertad. El sometido a la medida de internamiento por anomalía o alteración psíquica no podrá abandonar el establecimiento:","o":["sin autorización del director del centro.","sin autorización del Juez o Tribunal sentenciador.","sin informe favorable del Ministerio Fiscal.","sin comunicación al Juez de Vigilancia Penitenciaria."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">sin autorización del Juez o Tribunal sentenciador</mark></span>El <span class=\"ref-norma\">art. 101.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"El sometido a esta medida no podrá abandonar el establecimiento sin autorización del Juez o Tribunal sentenciador\"</span>. Autorización del Juez o Tribunal sentenciador. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1414","p":"Código Penal. Medidas privativas de libertad. A los declarados exentos de responsabilidad por alteraciones en la percepción desde el nacimiento o desde la infancia, se les podrá aplicar, si fuere necesaria, la medida de internamiento en:","o":["un centro de deshabituación, previo informe de la unidad policial competente.","un centro psiquiátrico.","un centro de menores.","un centro educativo especial."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">un centro educativo especial</mark></span>El <span class=\"ref-norma\">art. 103.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"la medida de internamiento en un centro educativo especial\"</span>. Centro educativo especial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1415","p":"Código Penal. Medidas privativas de libertad. En el supuesto de internamiento en centro educativo especial, la propuesta del Juez de Vigilancia Penitenciaria deberá hacerse:","o":["al menos anualmente en el mes de enero.","cada seis meses.","al terminar cada curso o grado de enseñanza.","al finalizar el primer trimestre de cada año."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">al terminar cada curso o grado de enseñanza</mark></span>El <span class=\"ref-norma\">art. 103.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"deberá hacerse al terminar cada curso o grado de enseñanza\"</span>. Al terminar cada curso o grado de enseñanza. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1416","p":"Código Penal. Medidas privativas de libertad. En los supuestos de eximente incompleta, la medida de internamiento sólo será aplicable cuando la pena impuesta sea privativa de libertad y su duración no podrá exceder:","o":["de la mitad de la pena impuesta.","de la de la pena prevista por el Código para el delito.","de la pena impuesta más un tercio, sin perjuicio de lo previsto en la normativa vigente.","de cinco años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">de la de la pena prevista por el Código para el delito</mark></span>El <span class=\"ref-norma\">art. 104.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"sólo será aplicable cuando la pena impuesta sea privativa de libertad y su duración no podrá exceder de la de la pena prevista por el Código para el delito\"</span>. Solo si la pena es privativa de libertad; no excede de la pena prevista para el delito. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1417","p":"Código Penal. Medidas privativas de libertad. Cuando se aplique una medida de internamiento, el juez o tribunal sentenciador comunicará al ministerio fiscal:","o":["con suficiente antelación, la proximidad de su vencimiento.","al inicio de la medida, su duración máxima.","mensualmente, la evolución del sujeto.","en el plazo de diez días, la fecha de ingreso, en los términos que se determinen reglamentariamente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">con suficiente antelación, la proximidad de su vencimiento</mark></span>El <span class=\"ref-norma\">art. 104.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el juez o tribunal sentenciador comunicará al ministerio fiscal, con suficiente antelación, la proximidad de su vencimiento\"</span>. Con suficiente antelación, la proximidad de su vencimiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1420","p":"Código Penal. Libertad vigilada. La libertad vigilada consistirá en el sometimiento del condenado a control judicial a través del cumplimiento por su parte de alguna o algunas de las siguientes medidas. Señale la INCORRECTA:","o":["La obligación de estar siempre localizable mediante aparatos electrónicos que permitan su seguimiento permanente.","La obligación de ingresar en un centro de deshabituación durante los fines de semana.","La obligación de presentarse periódicamente en el lugar que el Juez o Tribunal establezca.","La prohibición de ausentarse del lugar donde resida o de un determinado territorio sin autorización del Juez o Tribunal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La obligación de ingresar en un centro de deshabituación durante los fines de semana</mark></span>El <span class=\"ref-norma\">art. 106.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"a) La obligación de estar siempre localizable mediante aparatos electrónicos que permitan su seguimiento permanente. b) La obligación de presentarse periódicamente en el lugar que el Juez o Tribunal establezca\"</span>. No figura la obligación de ingresar en un centro de deshabituación en fines de semana. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 3","q":[{"i":"18-49","p":"Código Penal. Garantías Penales y de la aplicación de la Ley Penal: Señale la correcta","o":["No podrá ejecutarse pena ni medida de seguridad sino en virtud de sentencia firme dictada por el Juez o Tribunal competente, de acuerdo con las leyes procesales","No podrá ejecutarse pena ni medida de seguridad sino en virtud de sentencia firme dictada por el Juez o Tribunal competente, de acuerdo con las leyes penales y procesales","Tampoco podrá ejecutarse pena ni medida de seguridad en otra forma que la prescrita por la Ley y reglamentos que la desarrollan.","A y C son correctas"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A y C son correctas</mark></span>Según el <span class=\"ref-norma\">art. 3 del Código Penal</span>: <span class=\"ref-concepto\">\"Tampoco podrá ejecutarse pena ni medida de seguridad en otra forma que la prescrita por la Ley y reglamentos que la desarrollan, ni con otras circunstancias o accidentes que los expresados en su texto\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1007","p":"Código Penal. Ejecución de la pena. La ejecución de la pena o de la medida de seguridad se realizará bajo el control de:","o":["la Administración penitenciaria.","el Ministerio Fiscal.","los Jueces y Tribunales competentes.","el Gobierno, a través del Ministerio del Interior."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los Jueces y Tribunales competentes</mark></span>El <span class=\"ref-norma\">art. 3.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La ejecución de la pena o de la medida de seguridad se realizará bajo el control de los Jueces y Tribunales competentes\"</span>. El control corresponde a los Jueces y Tribunales competentes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 66 EXOF ✱","q":[{"i":"18-52","p":"Código Penal. En la aplicación de la pena, tratándose de delitos dolosos, los jueces o tribunales observarán, según haya o no circunstancias atenuantes o agravantes, las siguientes reglas: señale la INCORRECTA","o":["Cuando concurra sólo una circunstancia atenuante, aplicarán la pena en la mitad inferior de la que fija la ley para el delito","Cuando concurran dos o más circunstancias atenuantes, o una o varias muy cualificadas, y no concurra agravante alguna, aplicarán la pena inferior en uno o dos grados a la establecida por la ley, atendidos al número y la entidad de dichas circunstancias atenuantes","Cuando concurra sólo una o dos circunstancias agravantes, aplicarán la pena en la mitad superior de la que fija la ley para el delito","Cuando concurran más de dos circunstancias agravantes y concurra algún atenuante, podrán aplicar la pena superior en grado a la establecida por la ley, en su mitad inferior"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuando concurran más de dos circunstancias agravantes y concurra algún atenuante, podrán aplicar la pena superior en grado a la establecida…</mark></span>- Con más de dos agravantes y algún atenuante, se aplica la pena en la mitad superior, no superior en grado."},{"i":"18-93","p":"Código Penal. Aplicación de las penas. En la aplicación de la pena, tratándose de delitos dolosos, los jueces o tribunales observarán, según haya o no circunstancias atenuantes o agravantes, las siguientes reglas, entre otras: señale la INCORRECTA","o":["Cuando concurra sólo una circunstancia atenuante, aplicarán la pena en la mitad inferior de la que fije la ley para el delito","Cuando concurran dos o más circunstancias atenuantes, o una o varias muy cualificadas, y no concurra agravante alguna, aplicarán la pena inferior en uno o dos grados a la establecida por la ley, atendidos el número y la entidad de dicha circunstancia atenuante","Cuando concurra sólo una o dos circunstancias agravantes, aplicarán la pena en la mitad superior de la que fije la ley para el delito","Cuando concurran más de dos circunstancias agravantes y no concurra atenuante alguno, podrán aplicar la pena superior en grado a la establecida por la ley, en su mitad superior"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuando concurran más de dos circunstancias agravantes y no concurra atenuante alguno, podrán aplicar la pena superior en grado a la estable…</mark></span>- Con más de dos agravantes y ningún atenuante, se aplica la pena superior en grado en su mitad superior."},{"i":"18-267","p":"Código Penal. Reglas de aplicación de la pena. En los delitos dolosos, cuando concurra sólo una o dos circunstancias agravantes y ninguna atenuante, los jueces o tribunales aplicarán la pena:","o":["Superior en grado a la establecida por la ley, en su mitad inferior.","En la mitad superior de la que fije la ley para el delito.","En la mitad inferior de la que fije la ley para el delito.","Superior en grado a la establecida por la ley, en toda su extensión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En la mitad superior de la que fije la ley para el delito</mark></span>El <span class=\"ref-norma\">art. 66.1.3.ª de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"ª Cuando concurra sólo una o dos circunstancias agravantes, aplicarán la pena en la mitad superior de la que fije la ley para el delito\"</span>"},{"i":"18-268","p":"Código Penal. Reglas de aplicación de la pena. Cuando el culpable al delinquir hubiera sido condenado ejecutoriamente, al menos, por tres delitos comprendidos en el mismo título del Código, siempre que sean de la misma naturaleza, los jueces o tribunales podrán aplicar:","o":["La pena superior en grado a la prevista por la ley para el delito de que se trate, teniendo en cuenta las condenas precedentes, así como la gravedad del nuevo delito cometido.","La pena superior en dos grados a la prevista por la ley para el delito de que se trate, atendidas las condenas precedentes, conforme al procedimiento que reglamentariamente se establezca.","La pena en su mitad superior, sin que pueda exceder de la pena prevista para el delito.","La pena superior en grado, sin tener en cuenta la gravedad del nuevo delito cometido."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La pena superior en grado a la prevista por la ley para el delito de que se trate, teniendo en cuenta las condenas precedentes, así como la gravedad del nuevo delito cometido</mark></span>El <span class=\"ref-norma\">art. 66.1.5.ª de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"podrán aplicar la pena superior en grado a la prevista por la ley para el delito de que se trate, teniendo en cuenta las condenas precedentes, así como la gravedad del nuevo delito cometido\"</span>"},{"i":"18-ia-1268","p":"Código Penal. Aplicación de las penas en los delitos dolosos. Cuando concurra sólo una circunstancia atenuante, los jueces o tribunales aplicarán la pena:","o":["en su mitad superior.","en la mitad inferior de la que fije la ley para el delito.","inferior en un grado a la establecida por la ley, previo informe de la unidad policial competente.","en su grado mínimo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en la mitad inferior de la que fije la ley para el delito</mark></span>El <span class=\"ref-norma\">art. 66.1.1.ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Cuando concurra sólo una circunstancia atenuante, aplicarán la pena en la mitad inferior de la que fije la ley para el delito\"</span>. Mitad inferior. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1269","p":"Código Penal. Aplicación de las penas en los delitos dolosos. Cuando concurran dos o más circunstancias atenuantes, o una o varias muy cualificadas, y no concurra agravante alguna, los jueces o tribunales aplicarán:","o":["la pena inferior en uno o dos grados a la establecida por la ley, atendidos el número y la entidad de dichas circunstancias atenuantes.","la pena inferior en un solo grado a la establecida por la ley, atendida la entidad de dichas circunstancias atenuantes, sin perjuicio de lo previsto en la normativa vigente.","la pena en la mitad inferior de la establecida por la ley.","la pena inferior en dos grados a la establecida por la ley, en su mitad superior."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la pena inferior en uno o dos grados a la establecida por la ley, atendidos el número y la entidad de dichas circunstancias atenuantes</mark></span>El <span class=\"ref-norma\">art. 66.1.2.ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"a la establecida por la ley, atendidos el número y la entidad de dichas circunstancias atenuantes\"</span>. Inferior en uno o dos grados, atendidos el número y la entidad de las atenuantes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1270","p":"Código Penal. Aplicación de las penas en los delitos dolosos. Cuando concurra sólo una o dos circunstancias agravantes, los jueces o tribunales aplicarán la pena:","o":["superior en un grado a la que fije la ley para el delito.","en la mitad inferior de la que fije la ley para el delito, en los términos que se determinen reglamentariamente.","en su máxima extensión.","en la mitad superior de la que fije la ley para el delito."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">en la mitad superior de la que fije la ley para el delito</mark></span>El <span class=\"ref-norma\">art. 66.1.3.ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Cuando concurra sólo una o dos circunstancias agravantes, aplicarán la pena en la mitad superior de la que fije la ley para el delito\"</span>. Una o dos agravantes: mitad superior. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1271","p":"Código Penal. Aplicación de las penas en los delitos dolosos. Cuando concurran más de dos circunstancias agravantes y no concurra atenuante alguna, los jueces o tribunales podrán aplicar:","o":["la pena superior en grado a la establecida por la ley, en su mitad superior, salvo que la autoridad judicial disponga otra cosa.","la pena superior en uno o dos grados a la establecida por la ley.","la pena superior en grado a la establecida por la ley, en su mitad inferior.","la pena establecida por la ley, en su mitad superior."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la pena superior en grado a la establecida por la ley, en su mitad inferior</mark></span>El <span class=\"ref-norma\">art. 66.1.4.ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"podrán aplicar la pena superior en grado a la establecida por la ley, en su mitad inferior\"</span>. Superior en grado, en su mitad inferior. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1272","p":"Código Penal. Aplicación de las penas en los delitos dolosos. Cuando concurra la agravante de reincidencia con la cualificación de que el culpable al delinquir hubiera sido condenado ejecutoriamente, al menos, por __________ delitos comprendidos en el mismo título de este Código, siempre que sean de la misma naturaleza, podrán aplicar la pena superior en grado:","o":["dos","tres","cuatro","cinco"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">tres</mark></span>El <span class=\"ref-norma\">art. 66.1.5.ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"hubiera sido condenado ejecutoriamente, al menos, por tres delitos comprendidos en el mismo título de este Código, siempre que sean de la misma naturaleza, podrán aplicar la pena superior en grado a la prevista por la ley para el delito de que se trate\"</span>. Al menos tres delitos del mismo título y de la misma naturaleza. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1273","p":"Código Penal. Aplicación de las penas en los delitos dolosos. A los efectos de la regla sobre reincidencia cualificada:","o":["no se computarán los antecedentes penales cancelados o que debieran serlo.","se computarán los antecedentes penales cancelados, pero no los prescritos, previo informe de la unidad policial competente.","solo se computarán los antecedentes penales de los últimos diez años.","se computarán todos los antecedentes penales, incluidos los cancelados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no se computarán los antecedentes penales cancelados o que debieran serlo</mark></span>El <span class=\"ref-norma\">art. 66.1.5.ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"A los efectos de esta regla no se computarán los antecedentes penales cancelados o que debieran serlo\"</span>. No se computan los cancelados o que debieran serlo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1274","p":"Código Penal. Aplicación de las penas en los delitos dolosos. Cuando no concurran atenuantes ni agravantes, los jueces o tribunales aplicarán la pena establecida por la ley para el delito cometido, en la extensión que estimen adecuada, en atención:","o":["al peligro inherente al hecho y al daño causado a la víctima.","a la gravedad del hecho exclusivamente, con independencia de las circunstancias del delincuente.","a la situación económica del reo y a la entidad del perjuicio ocasionado.","a las circunstancias personales del delincuente y a la mayor o menor gravedad del hecho."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a las circunstancias personales del delincuente y a la mayor o menor gravedad del hecho</mark></span>El <span class=\"ref-norma\">art. 66.1.6.ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"en la extensión que estimen adecuada, en atención a las circunstancias personales del delincuente y a la mayor o menor gravedad del hecho\"</span>. Circunstancias personales del delincuente y gravedad del hecho. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1275","p":"Código Penal. Aplicación de las penas en los delitos dolosos. Cuando concurran atenuantes y agravantes, los jueces o tribunales las valorarán y compensarán racionalmente para la individualización de la pena. En el caso de persistir un fundamento cualificado de atenuación aplicarán:","o":["la pena en su mitad inferior.","la pena inferior en uno o dos grados.","la pena inferior en grado.","la pena en su grado mínimo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la pena inferior en grado</mark></span>El <span class=\"ref-norma\">art. 66.1.7.ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"En el caso de persistir un fundamento cualificado de atenuación aplicarán la pena inferior en grado. Si se mantiene un fundamento cualificado de agravación, aplicarán la pena en su mitad superior\"</span>. Atenuación cualificada: pena inferior en grado; agravación cualificada: mitad superior. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1276","p":"Código Penal. Aplicación de las penas en los delitos dolosos. Cuando los jueces o tribunales apliquen la pena inferior en más de un grado podrán hacerlo:","o":["en su mitad superior.","en toda su extensión.","en su mitad inferior.","únicamente en su grado máximo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en toda su extensión</mark></span>El <span class=\"ref-norma\">art. 66.1.8.ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Cuando los jueces o tribunales apliquen la pena inferior en más de un grado podrán hacerlo en toda su extensión\"</span>. En toda su extensión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1277","p":"Código Penal. Aplicación de las penas en los delitos dolosos. En los delitos leves y en los delitos imprudentes, los jueces o tribunales aplicarán las reglas:","o":["a su prudente arbitrio, sin sujetarse a las reglas prescritas en el apartado anterior, salvo lo dispuesto para los tipos agravados por multirreincidencia de delitos leves.","del apartado anterior, reduciendo en un grado la pena resultante.","del apartado anterior, salvo la relativa a la reincidencia cualificada, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente.","a su prudente arbitrio, sin excepción alguna."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a su prudente arbitrio, sin sujetarse a las reglas prescritas en el apartado anterior, salvo lo dispuesto para los tipos agravados por multirreincidencia de delitos leves</mark></span>El <span class=\"ref-norma\">art. 66.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"los jueces o tribunales aplicarán las reglas a su prudente arbitrio, sin sujetarse a las reglas prescritas en el apartado anterior, salvo lo dispuesto para los tipos agravados por multirreincidencia de delitos leves\"</span>. Prudente arbitrio, salvo la multirreincidencia de delitos leves. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 106 ✱","q":[{"i":"18-57","p":"Código Penal. De las medidas no privativas de libertad. La libertad vigilada consistirá en el sometimiento del condenado a control judicial a través del cumplimiento por su parte de alguna o algunas de las siguientes medidas","o":["La obligación de estar siempre localizable mediante aparatos electrónicos que permitan su seguimiento permanente","La ejecución anterior del lugar de trabajo que el autor establezca","La de comunicar inmediatamente, en el plazo máximo de 24 horas y por el medio que el Juez o Tribunal señale a tal efecto, cada cambio del lugar de residencia o del lugar o puesto de trabajo","La obligación de seguir tratamiento médico externo o interno, o de someterse a un control médico periódico"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La obligación de estar siempre localizable mediante aparatos electrónicos que permitan su seguimiento permanente</mark></span>- La localización mediante aparatos electrónicos es una medida específica de la libertad vigilada."},{"i":"18-280","p":"Código Penal. Libertad vigilada. La libertad vigilada consistirá en el sometimiento del condenado a control judicial a través del cumplimiento de alguna o algunas medidas, entre ellas:","o":["La prohibición de aproximarse a la víctima, o a aquellos de sus familiares u otras personas que determine el Juez o Tribunal.","La obligación de ingresar en un centro de deshabituación durante los fines de semana, en los términos que determine la ley orgánica correspondiente.","La prohibición de contraer matrimonio con personas de la familia de la víctima.","La obligación de ejercer una actividad laboral determinada por el Juez."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La prohibición de aproximarse a la víctima, o a aquellos de sus familiares u otras personas que determine el Juez o Tribunal</mark></span>El <span class=\"ref-norma\">art. 106.1.e) de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"La prohibición de aproximarse a la víctima, o a aquellos de sus familiares u otras personas que determine el Juez o Tribunal\"</span>"},{"i":"18-281","p":"Código Penal. Libertad vigilada. Entre las medidas de la libertad vigilada figura:","o":["La obligación de comunicar semanalmente a la víctima cada cambio de domicilio.","La prohibición de comunicarse con cualquier persona que no pertenezca a su núcleo familiar, salvo que el órgano competente acuerde otra cosa de forma motivada.","La obligación de someter a control judicial todas sus comunicaciones.","La prohibición de comunicarse con la víctima, o con aquellos de sus familiares u otras personas que determine el Juez o Tribunal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La prohibición de comunicarse con la víctima, o con aquellos de sus familiares u otras personas que determine el Juez o Tribunal</mark></span>El <span class=\"ref-norma\">art. 106.1.f) de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"La prohibición de comunicarse con la víctima, o con aquellos de sus familiares u otras personas que determine el Juez o Tribunal\"</span>"},{"i":"18-ia-1421","p":"Código Penal. Libertad vigilada. Entre las medidas de la libertad vigilada figura la de comunicar inmediatamente, en el plazo máximo y por el medio que el Juez o Tribunal señale a tal efecto:","o":["cada cambio del lugar de residencia o del lugar o puesto de trabajo.","cada salida del territorio nacional.","cada cambio de teléfono o dirección de correo electrónico, previo informe de la unidad policial competente.","cada contacto con la víctima o sus familiares."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cada cambio del lugar de residencia o del lugar o puesto de trabajo</mark></span>El <span class=\"ref-norma\">art. 106.1.c del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La de comunicar inmediatamente, en el plazo máximo y por el medio que el Juez o Tribunal señale a tal efecto, cada cambio del lugar de residencia o del lugar o puesto de trabajo\"</span>. Cambio de residencia o del lugar o puesto de trabajo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1422","p":"Código Penal. Libertad vigilada. Entre las medidas de la libertad vigilada figura la obligación de seguir:","o":["tratamiento psiquiátrico en régimen de internamiento parcial, sin perjuicio de lo previsto en la normativa vigente.","tratamiento psicológico obligatorio con informe mensual.","tratamiento de deshabituación durante un mínimo de un año.","tratamiento médico externo, o de someterse a un control médico periódico."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tratamiento médico externo, o de someterse a un control médico periódico</mark></span>El <span class=\"ref-norma\">art. 106.1.k del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La obligación de seguir tratamiento médico externo, o de someterse a un control médico periódico\"</span>. Tratamiento médico externo o control médico periódico. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1423","p":"Código Penal. Libertad vigilada. En los casos en que el Juez o Tribunal deba imponer la libertad vigilada para su cumplimiento posterior a la pena privativa de libertad, al menos dos meses antes de la extinción de la pena privativa de libertad, el Juez de Vigilancia Penitenciaria:","o":["dictará el auto fijando las obligaciones y prohibiciones.","informará al Ministerio Fiscal para que formule petición.","elevará la oportuna propuesta al Juez o Tribunal sentenciador.","comunicará al penado las obligaciones que habrá de observar, en los términos que se determinen reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">elevará la oportuna propuesta al Juez o Tribunal sentenciador</mark></span>El <span class=\"ref-norma\">art. 106.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"al menos dos meses antes de la extinción de la pena privativa de libertad, de modo que la medida de libertad vigilada pueda iniciarse en ese mismo momento, el Juez de Vigilancia Penitenciaria, por el procedimiento previsto en el artículo 98, elevará la oportuna propuesta al Juez o Tribunal sentenciador\"</span>. Al menos dos meses antes, el JVP eleva propuesta al sentenciador. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1424","p":"Código Penal. Libertad vigilada. Por el mismo procedimiento, el Juez o Tribunal podrá, respecto de la libertad vigilada, entre otras facultades:","o":["ampliar su duración hasta un máximo de diez años en caso de pronóstico negativo, salvo que la autoridad judicial disponga otra cosa.","reducir la duración de la libertad vigilada o incluso poner fin a la misma en vista del pronóstico positivo de reinserción.","sustituirla por la pena de localización permanente.","suspender su ejecución durante el tiempo que dure la pena de prisión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">reducir la duración de la libertad vigilada o incluso poner fin a la misma en vista del pronóstico positivo de reinserción</mark></span>El <span class=\"ref-norma\">art. 106.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"b) Reducir la duración de la libertad vigilada o incluso poner fin a la misma en vista del pronóstico positivo de reinserción\"</span>. Modificar obligaciones, reducir la duración o ponerle fin con pronóstico positivo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1425","p":"Código Penal. Libertad vigilada. Si el incumplimiento de las obligaciones de la libertad vigilada fuera reiterado o grave, revelador de la voluntad de no someterse a las obligaciones o prohibiciones impuestas, el Juez:","o":["deducirá, además, testimonio por un presunto delito de quebrantamiento de condena.","revocará la medida y ordenará el ingreso en prisión, previo informe de la unidad policial competente.","impondrá una multa de seis a doce meses.","sustituirá la medida por la de internamiento."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">deducirá, además, testimonio por un presunto delito de quebrantamiento de condena</mark></span>El <span class=\"ref-norma\">art. 106.4 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el Juez deducirá, además, testimonio por un presunto delito del artículo 468 de este Código\"</span>. Deduce testimonio por un presunto delito de quebrantamiento (art. 468). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"RECUERDA del temario · Código Penal (R1 a R10) R1 R2 R3 R4 R5 R6 R7 R8 R9 R10","q":[{"i":"18-60","p":"Código Penal. De los delitos. Cuando el que ha resuelto cometer un delito invita a otra u otras personas a participar en él, es una","o":["Complicidad","Proposición","Provocación","Todas son correctas"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Proposición</mark></span>- Se denomina proposición cuando alguien invita a otros a participar en un delito que ha resuelto cometer."},{"i":"18-61","p":"Código Penal. El error sobre un hecho constitutivo de la infracción penal","o":["Será castigada, en su caso, como imprudente","Excluye la responsabilidad criminal","Será castigada, en su caso, como dolosa","Impedirá su apreciación"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Excluye la responsabilidad criminal</mark></span>- El error sobre un elemento constitutivo del tipo penal excluye la responsabilidad criminal."},{"i":"18-69","p":"Código Penal. De los delitos. ¿Cuándo se castigan las acciones imprudentes?:","o":["Sólo se castigarán cuando sean delitos dolosos","Sólo se castigarán cuando expresamente lo disponga la Ley","Sólo se castigarán cuando la imprudencia sea considerada grave","Ninguna es correcta"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Sólo se castigarán cuando expresamente lo disponga la Ley</mark></span>- Las acciones imprudentes sólo se castigan cuando expresamente lo disponga la Ley."},{"i":"18-88","p":"Código Penal. Infracción Penal. En relación al error:","o":["El error invencible sobre un hecho constitutivo de la infracción penal excluye la responsabilidad criminal","Si el error fuera vencible sobre un hecho constitutivo de la infracción penal, atendidas las circunstancias del hecho y las personales del autor, la infracción será castigada, en su caso, como imprudente","El error sobre un hecho que cualifique la infracción o sobre una circunstancia agravante, impedirá su apreciación","El error invencible sobre la ilicitud del hecho constitutivo de la infracción penal excluye la responsabilidad criminal"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El error invencible sobre un hecho constitutivo de la infracción penal excluye la responsabilidad criminal</mark></span>- El error invencible sobre un elemento del tipo excluye la responsabilidad criminal."},{"i":"18-92","p":"Código Penal. De la infracción penal. La provocación se castigará exclusivamente en los casos en que la Ley así lo prevea. Si a la provocación hubiese seguido la perpetración del delito, se castigará como:","o":["Proposición","Apología.","Conjugación","Ninguna es correcta"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Ninguna es correcta</mark></span>- La provocación seguida de perpetración se castiga como inducción."},{"i":"18-112","p":"Ley Orgánica 10/1995, de 23 de noviembre, del Código Penal. Existe cuando el que ha resuelto cometer un delito invita a otra u otras personas a participar en él:","o":["La comparación.","La proposición.","La conspiración.","La apología."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La proposición.</mark></span>(La proposición delictiva consiste en invitar a otros a participar en un delito)."},{"i":"18-114","p":"Código Penal. En el caso de error invencible sobre la ilicitud del hecho constitutivo de la infracción penal, ¿cuál es la consecuencia?","o":["Excluye la responsabilidad criminal.","Se considera una circunstancia atenuante.","Se aplica la pena superior en uno o dos grados.","Se aplica la pena correspondiente al delito imprudente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Excluye la responsabilidad criminal.</mark></span>(El error invencible sobre la ilicitud excluye la responsabilidad criminal según el principio de culpabilidad)."},{"i":"18-115","p":"Código Penal. De las garantías penales y de la aplicación de la ley penal. Señale la INCORRECTA.","o":["No será castigada ninguna acción ni omisión que no esté prevista como delito por ley anterior a su perpetración.","Las medidas de seguridad sólo podrán aplicarse cuando concurran los presupuestos establecidos previamente por la Ley.","Tendrán efecto retroactivo aquellas leyes penales que favorezcan al reo, siempre que al entrar en vigor no hubiera recaído sentencia firme y el sujeto no estuviese cumpliendo condena.","No será castigado ningún delito con pena que no se halle prevista por ley anterior a su perpetración."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Tendrán efecto retroactivo aquellas leyes penales que favorezcan al reo, siempre que al entrar en vigor no hubiera recaído sentencia firme …</mark></span>(Las leyes penales favorables tienen efecto retroactivo incluso cuando hay sentencia firme y el condenado está cumpliendo condena)."},{"i":"18-125","p":"Código Penal. Si una persona comete un error sobre un hecho que cualifica la infracción o sobre una circunstancia agravante, ¿qué consecuencia tiene?","o":["La infracción se considera como cometida con dolo.","Se aplica la pena correspondiente al delito básico.","Impedirá su apreciación.","Se considera como una atenuante en la responsabilidad criminal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Impedirá su apreciación.</mark></span>(El error sobre una circunstancia agravante impide su apreciación)."},{"i":"18-127","p":"Código Penal. De los delitos. Señale la CORRECTA.","o":["El error invencible sobre un hecho constitutivo de la infracción penal excluye la responsabilidad criminal.","El error sobre un hecho que cualifique la infracción o sobre una circunstancia agravante, impide su apreciación.","El error invencible sobre la ilicitud del hecho constitutivo de la infracción penal excluye la responsabilidad criminal.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span>(Todas las afirmaciones sobre el error son correctas según la legislación penal)."},{"i":"18-141","p":"Código Penal. ¿En qué casos se castigan la conspiración y la proposición para delinquir?","o":["En todos los casos de delitos menores y mayores.","Sólo cuando el delito ha sido consumado.","Únicamente en los casos que la ley no genera.","Sólo en los casos especialmente previstos en la ley."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Sólo en los casos especialmente previstos en la ley.</mark></span>(Solo se castigan cuando la ley los prevé expresamente para determinados delitos)."},{"i":"18-151","p":"Código Penal. De los delitos. ¿Cuál de las siguientes afirmaciones define correctamente la conspiración?:","o":["La conspiración se da cuando una persona planea un delito en solitario.","La conspiración existe cuando dos o más personas se conciertan para la ejecución de un delito y resuelven ejecutarlo.","La conspiración ocurre cuando una persona comete un delito sin ayuda.","La conspiración se castiga en todos los casos sin excepción."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La conspiración existe cuando dos o más personas se conciertan para la ejecución de un delito y resuelven ejecutarlo.</mark></span>(La conspiración requiere el concierto de dos o más personas para ejecutar un delito)."},{"i":"18-154","p":"Código Penal. De los delitos. ¿Qué efecto tiene el error invencible sobre un hecho constitutivo de la infracción penal?:","o":["No tiene ningún efecto sobre la responsabilidad criminal.","Excluye la responsabilidad criminal.","La infracción se castiga como delito doloso.","La infracción se castiga con la pena máxima posible."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Excluye la responsabilidad criminal.</mark></span>(El error invencible sobre un hecho constitutivo excluye la responsabilidad criminal)."},{"i":"18-168","p":"Código penal. De los delitos. Señale la CORRECTA:","o":["La conspiración existe cuando el que ha resuelto cometer un delito invita a otra u otras personas a participar en él.","La proposición existe cuando dos o más personas se conciertan para la ejecución de un delito y resuelven ejecutarlo.","La conspiración y la proposición para delinquir sólo se castigarán en los casos especialmente previstos en la ley.","La conspiración y la proposición para delinquir se castigarán en todos los casos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La conspiración y la proposición para delinquir sólo se castigarán en los casos especialmente previstos en la ley</mark></span>Conspiración: concierto de dos o más personas; proposición: invitación del que ya ha resuelto delinquir. Según el <span class=\"ref-norma\">art. 17 del Código Penal</span>: <span class=\"ref-concepto\">\"La conspiración y la proposición para delinquir sólo se castigarán en los casos especialmente previstos en la Ley\"</span> (verificado con el texto del temario oficial)."},{"i":"18-171","p":"Código penal. De los delitos. Si el error sobre la ilicitud del hecho fuera vencible:","o":["Se aplicará la pena menos grave.","Se aplicará la pena inferior en uno o dos grados.","Se excluye la responsabilidad criminal.","Se siguen las mismas consecuencias que si el error fuera invencible."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Se aplicará la pena inferior en uno o dos grados.</mark></span>(El error vencible sobre la ilicitud permite aplicar la pena inferior en uno o dos grados)."},{"i":"18-247","p":"Código Penal. Tiempo del delito. A los efectos de determinar la ley penal aplicable en el tiempo, los delitos se consideran cometidos:","o":["En el momento en que se produce el resultado de la acción u omisión.","En el momento en que el sujeto ejecuta la acción u omite el acto que estaba obligado a realizar.","En el momento en que los hechos llegan a conocimiento de la autoridad judicial, sin perjuicio de lo que establezcan los tratados internacionales.","En el momento en que se incoa el procedimiento penal contra el sujeto."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En el momento en que el sujeto ejecuta la acción u omite el acto que estaba obligado a realizar</mark></span>El <span class=\"ref-norma\">art. 7 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"A los efectos de determinar la ley penal aplicable en el tiempo, los delitos se consideran cometidos en el momento en que el sujeto ejecuta la acción u omite el acto que estaba obligado a realizar\"</span>"},{"i":"18-ia-1003","p":"Código Penal. Irretroactividad. Señale la INCORRECTA sobre la irretroactividad de la ley penal:","o":["No será castigado ningún delito con pena que no se halle prevista por ley anterior a su perpetración.","Carecerán de efecto retroactivo las leyes que establezcan medidas de seguridad.","Las leyes que establezcan medidas de seguridad tendrán efecto retroactivo siempre que favorezcan al sujeto peligroso.","Tendrán efecto retroactivo las leyes penales que favorezcan al reo, aunque hubiera recaído sentencia firme, en los términos que se determinen reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las leyes que establezcan medidas de seguridad tendrán efecto retroactivo siempre que favorezcan al sujeto peligroso</mark></span>El <span class=\"ref-norma\">art. 2.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Carecerán, igualmente, de efecto retroactivo las leyes que establezcan medidas de seguridad\"</span>. Las leyes que establezcan medidas de seguridad carecen de efecto retroactivo; la retroactividad favorable se refiere a las leyes penales que favorezcan al reo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1015","p":"Código Penal. Ley penal en el tiempo. A los efectos de determinar la ley penal aplicable en el tiempo, los delitos se consideran cometidos en el momento en que:","o":["se produce el resultado del delito.","se denuncia el hecho ante la autoridad competente.","el sujeto ejecuta la acción u omite el acto que estaba obligado a realizar.","el sujeto ejecuta la acción o se produce el resultado, a elección del Tribunal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el sujeto ejecuta la acción u omite el acto que estaba obligado a realizar</mark></span>El <span class=\"ref-norma\">art. 7 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"los delitos se consideran cometidos en el momento en que el sujeto ejecuta la acción u omite el acto que estaba obligado a realizar\"</span>. Se atiende al momento de la acción u omisión, no al resultado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1023","p":"Código Penal. Imprudencia. Las acciones u omisiones imprudentes sólo se castigarán cuando:","o":["así lo aprecie el Juez o Tribunal.","causen un resultado de muerte o lesiones.","expresamente lo disponga la Ley.","se hayan infringido deberes reglamentarios."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">expresamente lo disponga la Ley</mark></span>El <span class=\"ref-norma\">art. 12 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Las acciones u omisiones imprudentes sólo se castigarán cuando expresamente lo disponga la Ley\"</span>. Sistema de numerus clausus de la imprudencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1026","p":"Código Penal. Error. El error invencible sobre un hecho constitutivo de la infracción penal excluye la responsabilidad criminal. Si el error, atendidas las circunstancias del hecho y las personales del autor, fuera vencible:","o":["la infracción será castigada, en su caso, como dolosa con la pena inferior en un grado.","se aplicará la pena inferior en uno o dos grados.","quedará excluida igualmente la responsabilidad criminal.","la infracción será castigada, en su caso, como imprudente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la infracción será castigada, en su caso, como imprudente</mark></span>El <span class=\"ref-norma\">art. 14.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Si el error, atendidas las circunstancias del hecho y las personales del autor, fuera vencible, la infracción será castigada, en su caso, como imprudente\"</span>. El error vencible sobre el hecho se castiga como imprudente; la pena inferior en uno o dos grados es para el error de prohibición vencible. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1027","p":"Código Penal. Error. El error sobre un hecho que cualifique la infracción o sobre una circunstancia agravante:","o":["excluirá la responsabilidad criminal.","se castigará como imprudente.","impedirá su apreciación.","atenuará la pena en un grado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">impedirá su apreciación</mark></span>El <span class=\"ref-norma\">art. 14.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"El error sobre un hecho que cualifique la infracción o sobre una circunstancia agravante, impedirá su apreciación\"</span>. El error impide apreciar el tipo cualificado o la agravante. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1028","p":"Código Penal. Error. El error invencible sobre la ilicitud del hecho constitutivo de la infracción penal excluye la responsabilidad criminal. Si el error fuera vencible:","o":["se aplicará la pena inferior en un grado.","se aplicará la pena inferior en uno o dos grados.","la infracción será castigada, en su caso, como imprudente.","se aplicará la pena en su mitad inferior."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">se aplicará la pena inferior en uno o dos grados</mark></span>El <span class=\"ref-norma\">art. 14.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Si el error fuera vencible, se aplicará la pena inferior en uno o dos grados\"</span>. El error de prohibición vencible rebaja la pena en uno o dos grados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 4 ✱","q":[{"i":"18-65","p":"Código Penal. Las leyes penales:","o":["Podrán aplicarse de forma analógica a otros supuestos de hecho","No podrán aplicarse de forma analógica cuando favorezcan al reo","No se aplicarán a casos distintos de los comprendidos expresamente en ellas","Todas son incorrectas"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">No se aplicarán a casos distintos de los comprendidos expresamente en ellas</mark></span>- Las leyes penales no pueden aplicarse por analogía, sólo a los casos expresamente previstos."},{"i":"18-97","p":"Código Penal. De las garantías penales y de la aplicación de la ley penal. Señala la CORRECTA:","o":["En el caso de que un Juez o Tribunal, en el ejercicio de su jurisdicción, tenga conocimiento de alguna acción u omisión que, sin estar penada por la Ley, estime digna de represión, se abstendrá de todo procedimiento sobre ella y expondrá al Gobierno las razones que le asistan para creer que debiera ser objeto de sanción penal.","Las leyes penales no se aplicarán a casos distintos de los comprendidos expresamente en ellas.","Si mediara petición de indulto, y el Juez o Tribunal hubiere apreciado en resolución fundada que por el cumplimiento de la pena puede resultar vulnerado el derecho a un proceso sin dilaciones indebidas, suspenderá la ejecución de la misma en tanto no se resuelva sobre la petición formulada.","Todas son correctas"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 4 del Código Penal</span>: <span class=\"ref-concepto\">\"Las leyes penales no se aplicarán a casos distintos de los comprendidos expresamente en ellas\"</span> (verificado con el texto del temario oficial)."},{"i":"18-187","p":"Código Penal. De las garantías penales y de la aplicación de la Ley penal. Señale la INCORRECTA:","o":["Las leyes penales se podrán aplicar a casos distintos de los comprendidos expresamente en ellas.","En el caso de que un Juez o Tribunal, en el ejercicio de su jurisdicción, tenga conocimiento de alguna acción u omisión que, sin estar penada por la Ley, estime digna de represión, se abstendrá de todo procedimiento sobre ella y expondrá al Gobierno las razones que le asistan para creer que debiera ser objeto de sanción penal.","Acudirá al Gobierno exponiendo lo conveniente sobre la derogación o modificación del precepto o la concesión de indulto, sin perjuicio de ejecutar desde luego la sentencia, cuando de la rigurosa aplicación de las disposiciones de la Ley resulte penada una acción u omisión que, a juicio del Juez o Tribunal, no debiera serlo, o cuando la pena sea notablemente excesiva, atendidos el mal causado por la infracción y las circunstancias personales del reo.","Si mediara petición de indulto, y el Juez o Tribunal hubiere apreciado en resolución fundada que por el cumplimiento de la pena puede resultar vulnerado el derecho a un proceso sin dilaciones indebidas, suspenderá la ejecución de la misma en tanto no se resuelva sobre la petición formulada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las leyes penales se podrán aplicar a casos distintos de los comprendidos expresamente en ellas</mark></span>Según el <span class=\"ref-norma\">art. 4 del Código Penal</span>: <span class=\"ref-concepto\">\"Las leyes penales no se aplicarán a casos distintos de los comprendidos expresamente en ellas\"</span> (verificado con el texto del temario oficial)."},{"i":"18-205","p":"Código Penal. De las garantías penales y de la aplicación de la Ley penal. Señale la INCORRECTA:","o":["Las leyes penales se podrán aplicar a casos distintos de los comprendidos expresamente en ellas.","En el caso de que un Juez o Tribunal, en el ejercicio de su jurisdicción, tenga conocimiento de alguna acción u omisión que, sin estar penada por la Ley, estime digna de represión, se abstendrá de todo procedimiento sobre ella y expondrá al Gobierno las razones que le asistan para creer que debiera ser objeto de sanción penal.","Acudirá al Gobierno exponiendo lo conveniente sobre la derogación o modificación del precepto o la concesión de indulto, sin perjuicio de ejecutar desde luego la sentencia, cuando de la rigurosa aplicación de las disposiciones de la Ley resulte penada una acción u omisión que, a juicio del Juez o Tribunal, no debiera serlo, o cuando la pena sea notablemente excesiva, atendidos el mal causado por la infracción y las circunstancias personales del reo.","Si mediara petición de indulto, y el Juez o Tribunal hubiere apreciado en resolución fundada que por el cumplimiento de la pena puede resultar vulnerado el derecho a un proceso sin dilaciones indebidas, suspenderá la ejecución de la misma en tanto no se resuelva sobre la petición formulada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las leyes penales se podrán aplicar a casos distintos de los comprendidos expresamente en ellas</mark></span>Según el <span class=\"ref-norma\">art. 4 del Código Penal</span>: <span class=\"ref-concepto\">\"Las leyes penales no se aplicarán a casos distintos de los comprendidos expresamente en ellas\"</span> (verificado con el texto del temario oficial)."},{"i":"18-207","p":"Código Penal. ¿Cuándo acudirá al Gobierno exponiendo lo conveniente sobre la derogación o modificación del precepto o la concesión de indulto, sin perjuicio de ejecutar desde luego la sentencia?","o":["Cuando de la rigurosa aplicación de las disposiciones de la Ley resulte penada una acción u omisión que, a juicio del Juez o Tribunal, no debiera serlo.","Si mediare petición de indulto.","Cuando la pena sea notablemente excesiva, atendidos el mal causado por la infracción y las circunstancias personales del reo.","A Y C son respuestas correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A Y C son respuestas correctas</mark></span>Es el apartado 3 del artículo 4 (no el 4.2). Según el <span class=\"ref-norma\">art. 4 del Código Penal</span>: <span class=\"ref-concepto\">\"cuando de la rigurosa aplicación de las disposiciones de la Ley resulte penada una acción u omisión que, a juicio del Juez o Tribunal, no debiera serlo, o cuando la pena sea notablemente excesiva, atendidos el mal causado por la infracción y las circunstancias personales del reo\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1008","p":"Código Penal. Principio de legalidad. Las leyes penales no se aplicarán a casos distintos de:","o":["los previstos en la Constitución.","los comprendidos expresamente en ellas.","los comprendidos en ellas, salvo analogía favorable.","los comprendidos en ellas o en normas análogas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los comprendidos expresamente en ellas</mark></span>El <span class=\"ref-norma\">art. 4.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Las leyes penales no se aplicarán a casos distintos de los comprendidos expresamente en ellas\"</span>. Se prohíbe la aplicación a casos no comprendidos expresamente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1009","p":"Código Penal. Principio de legalidad. Si un Juez o Tribunal tiene conocimiento de una acción u omisión que, sin estar penada por la Ley, estime digna de represión, deberá:","o":["abstenerse de todo procedimiento sobre ella y exponer al Gobierno las razones que le asistan.","incoar diligencias y elevar exposición razonada al Consejo General del Poder Judicial.","abstenerse de todo procedimiento y comunicarlo al Ministerio Fiscal para que ejercite la acción.","continuar el procedimiento y exponer al Gobierno las razones que le asistan."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">abstenerse de todo procedimiento sobre ella y exponer al Gobierno las razones que le asistan</mark></span>El <span class=\"ref-norma\">art. 4.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"se abstendrá de todo procedimiento sobre ella y expondrá al Gobierno las razones que le asistan para creer que debiera ser objeto de sanción penal\"</span>. El Juez se abstiene y expone al Gobierno las razones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1010","p":"Código Penal. Principio de legalidad. Cuando de la rigurosa aplicación de la Ley resulte penada una acción que, a juicio del Juez o Tribunal, no debiera serlo, o cuando la pena sea notablemente excesiva, el Juez acudirá al Gobierno, sin perjuicio de:","o":["suspender desde luego la ejecución de la sentencia.","revisar de oficio la sentencia dictada.","dejar sin efecto la condena impuesta.","ejecutar desde luego la sentencia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">ejecutar desde luego la sentencia</mark></span>El <span class=\"ref-norma\">art. 4.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"sin perjuicio de ejecutar desde luego la sentencia\"</span>. La sentencia se ejecuta desde luego; el Juez solo expone lo conveniente al Gobierno. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1011","p":"Código Penal. Principio de legalidad. Si mediara petición de indulto, y el Juez o Tribunal hubiere apreciado en resolución fundada que por el cumplimiento de la pena puede resultar vulnerado el derecho a un proceso sin dilaciones indebidas, suspenderá la ejecución de la misma:","o":["por un plazo máximo de seis meses.","hasta que el Consejo de Ministros acuerde el indulto.","en tanto no se resuelva sobre la petición formulada.","durante un año como máximo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en tanto no se resuelva sobre la petición formulada</mark></span>El <span class=\"ref-norma\">art. 4.4 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"suspenderá la ejecución de la misma en tanto no se resuelva sobre la petición formulada\"</span>. La suspensión dura mientras no se resuelva sobre el indulto, sin plazo fijo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 100","q":[{"i":"18-66","p":"Código Penal. El quebrantamiento de una medida de seguridad de internamiento dará lugar a:","o":["La proporción entre el valor de los bienes y efectos de que se trate y los ingresos legales de la persona condenada","Que el juez o tribunal ordene el ingreso del sujeto en el mismo centro del que se hubiese evadido","La sustitución de la medida quebrantada por otra si ésta estuviese prevista para el supuesto de que se trate y el quebrantamiento demostrase su necesidad","El ingreso del sujeto en otro centro de internamiento de la misma o distinta naturaleza"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La sustitución de la medida quebrantada por otra si ésta estuviese prevista para el supuesto de que se trate y el quebrantamiento demostras…</mark></span>- El quebrantamiento puede dar lugar a la sustitución por otra medida si está prevista y es necesaria."},{"i":"18-124","p":"Código Penal. ¿Qué consecuencia acarrea el quebrantamiento de una medida de seguridad de internamiento?","o":["El interno es liberado.","Se reducirá la medida de seguridad.","Se impone una multa.","El reingreso del sujeto en el mismo centro del que se hubiese evadido."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El reingreso del sujeto en el mismo centro del que se hubiese evadido.</mark></span>(El quebrantamiento implica el reingreso en el mismo centro)."},{"i":"18-ia-1408","p":"Código Penal. Quebrantamiento de las medidas de seguridad. El quebrantamiento de una medida de seguridad de internamiento dará lugar a que el juez o tribunal ordene:","o":["el ingreso del sujeto en un centro penitenciario ordinario, en los términos que se determinen reglamentariamente.","el reingreso del sujeto en el mismo centro del que se hubiese evadido o en otro que corresponda a su estado.","la sustitución de la medida por una pena de prisión.","el cese de la medida por incumplimiento del sujeto."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el reingreso del sujeto en el mismo centro del que se hubiese evadido o en otro que corresponda a su estado</mark></span>El <span class=\"ref-norma\">art. 100.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"El quebrantamiento de una medida de seguridad de internamiento dará lugar a que el juez o tribunal ordene el reingreso del sujeto en el mismo centro del que se hubiese evadido o en otro que corresponda a su estado\"</span>. Reingreso en el mismo centro o en otro que corresponda a su estado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1409","p":"Código Penal. Quebrantamiento de las medidas de seguridad. Si se tratare de otras medidas, el juez o tribunal podrá acordar la sustitución de la quebrantada por la de internamiento:","o":["si ésta estuviese prevista para el supuesto de que se trate y si el quebrantamiento demostrase su necesidad.","en todo caso, cuando el quebrantamiento sea grave.","si el sujeto lo consintiera y el Ministerio Fiscal lo solicitara, salvo que la autoridad judicial disponga otra cosa.","si el quebrantamiento se produjera por segunda vez."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">si ésta estuviese prevista para el supuesto de que se trate y si el quebrantamiento demostrase su necesidad</mark></span>El <span class=\"ref-norma\">art. 100.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"si ésta estuviese prevista para el supuesto de que se trate y si el quebrantamiento demostrase su necesidad\"</span>. Si el internamiento está previsto y el quebrantamiento demuestra su necesidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1410","p":"Código Penal. Quebrantamiento de las medidas de seguridad. No se considerará quebrantamiento de la medida de seguridad:","o":["la ausencia del centro durante más de veinticuatro horas.","la falta de presentación periódica ante el Juez.","el incumplimiento reiterado de las prohibiciones impuestas, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente.","la negativa del sujeto a someterse a tratamiento médico o a continuar un tratamiento médico inicialmente consentido."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la negativa del sujeto a someterse a tratamiento médico o a continuar un tratamiento médico inicialmente consentido</mark></span>El <span class=\"ref-norma\">art. 100.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"someterse a tratamiento médico o a continuar un tratamiento médico inicialmente consentido\"</span>. La negativa a someterse a tratamiento médico o a continuarlo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 117","q":[{"i":"18-71","p":"Código Penal. Los aseguradores que hubieren asumido el riesgo de las responsabilidades pecuniarias derivadas del uso o explotación de cualquier industria o actividad, cuando, como consecuencia de un hecho previsto en este Código, se produzca el evento que determine el riesgo asegurado, serán responsables civiles:","o":["Directa hasta el límite del 75% de la indemnización legalmente establecida o convencionalmente pactada, sin perjuicio del derecho de repetición contra quien corresponda","Directa hasta el límite de la indemnización legalmente establecida o convencionalmente pactada, sin perjuicio del derecho de repetición contra quien corresponda","Indirecta hasta el límite del 75% de la indemnización legalmente establecida o convencionalmente pactada, sin perjuicio del derecho de repetición contra quien corresponda","Indirecta hasta el límite de la indemnización legalmente establecida o convencionalmente pactada, sin perjuicio del derecho de repetición contra quien corresponda"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Directa hasta el límite de la indemnización legalmente establecida o convencionalmente pactada, sin perjuicio del derecho de repetición con…</mark></span>- Los aseguradores responden directamente hasta el límite de la indemnización establecida."},{"i":"18-121","p":"Código Penal. ¿Hasta qué límite son responsables civiles directos los aseguradores por las responsabilidades pecuniarias derivadas de un hecho previsto en el Código?","o":["Hasta el límite de la indemnización solicitada por la víctima.","Hasta el límite de la indemnización legalmente establecida o convencionalmente pactada.","Hasta el límite impuesto por el juez o tribunal.","Hasta el límite que los aseguradores decidan."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Hasta el límite de la indemnización legalmente establecida o convencionalmente pactada.</mark></span>(Hasta el límite de la indemnización legalmente establecida o convencionalmente pactada)."},{"i":"18-ia-1442","p":"Código Penal. Personas civilmente responsables. Los aseguradores que hubieren asumido el riesgo de las responsabilidades pecuniarias derivadas del uso o explotación de cualquier bien, empresa, industria o actividad, serán responsables civiles directos:","o":["hasta el límite de la indemnización legalmente establecida, con exclusión de lo convencionalmente pactado, en los términos que se determinen reglamentariamente.","de forma subsidiaria, sin perjuicio del derecho de repetición contra quien corresponda.","sin límite alguno, con derecho de repetición contra el asegurado.","hasta el límite de la indemnización legalmente establecida o convencionalmente pactada, sin perjuicio del derecho de repetición contra quien corresponda."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">hasta el límite de la indemnización legalmente establecida o convencionalmente pactada, sin perjuicio del derecho de repetición contra quien corresponda</mark></span>El <span class=\"ref-norma\">art. 117 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"serán responsables civiles directos hasta el límite de la indemnización legalmente establecida o convencionalmente pactada, sin perjuicio del derecho de repetición contra quien corresponda\"</span>. Responsables civiles directos hasta el límite legal o convencional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 102","q":[{"i":"18-72","p":"Código Penal. De las medidas de seguridad. No es una medida de seguridad privativa de libertad:","o":["La libertad vigilada","El internamiento en centro de desintoxicación","La custodia familiar","A y C son correctas"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A y C son correctas</mark></span>- Tanto la libertad vigilada como la custodia familiar son medidas no privativas de libertad."},{"i":"18-ia-1413","p":"Código Penal. Medidas privativas de libertad. A los exentos de responsabilidad penal por intoxicación plena o síndrome de abstinencia se les aplicará, si fuere necesaria, la medida de internamiento en:","o":["centro de deshabituación público, o privado debidamente acreditado u homologado.","centro psiquiátrico penitenciario.","centro educativo especial.","centro de deshabituación público exclusivamente, salvo que la autoridad judicial disponga otra cosa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">centro de deshabituación público, o privado debidamente acreditado u homologado</mark></span>El <span class=\"ref-norma\">art. 102.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"la medida de internamiento en centro de deshabituación público, o privado debidamente acreditado u homologado\"</span>. Centro de deshabituación público o privado acreditado u homologado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 70 ✱","q":[{"i":"18-78","p":"Código Penal. De la aplicación de las penas: El límite inferior de una pena superior en grado se formará:","o":["El límite mínimo de la pena superior en grado será el máximo de la pena señalada por la ley para el delito de que se trate, incrementado en un día o en un día multa según la naturaleza de la pena a imponer.","El límite mínimo de la pena superior en grado será el máximo de la pena señalada por la ley para el delito de que se trate, sin incremento alguno.","Se formará partiendo de la cifra máxima señalada por la ley para el delito de que se trate y aumentando a ésta la mitad de su cuantía","Todas son incorrectas"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El límite mínimo de la pena superior en grado será el máximo de la pena señalada por la ley para el delito de que se trate, incrementado en un día o en un día multa según la naturaleza de la pena a imponer</mark></span>Según el <span class=\"ref-norma\">art. 70 del Código Penal</span>: <span class=\"ref-concepto\">\"El límite mínimo de la pena superior en grado será el máximo de la pena señalada por la ley para el delito de que se trate, incrementado en un día o en un día multa según la naturaleza de la pena a imponer\"</span> (verificado con el texto del temario oficial)."},{"i":"18-82","p":"Código Penal. La pena inferior en grado se formará:","o":["Partiendo de la cifra mínima señalada para el delito de que se trate y deduciendo de ésta la mitad de su cuantía, constituyendo el resultado de tal deducción su límite mínimo. El límite mínimo de la pena inferior en grado será el mismo de la pena señalada por la ley para el delito de que se trate","Partiendo de la cifra mínima señalada para el delito de que se trate y deduciendo de ésta la mitad de la diferencia entre el límite superior e inferior, constituyendo el resultado de tal deducción su límite mínimo. El límite mínimo de la pena inferior en grado será el mismo de la pena señalada por la ley para el delito de que se trate, reducido en un día o en un día multa según la naturaleza de la pena a imponer","Partiendo de la cifra mínima señalada para el delito de que se trate y deduciendo de ésta la mitad de su cuantía, constituyendo el resultado de tal deducción su límite mínimo. El límite máximo de la pena inferior en grado será el mínimo de la pena señalada por la ley para el delito de que se trate, reducido en un día o en un día multa según la naturaleza de la pena a imponer","Todas son incorrectas"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Partiendo de la cifra mínima señalada para el delito de que se trate y deduciendo de ésta la mitad de su cuantía, constituyendo el resultado de tal deducción su límite mínimo. El límite máximo de la pena inferior en grado será el mínimo de la pena señalada por la ley para el delito de que se trate, reducido en un día o en un día multa según la naturaleza de la pena a imponer</mark></span>Según el <span class=\"ref-norma\">art. 70 del Código Penal</span>: <span class=\"ref-concepto\">\"deduciendo de ésta la mitad de su cuantía, constituyendo el resultado de tal deducción su límite mínimo. El límite máximo de la pena inferior en grado será el mínimo de la pena señalada por la ley para el delito de que se trate, reducido en un día o en un día multa según la naturaleza de la pena a imponer\"</span> (verificado con el texto del temario oficial)."},{"i":"18-83","p":"Código Penal. De la aplicación de las penas. Respecto a la pena superior en grado y su límite máximo:","o":["Se forma partiendo de la cifra máxima señalada por la ley para el delito de que se trate y desintegrando a ésta la mitad de su cuantía, constituyendo la suma resultante su límite máximo","Se forma partiendo de la cifra máxima señalada por la ley para el delito de que se trate y aumentando a ésta la mitad de su cuantía, constituyendo la suma resultante su límite máximo","Se forma partiendo de la cifra mínima señalada por la ley para el delito de que se trate y aumentando a ésta la mitad de su cuantía, constituyendo la suma resultante su límite máximo.","Ninguna es correcta"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Se forma partiendo de la cifra máxima señalada por la ley para el delito de que se trate y aumentando a ésta la mitad de su cuantía, consti…</mark></span>- La pena superior en grado se forma aumentando la mitad de la cuantía al máximo."},{"i":"18-270","p":"Código Penal. Pena superior en grado. Cuando la pena superior en grado exceda de los límites máximos, tratándose de privación del derecho a conducir vehículos a motor y ciclomotores, se considerará inmediatamente superior la misma pena, con la cláusula de que su duración máxima será de:","o":["10 años, en los términos que determine la ley orgánica correspondiente.","20 años.","15 años.","30 años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">15 años</mark></span>El <span class=\"ref-norma\">art. 70.3.4.º de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"º Tratándose de privación del derecho a conducir vehículos a motor y ciclomotores, la misma pena, con la cláusula de que su duración máxima será de 15 años\"</span>"},{"i":"18-271","p":"Código Penal. Pena superior en grado. Cuando la pena superior en grado exceda de los límites máximos, tratándose de privación del derecho a la tenencia y porte de armas, se considerará inmediatamente superior la misma pena, con la cláusula de que su duración máxima será de:","o":["15 años, salvo que el órgano competente acuerde otra cosa de forma motivada.","20 años.","10 años.","30 años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">20 años</mark></span>El <span class=\"ref-norma\">art. 70.3.5.º de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"º Tratándose de privación del derecho a la tenencia y porte de armas, la misma pena, con la cláusula de que su duración máxima será de 20 años\"</span>"},{"i":"18-ia-1306","p":"Código Penal. Pena superior e inferior en grado. La pena superior en grado se formará partiendo de la cifra máxima señalada por la ley para el delito de que se trate y aumentando a ésta:","o":["una cuarta parte de su cuantía, constituyendo la suma resultante su límite máximo.","un tercio de su cuantía, constituyendo la suma resultante su límite mínimo.","la mitad de su cuantía, constituyendo la suma resultante su límite mínimo.","la mitad de su cuantía, constituyendo la suma resultante su límite máximo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la mitad de su cuantía, constituyendo la suma resultante su límite máximo</mark></span>El <span class=\"ref-norma\">art. 70.1.1.ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"se formará partiendo de la cifra máxima señalada por la ley para el delito de que se trate y aumentando a ésta la mitad de su cuantía, constituyendo la suma resultante su límite máximo\"</span>. Se aumenta la mitad de la cifra máxima; es el límite máximo de la pena superior en grado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1307","p":"Código Penal. Pena superior e inferior en grado. El límite mínimo de la pena superior en grado será el máximo de la pena señalada por la ley para el delito de que se trate, incrementado en:","o":["un mes o en un mes multa según la naturaleza de la pena a imponer, en los términos que se determinen reglamentariamente.","un día, cualquiera que sea la naturaleza de la pena a imponer.","un día o en un día multa según la naturaleza de la pena a imponer.","una semana o en una semana multa según la naturaleza de la pena."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">un día o en un día multa según la naturaleza de la pena a imponer</mark></span>El <span class=\"ref-norma\">art. 70.1.1.ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"será el máximo de la pena señalada por la ley para el delito de que se trate, incrementado en un día o en un día multa según la naturaleza de la pena a imponer\"</span>. Un día o un día multa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1308","p":"Código Penal. Pena superior e inferior en grado. A los efectos de determinar la mitad superior o inferior de la pena o de concretar la pena inferior o superior en grado, el día o el día multa se considerarán:","o":["divisibles en horas y cuotas fraccionadas, según los casos.","indivisibles y actuarán como unidades penológicas de más o menos, según los casos.","indivisibles y se computarán siempre a favor del reo.","divisibles cuando la pena sea de multa e indivisibles en los demás casos, salvo que la autoridad judicial disponga otra cosa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">indivisibles y actuarán como unidades penológicas de más o menos, según los casos</mark></span>El <span class=\"ref-norma\">art. 70.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el día o el día multa se considerarán indivisibles y actuaran como unidades penológicas de más o menos, según los casos\"</span>. Indivisibles; actúan como unidades penológicas de más o menos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1309","p":"Código Penal. Pena superior e inferior en grado. Cuando la pena superior en grado exceda de los límites máximos fijados a cada pena en el Código, si la pena determinada fuera la de prisión, se considerará inmediatamente superior la misma pena, con la cláusula de que su duración máxima será de:","o":["30 años.","25 años, previo informe de la unidad policial competente.","40 años.","20 años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">30 años</mark></span>El <span class=\"ref-norma\">art. 70.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Si la pena determinada fuera la de prisión, la misma pena, con la cláusula de que su duración máxima será de 30 años\"</span>. Prisión: 30 años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1310","p":"Código Penal. Pena superior e inferior en grado. Cuando la pena superior en grado exceda de los límites máximos, si fuera de suspensión de empleo o cargo público, la misma pena, con la cláusula de que su duración máxima será de:","o":["seis años.","diez años.","quince años.","ocho años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">ocho años</mark></span>El <span class=\"ref-norma\">art. 70.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Si fuera de suspensión de empleo o cargo público, la misma pena, con la cláusula de que su duración máxima será de ocho años\"</span>. Suspensión de empleo o cargo público: ocho años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1311","p":"Código Penal. Pena superior e inferior en grado. Tratándose de privación del derecho a conducir vehículos a motor y ciclomotores, la pena superior en grado que exceda de los límites tendrá una duración máxima de:","o":["20 años, sin perjuicio de lo previsto en la normativa vigente.","10 años.","15 años.","30 años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">15 años</mark></span>El <span class=\"ref-norma\">art. 70.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Tratándose de privación del derecho a conducir vehículos a motor y ciclomotores, la misma pena, con la cláusula de que su duración máxima será de 15 años\"</span>. Conducir: 15 años; armas, residir, aproximarse y comunicarse: 20 años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1312","p":"Código Penal. Pena superior e inferior en grado. Tratándose de privación del derecho a la tenencia y porte de armas, la pena superior en grado que exceda de los límites tendrá una duración máxima de:","o":["15 años, en los términos que se determinen reglamentariamente.","20 años.","10 años.","30 años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">20 años</mark></span>El <span class=\"ref-norma\">art. 70.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Tratándose de privación del derecho a la tenencia y porte de armas, la misma pena, con la cláusula de que su duración máxima será de 20 años\"</span>. Tenencia y porte de armas: 20 años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1313","p":"Código Penal. Pena superior e inferior en grado. Si la pena superior en grado fuera de multa y excediera de los límites máximos, se considerará inmediatamente superior la misma pena, con la cláusula de que su duración máxima será de:","o":["30 meses.","tres años.","cuatro años.","24 meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">30 meses</mark></span>El <span class=\"ref-norma\">art. 70.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Si fuera de multa, la misma pena, con la cláusula de que su duración máxima será de 30 meses\"</span>. Multa: 30 meses. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1314","p":"Código Penal. Pena superior e inferior en grado. La pena inferior en grado a la de prisión permanente es:","o":["la pena de prisión de quince a veinticinco años.","la pena de prisión de veinte a veinticinco años.","la pena de prisión de treinta a cuarenta años.","la pena de prisión de veinte a treinta años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la pena de prisión de veinte a treinta años</mark></span>El <span class=\"ref-norma\">art. 70.4 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La pena inferior en grado a la de prisión permanente es la pena de prisión de veinte a treinta años\"</span>. Prisión de veinte a treinta años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 76 EX","q":[{"i":"18-86","p":"Código Penal. Como Regla General, el cumplimiento efectivo máximo de condena del responsable de la comisión de dos o más delitos será:","o":["El cómputo del tiempo que suponga la pena más grave impuesta con un máximo de veinte años","El triple del tiempo que suponga la pena más grave impuesta con un máximo de treinta años","El cómputo del tiempo que suponga la pena más grave impuesta con un máximo de veinticinco años","El triple del tiempo que suponga la pena más grave impuesta con un máximo de veinte años"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El triple del tiempo que suponga la pena más grave impuesta con un máximo de veinte años</mark></span>- El límite máximo es el triple de la pena más grave con máximo de 20 años."},{"i":"18-275","p":"Código Penal. Máximo de cumplimiento. Cuando el sujeto haya sido condenado por dos o más delitos y, al menos, dos de ellos estén castigados por la ley con pena de prisión superior a 20 años, el límite máximo de cumplimiento será de:","o":["25 años, en los términos que determine la ley orgánica correspondiente.","40 años.","30 años.","35 años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">40 años</mark></span>El <span class=\"ref-norma\">art. 76.1.c) de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"De 40 años, cuando el sujeto haya sido condenado por dos o más delitos y, al menos, dos de ellos estén castigados por la ley con pena de prisión superior a 20 años\"</span>"},{"i":"18-ia-1323","p":"Código Penal. Máximo de cumplimiento. El máximo de cumplimiento efectivo de la condena del culpable no podrá exceder del triple del tiempo por el que se le imponga la más grave de las penas en que haya incurrido, declarando extinguidas las que procedan desde que las ya impuestas cubran dicho máximo, que no podrá exceder de:","o":["25 años, previo informe de la unidad policial competente.","30 años.","20 años.","15 años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">20 años</mark></span>El <span class=\"ref-norma\">art. 76.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"declarando extinguidas las que procedan desde que las ya impuestas cubran dicho máximo, que no podrá exceder de 20 años\"</span>. Veinte años como regla general. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1324","p":"Código Penal. Máximo de cumplimiento. Excepcionalmente, el límite máximo de cumplimiento será de 25 años:","o":["cuando el sujeto haya sido condenado por dos o más delitos y alguno de ellos esté castigado por la ley con pena de prisión superior a 20 años.","cuando el sujeto haya sido condenado por dos o más delitos y alguno de ellos esté castigado por la ley con pena de prisión de hasta 20 años.","cuando el sujeto haya sido condenado por tres o más delitos y alguno de ellos esté castigado con pena de prisión de hasta 20 años.","cuando el sujeto haya sido condenado por dos o más delitos y al menos dos de ellos estén castigados con pena de prisión de hasta 20 años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cuando el sujeto haya sido condenado por dos o más delitos y alguno de ellos esté castigado por la ley con pena de prisión de hasta 20 años</mark></span>El <span class=\"ref-norma\">art. 76.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"a) De 25 años, cuando el sujeto haya sido condenado por dos o más delitos y alguno de ellos esté castigado por la ley con pena de prisión de hasta 20 años\"</span>. 25 años: alguno con prisión de hasta 20 años; 30 años: alguno con prisión superior a 20. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1325","p":"Código Penal. Máximo de cumplimiento. El límite máximo de cumplimiento será de 30 años cuando el sujeto haya sido condenado por dos o más delitos y:","o":["alguno de ellos esté castigado por la ley con pena de prisión superior a 20 años.","al menos dos de ellos estén castigados por la ley con pena de prisión superior a 20 años.","alguno de ellos esté castigado por la ley con pena de prisión de hasta 20 años.","alguno de ellos sea un delito de terrorismo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">alguno de ellos esté castigado por la ley con pena de prisión superior a 20 años</mark></span>El <span class=\"ref-norma\">art. 76.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"b) De 30 años, cuando el sujeto haya sido condenado por dos o más delitos y alguno de ellos esté castigado por la ley con pena de prisión superior a 20 años\"</span>. 30 años: alguno con prisión superior a 20 años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1326","p":"Código Penal. Máximo de cumplimiento. El límite máximo de cumplimiento será de 40 años cuando el sujeto haya sido condenado por dos o más delitos y:","o":["alguno de ellos esté castigado por la ley con pena de prisión superior a 20 años.","al menos tres de ellos estén castigados por la ley con pena de prisión superior a 20 años.","al menos dos de ellos estén castigados por la ley con pena de prisión de hasta 20 años.","al menos dos de ellos estén castigados por la ley con pena de prisión superior a 20 años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">al menos dos de ellos estén castigados por la ley con pena de prisión superior a 20 años</mark></span>El <span class=\"ref-norma\">art. 76.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"c) De 40 años, cuando el sujeto haya sido condenado por dos o más delitos y, al menos, dos de ellos estén castigados por la ley con pena de prisión superior a 20 años\"</span>. 40 años: al menos dos delitos con prisión superior a 20 años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1327","p":"Código Penal. Máximo de cumplimiento. La limitación del máximo de cumplimiento se aplicará aunque las penas se hayan impuesto en distintos procesos cuando lo hayan sido:","o":["por hechos cometidos después de la fecha en que fue enjuiciado el primero de ellos, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente.","por hechos cometidos con anterioridad a la firmeza de la primera sentencia dictada.","por hechos cometidos antes de la fecha en que fueron enjuiciados los que, siendo objeto de acumulación, lo hubieran sido en primer lugar.","por hechos cometidos dentro de un plazo máximo de cinco años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por hechos cometidos antes de la fecha en que fueron enjuiciados los que, siendo objeto de acumulación, lo hubieran sido en primer lugar</mark></span>El <span class=\"ref-norma\">art. 76.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"cuando lo hayan sido por hechos cometidos antes de la fecha en que fueron enjuiciados los que, siendo objeto de acumulación, lo hubieran sido en primer lugar\"</span>. Hechos cometidos antes de la fecha de enjuiciamiento del primer proceso. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 21 EX ✱","q":[{"i":"18-100","p":"Código Penal. Circunstancias que atenúan la responsabilidad criminal. NO son circunstancias atenuantes, entre otras:","o":["La de obrar por causas o estímulos tan poderosos que hayan producido arrebato, obcecación u otro estado pasional de entidad semejante","La de haber procedido el culpable, antes de conocer que el procedimiento judicial se dirige contra él, a confesar la infracción a las autoridades","La de haber procedido el culpable a reparar el daño ocasionado a la víctima, o disminuir sus efectos, en cualquier momento del procedimiento y con anterioridad a la celebración del acto del juicio oral","La dilación extraordinaria e indebida en la tramitación del procedimiento, siempre que sea atribuible al propio inculpado y que guarde proporción con la complejidad de la causa"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La dilación extraordinaria e indebida en la tramitación del procedimiento, siempre que sea atribuible al propio inculpado y que guarde prop…</mark></span>- La dilación extraordinaria sólo es atenuante cuando NO es atribuible al inculpado."},{"i":"18-129","p":"Código Penal. ¿Cuál de las siguientes opciones es una circunstancia atenuante?","o":["Actuar el culpable a causa de su grave adicción a las sustancias estupefacientes.","Actuar bajo la influencia de una leve preferencia por las sustancias.","Actuar bajo la presión de un leve interés económico.","Actuar bajo la influencia de una recomendación de un amigo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Actuar el culpable a causa de su grave adicción a las sustancias estupefacientes.</mark></span>(La grave adicción a estupefacientes puede ser circunstancia atenuante)."},{"i":"18-157","p":"Código Penal. ¿Qué debe hacer el culpable para que se considere una circunstancia atenuante antes del juicio oral?:","o":["Reparar el daño ocasionado a la víctima o disminuir sus efectos.","Confesar la infracción a un amigo o familiar.","Esperar a que el procedimiento judicial se dirija contra él para actuar.","Deteriorar la persecución de inocentes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Reparar el daño ocasionado a la víctima o disminuir sus efectos.</mark></span>(Reparar el daño o disminuir sus efectos antes del juicio oral es circunstancia atenuante)."},{"i":"18-170","p":"Código penal. Son circunstancias que atenúan la responsabilidad criminal, entre otras:","o":["La de haber procedido el culpable, después de conocer que el procedimiento judicial se dirige contra él, a confesar la infracción a las autoridades.","La de haber procedido la víctima a reparar el daño ocasionado al culpable, o disminuir sus efectos, en cualquier momento del procedimiento y con anterioridad a la celebración del acto del juicio oral.","La dilación extraordinaria e indebida en la tramitación del procedimiento, siempre que no sea atribuible al propio inculpado y que no guarde proporción con la complejidad de la causa.","A y B son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La dilación extraordinaria e indebida en la tramitación del procedimiento, siempre que no sea atribuible al propio inculpado y que no guarde proporción con la complejidad de la causa</mark></span>La confesión es atenuante si se hace «antes» de conocer que el procedimiento se dirige contra el culpable, y se repara el daño «a la víctima» (no al culpable). Según el <span class=\"ref-norma\">art. 21 del Código Penal</span>: <span class=\"ref-concepto\">\"6.ª La dilación extraordinaria e indebida en la tramitación del procedimiento, siempre que no sea atribuible al propio inculpado y que no guarde proporción con la complejidad de la causa\"</span> (verificado con el texto del temario oficial)."},{"i":"18-179","p":"Código penal. Circunstancias modificativas de la responsabilidad criminal. NO son circunstancias agravantes:","o":["Ejecutar el hecho con alevosía.","Ejecutar el hecho mediante disfraz, con abuso de superioridad o aprovechando las circunstancias de lugar, tiempo o auxilio de otras personas que debiliten la defensa del ofendido o faciliten la impunidad del ofensor.","Obrar con abuso de confianza.","La dilación extraordinaria e indebida en la tramitación del procedimiento, siempre que no sea atribuible al propio inculpado y que no guarde proporción con la complejidad de la causa."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La dilación extraordinaria e indebida en la tramitación del procedimiento, siempre que no sea atribuible al propio inculpado y que no guard…</mark></span>(Esta es una circunstancia atenuante, no agravante)."},{"i":"18-218","p":"Código Penal. Son circunstancias agravantes... indique la respuesta INCORRECTA:","o":["La de obrar por causas o estímulos tan poderosos que al ejecutar el hecho produzcan arrebato, obcecación u otro estado pasional de entidad semejante.","Prevalerse del carácter público que tenga el culpable.","Ejecutar el hecho mediante precio, recompensa o promesa.","Aumentar deliberada e inhumanamente el sufrimiento de la víctima, causando a ésta padecimientos innecesarios para la ejecución del delito."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La de obrar por causas o estímulos tan poderosos que al ejecutar el hecho produzcan arrebato, obcecación u otro estado pasional de entidad …</mark></span><span class=\"ref-norma\">Art. 21.5 · De las Circunstancias que Modifican la Responsabilidad Criminal</span>. (La opción a) describe un estado que puede ser atenuante (Art. 21.5 CP), no agravante. Los agravantes están en el Art. 22)."},{"i":"18-ia-1053","p":"Código Penal. Atenuantes. Son circunstancias atenuantes las causas expresadas en el capítulo anterior, cuando:","o":["no concurrieren todos los requisitos necesarios para eximir de responsabilidad en sus respectivos casos.","concurrieren con otra circunstancia atenuante de distinta naturaleza.","concurrieren todos los requisitos, pero en grado menor.","no concurrieren los requisitos esenciales para eximir de responsabilidad, previo informe de la unidad policial competente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no concurrieren todos los requisitos necesarios para eximir de responsabilidad en sus respectivos casos</mark></span>El <span class=\"ref-norma\">art. 21.1ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Las causas expresadas en el capítulo anterior, cuando no concurrieren todos los requisitos necesarios para eximir de responsabilidad en sus respectivos casos\"</span>. Eximente incompleta: no concurren todos los requisitos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1054","p":"Código Penal. Atenuantes. Es circunstancia atenuante la de actuar el culpable a causa de su:","o":["adicción a las sustancias estupefacientes o psicotrópicas, sin perjuicio de lo previsto en la normativa vigente.","intoxicación parcial por alcohol o drogas.","dependencia del juego patológico.","grave adicción a las sustancias mencionadas en el número 2.º del artículo anterior."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">grave adicción a las sustancias mencionadas en el número 2.º del artículo anterior</mark></span>El <span class=\"ref-norma\">art. 21.2ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La de actuar el culpable a causa de su grave adicción a las sustancias mencionadas\"</span>. Atenuante de grave adicción. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1055","p":"Código Penal. Atenuantes. Es circunstancia atenuante la de obrar por causas o estímulos tan poderosos que hayan producido:","o":["miedo, ira u otro estado emocional de entidad semejante.","arrebato, obcecación o miedo insuperable.","arrebato, obcecación u otro estado pasional de entidad semejante.","trastorno mental transitorio o estado pasional de entidad semejante."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">arrebato, obcecación u otro estado pasional de entidad semejante</mark></span>El <span class=\"ref-norma\">art. 21.3ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"causas o estímulos tan poderosos que hayan producido arrebato, obcecación u otro estado pasional de entidad semejante\"</span>. Arrebato, obcecación u otro estado pasional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1056","p":"Código Penal. Atenuantes. Es circunstancia atenuante la de haber procedido el culpable, antes de conocer que el procedimiento judicial se dirige contra él, a:","o":["reparar el daño ocasionado a la víctima.","confesar la infracción a las autoridades.","entregarse voluntariamente a las autoridades.","confesar la infracción al Juez de Instrucción."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">confesar la infracción a las autoridades</mark></span>El <span class=\"ref-norma\">art. 21.4ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"antes de conocer que el procedimiento judicial se dirige contra él, a confesar la infracción a las autoridades\"</span>. Confesión a las autoridades antes de conocer que el procedimiento se dirige contra él. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1057","p":"Código Penal. Atenuantes. Es circunstancia atenuante la de haber procedido el culpable a reparar el daño ocasionado a la víctima, o disminuir sus efectos, en cualquier momento del procedimiento y con anterioridad a:","o":["la celebración del acto del juicio oral.","la apertura del juicio oral.","la firmeza de la sentencia.","la calificación provisional del Ministerio Fiscal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la celebración del acto del juicio oral</mark></span>El <span class=\"ref-norma\">art. 21.5ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"en cualquier momento del procedimiento y con anterioridad a la celebración del acto del juicio oral\"</span>. Reparación antes de la celebración del juicio oral. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1058","p":"Código Penal. Atenuantes. Es circunstancia atenuante la dilación extraordinaria e indebida en la tramitación del procedimiento, siempre que:","o":["no sea atribuible al propio inculpado y exceda de dos años desde la incoación.","no sea atribuible al órgano judicial ni al inculpado.","no guarde proporción con la complejidad de la causa, aunque sea atribuible al inculpado, en los términos que se determinen reglamentariamente.","no sea atribuible al propio inculpado y que no guarde proporción con la complejidad de la causa."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no sea atribuible al propio inculpado y que no guarde proporción con la complejidad de la causa</mark></span>El <span class=\"ref-norma\">art. 21.6ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"siempre que no sea atribuible al propio inculpado y que no guarde proporción con la complejidad de la causa\"</span>. Requisitos: no atribuible al inculpado y desproporcionada con la complejidad de la causa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"De la Extinción de la Responsabilidad Criminal y sus Efectos","q":[{"i":"18-110","p":"Código Penal. La responsabilidad criminal se extingue:","o":["Por la muerte del reo.","Por el cumplimiento de la condena.","Por la prescripción del delito.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 130 del Código Penal</span>: <span class=\"ref-concepto\">\"1.º Por la muerte del reo. 2.º Por el cumplimiento de la condena\"</span> (verificado con el texto del temario oficial)."},{"i":"18-143","p":"Código Penal. Las penas impuestas por sentencia firme prescriben, para penas leves:","o":["Al año.","A los dos años.","A los cinco años.","A los diez años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Al año</mark></span>Penas graves: 10 a 30 años según su gravedad; menos graves: cinco años; leves: un año. Según el <span class=\"ref-norma\">art. 133 del Código Penal</span>: <span class=\"ref-concepto\">\"Al año, las penas leves\"</span> (verificado con el texto del temario oficial)."},{"i":"18-294","p":"Código Penal. Prescripción de las penas. Las penas de prisión impuestas por sentencia firme por más de 20 años prescriben:","o":["A los 25 años, sin perjuicio de lo que establezcan los tratados internacionales.","A los 20 años.","A los 30 años.","A los 15 años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A los 30 años</mark></span>El <span class=\"ref-norma\">art. 133.1 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"A los 30 años, las de prisión por más de 20 años\"</span>"},{"i":"18-ia-1528","p":"Código Penal. Causas de extinción de la responsabilidad criminal. Señale la INCORRECTA. La responsabilidad criminal se extingue:","o":["Por la muerte del reo.","Por la reincidencia del condenado en los diez años siguientes al cumplimiento.","Por el cumplimiento de la condena, sin perjuicio de lo previsto en la normativa vigente.","Por la amnistía o el indulto."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Por la reincidencia del condenado en los diez años siguientes al cumplimiento</mark></span>El <span class=\"ref-norma\">art. 130.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"1.º Por la muerte del reo. 2.º Por el cumplimiento de la condena\"</span>. La reincidencia no extingue la responsabilidad criminal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1546","p":"Código Penal. Prescripción de las penas. Las penas impuestas por sentencia firme prescriben a los treinta años cuando se trate de:","o":["las de prisión de 15 o más años sin que excedan de 20.","las de prisión de 20 años.","las de prisión por más de 25 años.","las de prisión por más de 20 años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las de prisión por más de 20 años</mark></span>El <span class=\"ref-norma\">art. 133.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"A los 30 años, las de prisión por más de 20 años\"</span>. 30 años: prisión por más de 20 años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1547","p":"Código Penal. Prescripción de las penas. Las penas impuestas por sentencia firme prescriben a los veinticinco años cuando se trate de:","o":["las de prisión por más de 20 años.","las de prisión por más de 10 y menos de 15 años, sin perjuicio de lo previsto en la normativa vigente.","las de prisión de 15 o más años sin que excedan de 20.","las de inhabilitación por más de 10 años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las de prisión de 15 o más años sin que excedan de 20</mark></span>El <span class=\"ref-norma\">art. 133.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"A los 25 años, las de prisión de 15 o más años sin que excedan de 20\"</span>. 25 años: prisión de 15 o más años sin que excedan de 20. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1548","p":"Código Penal. Prescripción de las penas. Las penas impuestas por sentencia firme prescriben, las penas menos graves, a los cinco años, y las penas leves:","o":["a los seis meses.","al año.","a los dos años.","a los tres años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">al año</mark></span>El <span class=\"ref-norma\">art. 133.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"A los cinco, las penas menos graves. Al año, las penas leves\"</span>. Penas menos graves: cinco años; leves: un año. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1549","p":"Código Penal. Cómputo de la prescripción de las penas. El tiempo de la prescripción de la pena se computará desde la fecha de la sentencia firme, o:","o":["desde el quebrantamiento de la condena, si ésta hubiese comenzado a cumplirse.","desde la fecha de la sentencia en primera instancia, en los términos que se determinen reglamentariamente.","desde la notificación de la sentencia al condenado.","desde la liquidación de la condena."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">desde el quebrantamiento de la condena, si ésta hubiese comenzado a cumplirse</mark></span>El <span class=\"ref-norma\">art. 134 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"se computará desde la fecha de la sentencia firme, o desde el quebrantamiento de la condena, si ésta hubiese comenzado a cumplirse\"</span>. Desde la sentencia firme o desde el quebrantamiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 26","q":[{"i":"18-119","p":"Código Penal. ¿Qué se considera documento según este Código?","o":["Todo soporte material que exprese o incorpore datos con eficacia probatoria.","Cualquier soporte material sin relevancia jurídica.","Solo los soportes materiales que expresen datos financieros.","Un soporte material que no exprese datos, hechos o narraciones."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Todo soporte material que exprese o incorpore datos con eficacia probatoria.</mark></span>(Documento es todo soporte material que exprese o incorpore datos con eficacia probatoria)."},{"i":"18-227","p":"Código Penal. A los efectos de este Código se considera documento todo soporte material que exprese o incorpore datos, hechos o narraciones con:","o":["Eficacia probatoria.","Cualquier otro tipo de relevancia jurídica.","A y B son correctas.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>Según el <span class=\"ref-norma\">art. 26 del Código Penal</span>: <span class=\"ref-concepto\">\"todo soporte material que exprese o incorpore datos, hechos o narraciones con eficacia probatoria o cualquier otro tipo de relevancia jurídica\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1073","p":"Código Penal. Documento. A los efectos del Código Penal se considera documento todo soporte material que exprese o incorpore datos, hechos o narraciones con:","o":["eficacia probatoria o cualquier otro tipo de relevancia jurídica.","eficacia probatoria o fe pública.","eficacia jurídica y valor oficial.","relevancia jurídica, siempre que conste firma de su autor, en los términos que se determinen reglamentariamente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">eficacia probatoria o cualquier otro tipo de relevancia jurídica</mark></span>El <span class=\"ref-norma\">art. 26 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"todo soporte material que exprese o incorpore datos, hechos o narraciones con eficacia probatoria o cualquier otro tipo de relevancia jurídica\"</span>. Eficacia probatoria o cualquier otro tipo de relevancia jurídica. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 127","q":[{"i":"18-122","p":"Código Penal. ¿Qué ocurre con los bienes, medios o instrumentos utilizados en la comisión de un delito doloso?","o":["Son devueltos al acusado tras el juicio.","Son donados a organizaciones benéficas.","Unen comisión a prueba de las mismas y de las ganancias provenientes del delito.","Se subastan al público general."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Unen comisión a prueba de las mismas y de las ganancias provenientes del delito.</mark></span>(Se decreta el comiso de los bienes, medios o instrumentos utilizados y de las ganancias del delito)."},{"i":"18-ia-1502","p":"Código Penal. Decomiso. Toda pena que se imponga por un delito doloso llevará consigo la pérdida de los efectos que de él provengan y de los bienes, medios o instrumentos con que se haya preparado o ejecutado, así como de las ganancias provenientes del delito:","o":["siempre que no hubieran sido transformadas ni transmitidas a terceros.","salvo que su valor sea inferior al de la responsabilidad civil.","únicamente cuando el condenado no pueda satisfacer la responsabilidad civil, en los términos que se determinen reglamentariamente.","cualesquiera que sean las transformaciones que hubieren podido experimentar."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">cualesquiera que sean las transformaciones que hubieren podido experimentar</mark></span>El <span class=\"ref-norma\">art. 127.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"así como de las ganancias provenientes del delito, cualesquiera que sean las transformaciones que hubieren podido experimentar\"</span>. Cualesquiera que sean las transformaciones experimentadas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1503","p":"Código Penal. Decomiso. En los casos en que la ley prevea la imposición de una pena privativa de libertad superior a un año por la comisión de un delito imprudente, el juez o tribunal:","o":["acordará en todo caso la pérdida de los efectos y de los instrumentos del delito, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente.","no podrá acordar el decomiso, que se reserva a los delitos dolosos.","podrá acordar la pérdida de los efectos que provengan del mismo y de los bienes, medios o instrumentos con que se haya preparado o ejecutado, así como de las ganancias.","podrá acordar el decomiso únicamente de las ganancias provenientes del delito."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">podrá acordar la pérdida de los efectos que provengan del mismo y de los bienes, medios o instrumentos con que se haya preparado o ejecutado, así como de las ganancias</mark></span>El <span class=\"ref-norma\">art. 127.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el juez o tribunal podrá acordar la pérdida de los efectos que provengan del mismo y de los bienes, medios o instrumentos con que se haya preparado o ejecutado, así como de las ganancias provenientes del delito\"</span>. En el delito imprudente con pena superior a un año de prisión el decomiso es facultativo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1504","p":"Código Penal. Decomiso. Si por cualquier circunstancia no fuera posible el decomiso de los bienes señalados, se acordará:","o":["la imposición de una multa equivalente a la mitad del valor de los bienes.","el decomiso de otros bienes por una cantidad que corresponda al valor económico de los mismos, y al de las ganancias que se hubieran obtenido de ellos.","la sustitución del decomiso por la responsabilidad personal subsidiaria.","el decomiso de otros bienes por una cantidad que corresponda a las ganancias obtenidas, con exclusión del valor de los bienes, sin perjuicio de lo previsto en la normativa vigente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el decomiso de otros bienes por una cantidad que corresponda al valor económico de los mismos, y al de las ganancias que se hubieran obtenido de ellos</mark></span>El <span class=\"ref-norma\">art. 127.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"se acordará el decomiso de otros bienes por una cantidad que corresponda al valor económico de los mismos, y al de las ganancias que se hubieran obtenido de ellos\"</span>. Decomiso por equivalente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 111 ✱","q":[{"i":"18-123","p":"Código Penal. ¿En qué circunstancias se debe restituir un bien, incluso si está en poder de un tercero que lo adquirió legalmente y de buena fe?","o":["Cuando el tercero haya adquirido el bien de forma ilegítima según las Leyes.","Siempre que sea posible, el mismo bien, con dinero de los deterioros y menoscabos determinados por el juez o tribunal.","Solo si el tercero no tiene derecho de repetición contra el responsable civil del delito.","Cuando el bien se halle en poder de un tercero de mala fe."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Siempre que sea posible, el mismo bien, con dinero de los deterioros y menoscabos determinados por el juez o tribunal.</mark></span>(Se restituye el bien siempre que sea posible, con compensación por deterioros)."},{"i":"18-284","p":"Código Penal. Restitución. La restitución del mismo bien, aunque se halle en poder de tercero que lo haya adquirido legalmente y de buena fe, no es aplicable:","o":["Cuando el tercero haya adquirido el bien en la forma y con los requisitos establecidos por las Leyes para hacerlo irreivindicable.","Cuando el tercero lo haya adquirido a título gratuito de buena fe.","Cuando el tercero desconociera el origen delictivo del bien.","Cuando hayan transcurrido cinco años desde que el tercero lo adquirió, sin perjuicio de lo que establezcan los tratados internacionales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cuando el tercero haya adquirido el bien en la forma y con los requisitos establecidos por las Leyes para hacerlo irreivindicable</mark></span>El <span class=\"ref-norma\">art. 111.2 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"Esta disposición no es aplicable cuando el tercero haya adquirido el bien en la forma y con los requisitos establecidos por las Leyes para hacerlo irreivindicable\"</span>"},{"i":"18-ia-1434","p":"Código Penal. Responsabilidad civil. Deberá restituirse, siempre que sea posible, el mismo bien, con abono de los deterioros y menoscabos que el juez o tribunal determinen. La restitución tendrá lugar aunque el bien se halle en poder de tercero y éste lo haya adquirido legalmente y de buena fe, dejando a salvo:","o":["su derecho a conservar el bien hasta que se le abone el precio pagado, sin perjuicio de lo previsto en la normativa vigente.","su derecho a ser indemnizado únicamente por el Estado.","su derecho a oponerse a la restitución mediante tercería de dominio.","su derecho de repetición contra quien corresponda y, en su caso, el de ser indemnizado por el responsable civil del delito."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">su derecho de repetición contra quien corresponda y, en su caso, el de ser indemnizado por el responsable civil del delito</mark></span>El <span class=\"ref-norma\">art. 111.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"dejando a salvo su derecho de repetición contra quien corresponda y, en su caso, el de ser indemnizado por el responsable civil del delito\"</span>. Derecho de repetición y a ser indemnizado por el responsable civil. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 31 bis","q":[{"i":"18-130","p":"Código Penal. ¿Bajo qué circunstancia una persona jurídica no sería penalmente responsable de un delito cometido en su nombre?","o":["Si el delito fue cometido sin su conocimiento.","Si el delito fue cometido por una persona física sin autorización.","Si antes de la comisión del delito, se adoptaron modelos de organización y gestión que incluyen las medidas de vigilancia y control idóneas para prevenir delitos de la misma naturaleza o para reducir de forma significativa el riesgo de su comisión.","Si el delito fue cometido por un competidor."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Si antes de la comisión del delito, se adoptaron modelos de organización y gestión que incluyen las medidas de vigilancia y control idóneas…</mark></span>(La existencia de compliance programs eficaces puede eximir de responsabilidad penal a la persona jurídica)."},{"i":"18-223","p":"Código Penal. En los supuestos previstos en este Código, las personas jurídicas serán penalmente responsables... Indique la opción INCORRECTA:","o":["De los delitos cometidos en nombre o por cuenta de las mismas, y en su beneficio directo o indirecto, por sus representantes legales o por aquellos que actuando individualmente o como integrantes de un órgano de la persona jurídica, no están autorizados para tomar decisiones en nombre de la persona jurídica y no ostentan facultades de organización y control dentro de la misma.","De los delitos cometidos, en el ejercicio de actividades sociales y por cuenta y en beneficio directo o indirecto de las mismas, por quienes, estando sometidos a la autoridad de las personas físicas mencionadas en el párrafo anterior, han podido realizar los hechos por haberse incumplido gravemente por aquéllos los deberes de supervisión, vigilancia y control de su actividad atendidas las concretas circunstancias del caso.","Las anteriores son respuestas correctas.","Ninguna de las respuestas anteriores es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">De los delitos cometidos en nombre o por cuenta de las mismas, y en su beneficio directo o indirecto, por sus representantes legales o por …</mark></span><span class=\"ref-norma\">Art. 31 bis · De las Personas Criminalmente Responsables de los Delitos</span>. (La opción a) es incorrecta porque la responsabilidad de la persona jurídica requiere que el delito sea cometido por quienes sí tienen facultades de organización y control, no por quienes carecen de ellas. Se regula en el Artículo 31 bis del CP)."},{"i":"18-ia-1113","p":"Código Penal. Responsabilidad de las personas jurídicas. En los supuestos previstos en el Código, las personas jurídicas serán penalmente responsables de los delitos cometidos en nombre o por cuenta de las mismas, y en su beneficio directo o indirecto, por:","o":["sus representantes legales o por aquellos que actuando individualmente o como integrantes de un órgano de la persona jurídica, están autorizados para tomar decisiones en nombre de la persona jurídica u ostentan facultades de organización y control dentro de la misma.","sus representantes legales o por los empleados que actúen por cuenta de la persona jurídica y bajo su dependencia.","sus representantes legales o por aquellos que, estando sometidos a la autoridad de los administradores, hayan podido realizar los hechos.","sus administradores de derecho y por quienes ostenten facultades de organización y control, con exclusión de los administradores de hecho, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">sus representantes legales o por aquellos que actuando individualmente o como integrantes de un órgano de la persona jurídica, están autorizados para tomar decisiones en nombre de la persona jurídica u ostentan facultades de organización y control dentro de la misma</mark></span>El <span class=\"ref-norma\">art. 31 bis.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"por sus representantes legales o por aquellos que actuando individualmente o como integrantes de un órgano de la persona jurídica, están autorizados\"</span>. Letra a): representantes legales y quienes puedan tomar decisiones u ostenten facultades de organización y control. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1114","p":"Código Penal. Responsabilidad de las personas jurídicas. Las personas jurídicas serán penalmente responsables de los delitos cometidos, en el ejercicio de actividades sociales y por cuenta y en beneficio directo o indirecto de las mismas, por quienes, estando sometidos a la autoridad de las personas físicas mencionadas en la letra a), han podido realizar los hechos por haberse incumplido gravemente por aquéllos los deberes de:","o":["información, vigilancia y control de su actividad atendidas las circunstancias del caso.","supervisión, formación y control de su actividad en el ámbito de la organización.","vigilancia, dirección y control de la actividad atendidas las concretas circunstancias del caso, salvo que la autoridad judicial disponga otra cosa.","supervisión, vigilancia y control de su actividad atendidas las concretas circunstancias del caso."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">supervisión, vigilancia y control de su actividad atendidas las concretas circunstancias del caso</mark></span>El <span class=\"ref-norma\">art. 31 bis.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"han podido realizar los hechos por haberse incumplido gravemente por aquéllos los deberes de supervisión, vigilancia y control de su actividad atendidas las concretas circunstancias del caso\"</span>. Deberes de supervisión, vigilancia y control. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1115","p":"Código Penal. Exención de responsabilidad. Si el delito fuere cometido por sus representantes legales o por quienes están autorizados para tomar decisiones en su nombre, la persona jurídica quedará exenta de responsabilidad si el órgano de administración ha adoptado y ejecutado con eficacia, antes de la comisión del delito, modelos de organización y gestión que incluyen las medidas de vigilancia y control idóneas para prevenir delitos de la misma naturaleza o para:","o":["evitar de forma absoluta el riesgo de su comisión.","reducir el riesgo de su comisión a un nivel tolerable, previo informe de la unidad policial competente.","reducir de forma significativa el riesgo de su comisión.","impedir la participación de terceros en su comisión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">reducir de forma significativa el riesgo de su comisión</mark></span>El <span class=\"ref-norma\">art. 31 bis.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"o para reducir de forma significativa el riesgo de su comisión\"</span>. Se exige prevenir delitos de la misma naturaleza o reducir de forma significativa el riesgo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1116","p":"Código Penal. Exención de responsabilidad. Señale la INCORRECTA. Para que la persona jurídica quede exenta de responsabilidad cuando el delito lo cometan sus representantes y directivos, deben cumplirse las siguientes condiciones:","o":["Que el órgano de administración haya adoptado y ejecutado con eficacia, antes de la comisión del delito, modelos de organización y gestión.","Que la supervisión del modelo haya sido confiada siempre a un órgano externo e independiente de la persona jurídica.","Que los autores individuales hayan cometido el delito eludiendo fraudulentamente los modelos de organización y de prevención.","Que no se haya producido una omisión o un ejercicio insuficiente de sus funciones de supervisión, vigilancia y control por parte del órgano de supervisión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Que la supervisión del modelo haya sido confiada siempre a un órgano externo e independiente de la persona jurídica</mark></span>El <span class=\"ref-norma\">art. 31 bis.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"2.ª la supervisión del funcionamiento y del cumplimiento del modelo de prevención implantado ha sido confiada a un órgano de la persona jurídica con poderes autónomos de iniciativa y de control\"</span>. El órgano de supervisión es de la propia persona jurídica, con poderes autónomos de iniciativa y de control. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1117","p":"Código Penal. Exención de responsabilidad. La supervisión del funcionamiento y del cumplimiento del modelo de prevención implantado ha de ser confiada a un órgano de la persona jurídica:","o":["con poderes autónomos de iniciativa y de control o que tenga encomendada legalmente la función de supervisar la eficacia de los controles internos de la persona jurídica.","con poderes delegados de iniciativa y de control o que tenga encomendada estatutariamente la función de supervisar los controles internos, sin perjuicio de lo previsto en la normativa vigente.","con poderes autónomos de iniciativa y de control y que tenga encomendada legalmente la función de auditoría.","dependiente del órgano de administración, con funciones de supervisión de los controles internos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">con poderes autónomos de iniciativa y de control o que tenga encomendada legalmente la función de supervisar la eficacia de los controles internos de la persona jurídica</mark></span>El <span class=\"ref-norma\">art. 31 bis.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"ha sido confiada a un órgano de la persona jurídica con poderes autónomos de iniciativa y de control o que tenga encomendada legalmente la función de supervisar la eficacia de los controles internos de la persona jurídica\"</span>. Poderes autónomos de iniciativa y de control, o función legal de supervisar los controles internos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1118","p":"Código Penal. Exención de responsabilidad. En los casos en los que las circunstancias que eximen a la persona jurídica solamente puedan ser objeto de acreditación parcial, esta circunstancia será valorada a los efectos de:","o":["exención parcial de la responsabilidad civil.","suspensión de la ejecución de la pena.","sustitución de la pena de multa.","atenuación de la pena."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">atenuación de la pena</mark></span>El <span class=\"ref-norma\">art. 31 bis.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"esta circunstancia será valorada a los efectos de atenuación de la pena\"</span>. La acreditación parcial se valora como atenuación de la pena. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1119","p":"Código Penal. Personas jurídicas de pequeñas dimensiones. En las personas jurídicas de pequeñas dimensiones, las funciones de supervisión podrán ser asumidas directamente por el órgano de administración. Son personas jurídicas de pequeñas dimensiones aquéllas que, según la legislación aplicable, estén autorizadas a presentar:","o":["balance de situación abreviado, en los términos que se determinen reglamentariamente.","cuentas anuales simplificadas.","cuenta de pérdidas y ganancias abreviada.","memoria económica abreviada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">cuenta de pérdidas y ganancias abreviada</mark></span>El <span class=\"ref-norma\">art. 31 bis.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"son personas jurídicas de pequeñas dimensiones aquéllas que, según la legislación aplicable, estén autorizadas a presentar cuenta de pérdidas y ganancias abreviada\"</span>. El criterio es la cuenta de pérdidas y ganancias abreviada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1120","p":"Código Penal. Exención de responsabilidad. Si el delito fuera cometido por las personas que, estando sometidas a la autoridad de los representantes y directivos, han podido realizar los hechos por incumplimiento grave de los deberes de supervisión, la persona jurídica quedará exenta de responsabilidad si, antes de la comisión del delito, ha adoptado y ejecutado eficazmente un modelo de organización y gestión que resulte:","o":["idóneo para prevenir cualquier clase de delito y reducir de forma absoluta el riesgo de su comisión, salvo que la autoridad judicial disponga otra cosa.","adecuado para prevenir delitos de la naturaleza del que fue cometido o para reducir de forma significativa el riesgo de su comisión.","aprobado por el órgano de supervisión y comunicado al Ministerio Fiscal.","certificado por un órgano externo e independiente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">adecuado para prevenir delitos de la naturaleza del que fue cometido o para reducir de forma significativa el riesgo de su comisión</mark></span>El <span class=\"ref-norma\">art. 31 bis.4 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"ha adoptado y ejecutado eficazmente un modelo de organización y gestión que resulte adecuado para prevenir delitos de la naturaleza del que fue cometido o para reducir de forma significativa el riesgo de su comisión\"</span>. Modelo adecuado para prevenir delitos de esa naturaleza o reducir de forma significativa el riesgo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1122","p":"Código Penal. Modelos de organización y gestión. Los modelos de organización y gestión realizarán una verificación periódica del modelo y de su eventual modificación cuando se pongan de manifiesto infracciones relevantes de sus disposiciones, o cuando se produzcan cambios:","o":["en la composición del órgano de administración o en la estructura de capital.","en la legislación aplicable o en la actividad desarrollada que los hagan necesarios, previo informe de la unidad policial competente.","en la organización o en la estructura de control, aunque no los hagan necesarios.","en la organización, en la estructura de control o en la actividad desarrollada que los hagan necesarios."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">en la organización, en la estructura de control o en la actividad desarrollada que los hagan necesarios</mark></span>El <span class=\"ref-norma\">art. 31 bis.5 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"o cuando se produzcan cambios en la organización, en la estructura de control o en la actividad desarrollada que los hagan necesarios\"</span>. Cambios en la organización, en la estructura de control o en la actividad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 99","q":[{"i":"18-133","p":"Código Penal. Si con la ejecución de la pena se pusieran en peligro los efectos conseguidos a través de la medida de seguridad, ¿qué puede hacer el juez o tribunal?","o":["Aumentar la duración de la pena.","Suspender el cumplimiento del resto de la pena por un plazo no superior a la duración de la misma.","Eliminar la medida de seguridad.","Ninguna es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Suspender el cumplimiento del resto de la pena por un plazo no superior a la duración de la misma.</mark></span>(El juez puede suspender el cumplimiento de la pena para no poner en peligro los efectos de la medida de seguridad)."},{"i":"18-ia-1406","p":"Código Penal. Concurrencia de penas y medidas de seguridad. En el caso de concurrencia de penas y medidas de seguridad privativas de libertad, el juez o tribunal ordenará el cumplimiento de la medida, que:","o":["se cumplirá después de la pena.","se cumplirá simultáneamente con la pena.","se computará solo si el sujeto lo solicita.","se abonará para el de la pena."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">se abonará para el de la pena</mark></span>El <span class=\"ref-norma\">art. 99 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el juez o tribunal ordenará el cumplimiento de la medida, que se abonará para el de la pena\"</span>. Se cumple la medida y se abona para el cumplimiento de la pena. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1407","p":"Código Penal. Concurrencia de penas y medidas de seguridad. Una vez alzada la medida de seguridad, el juez o tribunal podrá, si con la ejecución de la pena se pusieran en peligro los efectos conseguidos a través de aquélla, suspender el cumplimiento del resto de la pena por un plazo:","o":["no superior a la mitad de la misma.","no superior a cinco años.","no superior a la duración de la misma.","no inferior a la duración de la misma, sin perjuicio de lo previsto en la normativa vigente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">no superior a la duración de la misma</mark></span>El <span class=\"ref-norma\">art. 99 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"suspender el cumplimiento del resto de la pena por un plazo no superior a la duración de la misma, o aplicar alguna de las medidas previstas en el artículo 96.3\"</span>. Plazo no superior a la duración de la pena; o aplicar medidas no privativas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 128","q":[{"i":"18-136","p":"Código Penal. ¿En qué circunstancias puede el Juez o Tribunal no decretar el decomiso de efectos e instrumentos de lícito comercio?","o":["Cuando los efectos e instrumentos son de lícito comercio y su valor guarda proporción con la naturaleza o gravedad de la infracción penal.","Cuando los efectos e instrumentos son de lícito comercio y su valor no guarda proporción con la naturaleza o gravedad de la infracción penal.","Siempre se debe decretar el decomiso sin excepciones.","El decomiso no se aplica a efectos e instrumentos de lícito comercio."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cuando los efectos e instrumentos son de lícito comercio y su valor no guarda proporción con la naturaleza o gravedad de la infracción pena…</mark></span>(Cuando el valor no guarda proporción con la gravedad del delito, puede no decretarse el decomiso)."},{"i":"18-ia-1522","p":"Código Penal. Decomiso de efectos e instrumentos. Cuando los referidos efectos e instrumentos sean de lícito comercio y su valor no guarde proporción con la naturaleza o gravedad de la infracción penal, o se hayan satisfecho completamente las responsabilidades civiles, podrá el Juez o Tribunal:","o":["decretar el decomiso por valor equivalente.","decretar el decomiso de forma provisional.","sustituir el decomiso por una multa proporcional, previo informe de la unidad policial competente.","no decretar el decomiso, o decretarlo parcialmente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no decretar el decomiso, o decretarlo parcialmente</mark></span>El <span class=\"ref-norma\">art. 128 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"podrá el Juez o Tribunal no decretar el decomiso, o decretarlo parcialmente\"</span>. No decretar el decomiso o decretarlo parcialmente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 11 EX","q":[{"i":"18-138","p":"Código Penal. ¿En qué caso se equiparará la omisión a la acción para la comisión de un delito?","o":["Cuando el omisor tenga un deber moral de actuar.","Cuando exista una específica obligación legal o contractual de actuar.","Cuando el omisor haya presenciado el hecho.","Cuando el omisor haya tenido la oportunidad de evitar el resultado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cuando exista una específica obligación legal o contractual de actuar</mark></span>También cuando el omitente haya creado una ocasión de riesgo mediante una acción u omisión precedente. Según el <span class=\"ref-norma\">art. 11 del Código Penal</span>: <span class=\"ref-concepto\">\"a) Cuando exista una específica obligación legal o contractual de actuar\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1021","p":"Código Penal. Comisión por omisión. Los delitos que consistan en la producción de un resultado sólo se entenderán cometidos por omisión cuando la no evitación del mismo, al infringir un especial deber jurídico del autor, equivalga, según el sentido del texto de la ley, a:","o":["su causación.","su tentativa.","su encubrimiento.","su provocación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">su causación</mark></span>El <span class=\"ref-norma\">art. 11 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"equivalga, según el sentido del texto de la ley, a su causación\"</span>. La no evitación equivale a la causación del resultado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1022","p":"Código Penal. Comisión por omisión. Señale la INCORRECTA. La omisión se equiparará a la acción:","o":["Cuando exista una específica obligación legal de actuar.","Cuando exista una específica obligación contractual de actuar.","Cuando el omitente haya creado una ocasión de riesgo para el bien jurídicamente protegido mediante una acción u omisión precedente.","Cuando el omitente haya sido requerido por la autoridad para actuar."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuando el omitente haya sido requerido por la autoridad para actuar</mark></span>El <span class=\"ref-norma\">art. 11 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"a) Cuando exista una específica obligación legal o contractual de actuar. b) Cuando el omitente haya creado una ocasión de riesgo para el bien jurídicamente protegido mediante una acción u omisión precedente\"</span>. Los supuestos son la obligación legal o contractual y la creación de una ocasión de riesgo; el requerimiento de la autoridad no figura. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 25","q":[{"i":"18-149","p":"Código Penal. ¿Qué se entiende por \"persona con discapacidad necesitada de especial protección\" según el Código?","o":["Una persona con discapacidad que no requiere asistencia.","Una persona sin discapacidad que requiere asistencia.","Una persona con discapacidad que, tenga o no judicialmente modificada su capacidad de obrar, requiera de asistencia o apoyo para el ejercicio de su capacidad jurídica y para la toma de decisiones reservadas a la persona, de sus derechos o intereses a causa de sus deficiencias intelectuales o mentales de carácter permanente.","Una persona con discapacidad que no tiene deficiencias intelectuales o mentales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Una persona con discapacidad que, tenga o no judicialmente modificada su capacidad de obrar, requiera de asistencia o apoyo para el ejercic…</mark></span>(Esta es la definición legal de persona con discapacidad necesitada de especial protección)."},{"i":"18-ia-1071","p":"Código Penal. Discapacidad. A los efectos del Código Penal se entiende por discapacidad aquella situación en que se encuentra una persona con deficiencias físicas, mentales, intelectuales o sensoriales de carácter permanente que, al interactuar con diversas barreras, puedan:","o":["limitar su capacidad de obrar y su participación en la vida social.","impedir su participación plena y efectiva en la sociedad, con independencia de las demás, sin perjuicio de lo previsto en la normativa vigente.","limitar o impedir su participación plena y efectiva en la sociedad, en igualdad de condiciones con las demás.","limitar o impedir su autonomía personal, en igualdad de condiciones con las demás."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">limitar o impedir su participación plena y efectiva en la sociedad, en igualdad de condiciones con las demás</mark></span>El <span class=\"ref-norma\">art. 25 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"puedan limitar o impedir su participación plena y efectiva en la sociedad, en igualdad de condiciones con las demás\"</span>. Participación plena y efectiva en la sociedad en igualdad de condiciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1072","p":"Código Penal. Discapacidad. Se entenderá por persona con discapacidad necesitada de especial protección a aquella persona con discapacidad que, tenga o no judicialmente modificada su capacidad de obrar, requiera de asistencia o apoyo para el ejercicio de su capacidad jurídica y para la toma de decisiones respecto de su persona, de sus derechos o intereses a causa de sus deficiencias:","o":["físicas o sensoriales de carácter permanente.","intelectuales o mentales de carácter permanente.","intelectuales, mentales o sensoriales de carácter permanente.","intelectuales o mentales de carácter temporal o permanente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">intelectuales o mentales de carácter permanente</mark></span>El <span class=\"ref-norma\">art. 25 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"a causa de sus deficiencias intelectuales o mentales de carácter permanente\"</span>. Deficiencias intelectuales o mentales de carácter permanente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 113","q":[{"i":"18-152","p":"Código Penal. De la responsabilidad civil y su extensión. ¿Qué comprende la indemnización de perjuicios materiales y morales?","o":["Solo los daños causados al agraviado.","Los daños causados al agraviado y a sus familiares o a terceros.","Los daños causados al agraviado y a terceros.","Solo los daños causados a terceros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los daños causados al agraviado y a sus familiares o a terceros.</mark></span>(La indemnización comprende daños al agraviado, sus familiares y terceros perjudicados)."},{"i":"18-ia-1436","p":"Código Penal. Responsabilidad civil. La indemnización de perjuicios materiales y morales comprenderá no sólo los que se hubieren causado al agraviado, sino también:","o":["los que se hubieren irrogado a sus herederos exclusivamente.","los que se hubieren irrogado a sus familiares o a terceros.","los que se hubieren causado a la Administración pública.","los que se hubieren producido con posterioridad a la sentencia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los que se hubieren irrogado a sus familiares o a terceros</mark></span>El <span class=\"ref-norma\">art. 113 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"sino también los que se hubieren irrogado a sus familiares o a terceros\"</span>. También a familiares o terceros. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"De las Circunstancias que Modifican la Responsabilidad Criminal","q":[{"i":"18-155","p":"Código Penal. De las personas criminalmente responsables de los delitos. Sólo podrán considerarse circunstancias atenuantes de la responsabilidad penal de las personas jurídicas haber realizado, con posterioridad a la comisión del delito y a través de sus representantes legales, las siguientes actividades:","o":["Haber procedido, antes de conocer que el procedimiento judicial se dirige contra ella, a confesar la infracción a las autoridades.","Haber procedido en cualquier momento del procedimiento y con anterioridad al juicio oral a reparar o disminuir el daño causado por el delito.","Haber colaborado en la investigación del hecho aportando pruebas, en cualquier momento del proceso, que fueran nuevas y decisivas para establecer las responsabilidades penales dimanantes de los hechos.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span>(Todas estas actividades pueden considerarse circunstancias atenuantes para personas jurídicas)."}]},{"a":"Artículo 127 quater","q":[{"i":"18-156","p":"Código Penal. De las consecuencias accesorias. Se presumirá, salvo prueba en contrario, que el tercero ha conocido o ha tenido motivos para sospechar que se trataba de bienes procedentes de una actividad ilícita o que han transferidos para evitar su decomiso, cuando:","o":["Siempre que reciba bienes de cualquier tipo.","Cuando los bienes le son transferidos a título gratuito o por un precio inferior al valor de mercado.","Si los bienes son transferidos mediante un contrato legal.","Solo si hay una denuncia previa sobre la procedencia de los bienes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cuando los bienes le son transferidos a título gratuito o por un precio inferior al valor de mercado.</mark></span>(La presunción opera cuando la transferencia es gratuita o por precio inferior al mercado)."},{"i":"18-ia-1511","p":"Código Penal. Decomiso a terceros. Se presumirá, salvo prueba en contrario, que el tercero ha conocido o ha tenido motivos para sospechar que se trataba de bienes procedentes de una actividad ilícita o que eran transferidos para evitar su decomiso, cuando los bienes o efectos le hubieran sido transferidos:","o":["a título oneroso por un precio igual al de mercado.","por un familiar del condenado, cualquiera que fuese el precio.","a título gratuito o por un precio inferior al real de mercado.","mediante escritura pública después de la apertura del procedimiento."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">a título gratuito o por un precio inferior al real de mercado</mark></span>El <span class=\"ref-norma\">art. 127 quater.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"cuando los bienes o efectos le hubieran sido transferidos a título gratuito o por un precio inferior al real de mercado\"</span>. A título gratuito o por precio inferior al real de mercado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 96 EX","q":[{"i":"18-158","p":"Código Penal. Las medidas de seguridad que se pueden imponer con arreglo a este Código son, entre otras:","o":["Privativas de libertad.","No privativas de libertad.","Privativas de otros derechos.","A y B son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>Las multas son penas, no medidas de seguridad. Según el <span class=\"ref-norma\">art. 96 del Código Penal</span>: <span class=\"ref-concepto\">\"Las medidas de seguridad que se pueden imponer con arreglo a este Código son privativas y no privativas de libertad\"</span> (verificado con el texto del temario oficial)."},{"i":"18-235","p":"Código Penal. De las medidas de seguridad en general. ¿Cuál de las siguientes se consideran medidas privativas de libertad?","o":["El internamiento en centro educativo especial.","La inhabilitación profesional.","La privación del derecho a conducir vehículos a motor y ciclomotores.","La privación del derecho a la tenencia y porte de armas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El internamiento en centro educativo especial.</mark></span><span class=\"ref-norma\">Art. 96.3 · De las Medidas de Seguridad</span>. (El internamiento en centro educativo especial es una medida privativa de libertad según el Artículo 96.3 del CP)."},{"i":"18-277","p":"Código Penal. Medidas privativas de libertad. Son medidas de seguridad privativas de libertad:","o":["La inhabilitación profesional y la expulsión del territorio nacional de extranjeros no residentes legalmente en España, salvo que el órgano competente acuerde otra cosa de forma motivada.","La libertad vigilada y la custodia familiar.","El internamiento en centro psiquiátrico y la libertad vigilada.","El internamiento en centro psiquiátrico, el internamiento en centro de deshabituación y el internamiento en centro educativo especial."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El internamiento en centro psiquiátrico, el internamiento en centro de deshabituación y el internamiento en centro educativo especial</mark></span>El <span class=\"ref-norma\">art. 96.2 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"Son medidas privativas de libertad: 1.ª El internamiento en centro psiquiátrico. 2.ª El internamiento en centro de deshabituación. 3.ª El internamiento en centro educativo especial\"</span>"},{"i":"18-ia-1342","p":"Código Penal. Medidas de seguridad en general. Señale la INCORRECTA. Son medidas privativas de libertad:","o":["El internamiento en centro psiquiátrico.","El internamiento en centro de deshabituación.","El internamiento en centro educativo especial.","La libertad vigilada."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La libertad vigilada</mark></span>El <span class=\"ref-norma\">art. 96.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Son medidas privativas de libertad: 1.ª El internamiento en centro psiquiátrico. 2.ª El internamiento en centro de deshabituación. 3.ª El internamiento en centro educativo especial\"</span>. La libertad vigilada es medida no privativa de libertad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1343","p":"Código Penal. Medidas de seguridad en general. Señale la INCORRECTA. Son medidas no privativas de libertad:","o":["La inhabilitación profesional.","La expulsión del territorio nacional de extranjeros no residentes legalmente en España.","El internamiento en centro de deshabituación.","La privación del derecho a la tenencia y porte de armas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El internamiento en centro de deshabituación</mark></span>El <span class=\"ref-norma\">art. 96.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Son medidas no privativas de libertad: 1.ª) La inhabilitación profesional. 2.ª) La expulsión del territorio nacional de extranjeros no residentes legalmente en España\"</span>. El internamiento en centro de deshabituación es privativa de libertad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1344","p":"Código Penal. Medidas de seguridad en general. Respecto de la medida de custodia familiar, el sometido a esta medida quedará sujeto al cuidado y vigilancia del familiar que se designe y que acepte la custodia, quien la ejercerá en relación con:","o":["el Ministerio Fiscal y con suspensión de las actividades escolares o laborales del custodiado.","el Juez de Vigilancia Penitenciaria y sin menoscabo de las actividades escolares o laborales del custodiado.","los servicios sociales penitenciarios y sin menoscabo de las actividades laborales del custodiado, previo informe de la unidad policial competente.","el Juez sentenciador y con limitación de las actividades escolares o laborales del custodiado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el Juez de Vigilancia Penitenciaria y sin menoscabo de las actividades escolares o laborales del custodiado</mark></span>El <span class=\"ref-norma\">art. 96.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"quien la ejercerá en relación con el Juez de Vigilancia Penitenciaria y sin menoscabo de las actividades escolares o laborales del custodiado\"</span>. Juez de Vigilancia Penitenciaria y sin menoscabo de las actividades escolares o laborales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 109","q":[{"i":"18-161","p":"Código Penal. De las responsabilidad civil y su extensión. ¿Qué opción tiene el perjudicado por un delito en cuanto a la responsabilidad civil?:","o":["Solo puede exigirla ante la Jurisdicción Penal.","Debe renunciar a cualquier tipo de compensación.","Puede optar por exigir la responsabilidad civil ante la Jurisdicción Civil.","Está obligado a aceptar una compensación asignada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Puede optar por exigir la responsabilidad civil ante la Jurisdicción Civil.</mark></span>(El perjudicado puede optar por la vía civil o la penal para reclamar la responsabilidad civil)."},{"i":"18-ia-1431","p":"Código Penal. Responsabilidad civil. La ejecución de un hecho descrito por la ley como delito obliga a reparar, en los términos previstos en las leyes:","o":["los daños materiales y morales causados al ofendido.","los perjuicios causados, con exclusión de los daños morales.","los daños y perjuicios por él causados.","los daños causados, con independencia de que se derive responsabilidad penal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los daños y perjuicios por él causados</mark></span>El <span class=\"ref-norma\">art. 109.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"obliga a reparar, en los términos previstos en las leyes, los daños y perjuicios por él causados\"</span>. Obliga a reparar los daños y perjuicios causados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1432","p":"Código Penal. Responsabilidad civil. El perjudicado podrá optar, en todo caso, por exigir la responsabilidad civil:","o":["ante la Jurisdicción Contencioso-Administrativa.","ante la Jurisdicción Civil.","únicamente en el proceso penal.","ante la Jurisdicción Civil, salvo que el Ministerio Fiscal ejercite la acción."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">ante la Jurisdicción Civil</mark></span>El <span class=\"ref-norma\">art. 109.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"El perjudicado podrá optar, en todo caso, por exigir la responsabilidad civil ante la Jurisdicción Civil\"</span>. Ante la Jurisdicción Civil. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 127 sexies ✱","q":[{"i":"18-172","p":"Código penal. De las consecuencias accesorias. El juez o tribunal podrá acordar que las presunciones establecidas en relación al decomiso no sean aplicadas con relación a determinados bienes, efectos o ganancias, cuando, en las circunstancias concretas del caso, se revelen:","o":["Incorrectas o desproporcionadas.","Injustas o desproporcionadas.","Injustas o proporcionadas.","Incorrectas o paradójicas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Incorrectas o desproporcionadas</mark></span>Según el <span class=\"ref-norma\">art. 127 sexies del Código Penal</span>: <span class=\"ref-concepto\">\"cuando, en las circunstancias concretas del caso, se revelen incorrectas o desproporcionadas\"</span> (verificado con el texto del temario oficial)."},{"i":"18-185","p":"Código penal. De las consecuencias accesorias. A los efectos del decomiso, serán de aplicación las siguientes presunciones:","o":["Se presumirá que todos los bienes adquiridos por el condenado dentro del período de tiempo que se inicia cinco años antes de la fecha de apertura del procedimiento penal, proceden de su actividad delictiva.","Se presumirá que todos los gastos realizados por el condenado durante el período de tiempo que se inicia cinco años antes de la fecha de apertura del procedimiento penal, se pagaron con fondos procedentes de su actividad delictiva.","Se presumirá que todos los bienes adquiridos por el condenado dentro del período de tiempo que se inicia cinco años antes de la fecha de apertura del procedimiento penal, fueron adquiridos libres de cargas.","Se presumirá que todos los bienes adquiridos por el condenado dentro del período de tiempo que se inicia seis años antes de la fecha de apertura del procedimiento penal, proceden de su actividad delictiva."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Se presumirá que todos los bienes adquiridos por el condenado dentro del período de tiempo que se inicia cinco años antes de la fecha de ap…</mark></span> (Se presume el origen delictivo de bienes adquiridos en los 5 años anteriores al procedimiento). TEST 13 Based on the analysis of the provided images, here is the complete list of questions and answers from &quot"},{"i":"18-ia-1516","p":"Código Penal. Presunciones del decomiso. Se presumirá que todos los bienes adquiridos por el condenado dentro del período de tiempo que se inicia seis años antes de la fecha de apertura del procedimiento penal:","o":["han sido adquiridos con ingresos de origen lícito.","proceden de su actividad delictiva.","pertenecen a terceras personas de buena fe.","fueron adquiridos con cargas y gravámenes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">proceden de su actividad delictiva</mark></span>El <span class=\"ref-norma\">art. 127 sexies del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Se presumirá que todos los bienes adquiridos por el condenado dentro del período de tiempo que se inicia seis años antes de la fecha de apertura del procedimiento penal, proceden de su actividad delictiva\"</span>. Se presume su origen delictivo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1517","p":"Código Penal. Presunciones del decomiso. Entre las presunciones del decomiso, se presumirá que todos los bienes fueron adquiridos:","o":["libres de cargas.","con fondos de origen lícito.","a título oneroso y de buena fe.","mediante transmisiones simuladas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">libres de cargas</mark></span>El <span class=\"ref-norma\">art. 127 sexies del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"3.º Se presumirá que todos los bienes a que se refiere el número 1 fueron adquiridos libres de cargas\"</span>. Libres de cargas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1518","p":"Código Penal. Presunciones del decomiso. El juez o tribunal podrá acordar que las presunciones no sean aplicadas con relación a determinados bienes, efectos o ganancias, cuando, en las circunstancias concretas del caso:","o":["se revelen insuficientes o inciertas.","el condenado así lo solicite y el Ministerio Fiscal no se oponga.","los bienes hayan sido adquiridos antes de los seis años anteriores.","se revelen incorrectas o desproporcionadas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">se revelen incorrectas o desproporcionadas</mark></span>El <span class=\"ref-norma\">art. 127 sexies del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"cuando, en las circunstancias concretas del caso, se revelen incorrectas o desproporcionadas\"</span>. Incorrectas o desproporcionadas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 127 quinquies","q":[{"i":"18-180","p":"Código penal. De las consecuencias accesorias. Se entenderá que el delito se ha cometido en el contexto de una actividad delictiva continuada siempre que:","o":["El sujeto sea condenado o haya sido condenado en el mismo procedimiento por tres o más delitos de las que se haya derivado la obtención de un beneficio económico directo o indirecto o por un delito continuado que incluya, al menos, tres infracciones penales de las que haya derivado un beneficio económico directo o indirecto.","En el período de cinco años anterior al momento en que se inició el procedimiento en el que ha sido condenado por alguno de los delitos a que se refiere el artículo 127 bis del Código Penal, hubiera sido condenado por dos o más delitos de las que hubiera derivado la obtención de un beneficio económico, o por un delito continuado que incluya, al menos, dos infracciones penales de las que ha derivado la obtención de un beneficio económico.","El sujeto sea condenado o haya sido condenado en el mismo procedimiento por tres o más delitos de las que se haya derivado la obtención de un beneficio económico directo o indirecto o por un delito continuado que incluya, al menos, tres infracciones penales de las que haya derivado un beneficio económico directo.","El sujeto sea condenado o haya sido condenado en el mismo procedimiento por tres o más delitos de las que se haya derivado la obtención de un beneficio económico directo o indirecto o por un delito continuado que incluya, al menos, dos infracciones penales de las que haya derivado un beneficio económico directo o indirecto."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El sujeto sea condenado o haya sido condenado en el mismo procedimiento por tres o más delitos de las que se haya derivado la obtención de …</mark></span>(Esta es la definición correcta de actividad delictiva continuada)."},{"i":"18-ia-1512","p":"Código Penal. Decomiso por actividad delictiva previa. El decomiso de bienes provenientes de la actividad delictiva previa del condenado requiere cumulativamente, entre otros requisitos, que el delito se haya cometido en el contexto de:","o":["una organización criminal estable.","una actividad delictiva previa continuada.","una pluralidad de delitos contra el patrimonio.","una actividad delictiva transnacional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">una actividad delictiva previa continuada</mark></span>El <span class=\"ref-norma\">art. 127 quinquies.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"b) Que el delito se haya cometido en el contexto de una actividad delictiva previa continuada\"</span>. Contexto de una actividad delictiva previa continuada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1513","p":"Código Penal. Decomiso por actividad delictiva previa. Lo dispuesto sobre los indicios relevantes solamente será de aplicación cuando consten indicios fundados de que el sujeto ha obtenido, a partir de su actividad delictiva, un beneficio superior a:","o":["6.000 euros.","3.000 euros.","12.000 euros.","30.000 euros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">6.000 euros</mark></span>El <span class=\"ref-norma\">art. 127 quinquies.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"un beneficio superior a 6.000 euros\"</span>. Más de 6.000 euros. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1514","p":"Código Penal. Decomiso por actividad delictiva previa. Se entenderá que el delito se ha cometido en el contexto de una actividad delictiva continuada siempre que el sujeto sea condenado o haya sido condenado en el mismo procedimiento por:","o":["dos o más delitos de los que se haya derivado un beneficio económico, o por un delito continuado que incluya, al menos, dos infracciones penales, previo informe de la unidad policial competente.","cuatro o más delitos de los que se haya derivado la obtención de un beneficio económico directo.","tres o más delitos, siempre que alguno sea de los enumerados como graves.","tres o más delitos de los que se haya derivado la obtención de un beneficio económico directo o indirecto, o por un delito continuado que incluya, al menos, tres infracciones penales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tres o más delitos de los que se haya derivado la obtención de un beneficio económico directo o indirecto, o por un delito continuado que incluya, al menos, tres infracciones penales</mark></span>El <span class=\"ref-norma\">art. 127 quinquies.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"a) El sujeto sea condenado o haya sido condenado en el mismo procedimiento por tres o más delitos de los que se haya derivado la obtención de un beneficio económico directo o indirecto, o por un delito continuado que incluya, al menos, tres infracciones penales\"</span>. Tres o más delitos (o delito continuado con tres infracciones); alternativamente dos en los seis años anteriores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1515","p":"Código Penal. Decomiso por actividad delictiva previa. Se entenderá cometido en el contexto de una actividad delictiva continuada si en el período de __________ anterior al momento en que se inició el procedimiento hubiera sido condenado por dos o más delitos de los que hubiera derivado la obtención de un beneficio económico:","o":["cinco años","diez años","seis años","tres años"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">seis años</mark></span>El <span class=\"ref-norma\">art. 127 quinquies.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"b) O en el período de seis años anterior al momento en que se inició el procedimiento en el que ha sido condenado por alguno de los delitos a que se refiere el artículo 127 bis del Código Penal, hubiera sido condenado por dos o más delitos\"</span>. Seis años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 34 EX","q":[{"i":"18-182","p":"Código penal. De las penas, sus efectos y clases. No se reputarán penas: señale la INCORRECTA.","o":["La detención y la prisión preventiva.","Las multas y demás correcciones que, en uso de atribuciones gubernativas o disciplinarias, se impongan a los subordinados o administrados.","Las privaciones de derechos y las sanciones reparadoras que establezcan las leyes civiles o administrativas.","Las medidas cautelares de naturaleza civil."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las medidas cautelares de naturaleza civil.</mark></span>(Las medidas cautelares civiles no están incluidas en esta enumeración)."}]},{"a":"Artículo 6 ✱","q":[{"i":"18-184","p":"Código penal. De las garantías penales y de la aplicación de la Ley penal. Respecto de las medidas de seguridad, señale la CORRECTA:","o":["Las medidas de seguridad se fundamentan en la peligrosidad criminal del sujeto al que se impongan, exteriorizada en la comisión de un hecho previsto como delito.","Las medidas de seguridad pueden resultar más gravosas, incluso de mayor duración que la pena abstractamente aplicable al hecho cometido.","Las medidas de seguridad pueden exceder el límite de lo necesario para prevenir la peligrosidad del autor.","Las medidas de seguridad se fundamentan en la capacidad para delinquir del sujeto al que se impongan, exteriorizada en su peligrosidad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las medidas de seguridad se fundamentan en la peligrosidad criminal del sujeto al que se impongan, exteriorizada en la comisión de un hecho…</mark></span>(Las medidas de seguridad requieren peligrosidad criminal exteriorizada en un delito)."},{"i":"18-ia-1013","p":"Código Penal. Medidas de seguridad. Las medidas de seguridad se fundamentan en la peligrosidad criminal del sujeto al que se impongan, exteriorizada en:","o":["la comisión de un hecho previsto como delito.","la reiteración de conductas antisociales.","el informe pericial del médico forense.","la comisión de un hecho previsto como delito grave."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la comisión de un hecho previsto como delito</mark></span>El <span class=\"ref-norma\">art. 6.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"exteriorizada en la comisión de un hecho previsto como delito\"</span>. Basta la comisión de un hecho previsto como delito. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1014","p":"Código Penal. Medidas de seguridad. Las medidas de seguridad no pueden resultar ni más gravosas ni de mayor duración que la pena abstractamente aplicable al hecho cometido, ni exceder el límite de:","o":["lo necesario para reinsertar socialmente al autor.","lo establecido por el Juez de Vigilancia Penitenciaria.","lo necesario para proteger a la víctima.","lo necesario para prevenir la peligrosidad del autor."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">lo necesario para prevenir la peligrosidad del autor</mark></span>El <span class=\"ref-norma\">art. 6.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"ni exceder el límite de lo necesario para prevenir la peligrosidad del autor\"</span>. El límite es lo necesario para prevenir la peligrosidad del autor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 37 R18","q":[{"i":"18-190","p":"Código Penal. En los casos en los que la localización permanente esté prevista como pena principal, atendiendo a la reiteración en la comisión de la infracción y siempre que así lo disponga expresamente el concreto precepto aplicable, el Juez podrá acordar en sentencia que la pena de localización permanente se cumpla en el centro penitenciario más próximo al domicilio del penado:","o":["Los sábados.","Los domingos.","Los días festivos.","Todas son correctas. *"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas. *</mark></span>Según el <span class=\"ref-norma\">art. 37 del Código Penal</span>: <span class=\"ref-concepto\">\"el Juez podrá acordar en sentencia que la pena de localización permanente se cumpla los sábados, domingos y días festivos en el centro penitenciario más próximo al domicilio del penado\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1164","p":"Código Penal. Localización permanente. El cumplimiento de la localización permanente obliga al penado a permanecer:","o":["en su domicilio o en el establecimiento penitenciario más próximo, según decida el Juez de Vigilancia Penitenciaria.","en su domicilio o en lugar determinado fijado por el Juez en sentencia o posteriormente en auto motivado.","en el centro penitenciario más próximo a su domicilio los sábados, domingos y festivos.","en su domicilio o en lugar determinado fijado por el Juez únicamente en sentencia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en su domicilio o en lugar determinado fijado por el Juez en sentencia o posteriormente en auto motivado</mark></span>El <span class=\"ref-norma\">art. 37.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Su cumplimiento obliga al penado a permanecer en su domicilio o en lugar determinado fijado por el Juez en sentencia o posteriormente en auto motivado\"</span>. Domicilio o lugar fijado por el Juez en sentencia o posteriormente en auto motivado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1165","p":"Código Penal. Localización permanente. Cuando la localización permanente esté prevista como pena principal, atendiendo a la reiteración en la comisión de la infracción y siempre que así lo disponga expresamente el concreto precepto aplicable, el Juez podrá acordar en sentencia que se cumpla:","o":["los sábados, domingos y días festivos en el centro penitenciario más próximo al domicilio del penado.","los sábados y domingos en el domicilio del penado.","de forma no continuada en el centro penitenciario más próximo al domicilio, salvo que la autoridad judicial disponga otra cosa.","los días laborables en el establecimiento penitenciario más próximo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los sábados, domingos y días festivos en el centro penitenciario más próximo al domicilio del penado</mark></span>El <span class=\"ref-norma\">art. 37.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el Juez podrá acordar en sentencia que la pena de localización permanente se cumpla los sábados, domingos y días festivos en el centro penitenciario más próximo al domicilio del penado\"</span>. Sábados, domingos y festivos en el centro penitenciario más próximo al domicilio. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1166","p":"Código Penal. Localización permanente. Si el reo lo solicitare y las circunstancias lo aconsejaren, oído el ministerio fiscal, el juez o tribunal sentenciador podrá acordar que la condena de localización permanente se cumpla:","o":["durante los días laborables o de forma no continuada, previo informe de la unidad policial competente.","únicamente durante los sábados y domingos.","en el centro penitenciario más próximo al domicilio.","durante los sábados y domingos o de forma no continuada."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">durante los sábados y domingos o de forma no continuada</mark></span>El <span class=\"ref-norma\">art. 37.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"podrá acordar que la condena se cumpla durante los sábados y domingos o de forma no continuada\"</span>. Sábados y domingos o de forma no continuada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1167","p":"Código Penal. Localización permanente. Si el condenado incumpliera la pena de localización permanente, el juez o tribunal sentenciador:","o":["revocará la pena y la sustituirá por prisión.","deducirá testimonio para proceder por un delito de desobediencia grave, sin perjuicio de lo previsto en la normativa vigente.","deducirá testimonio para proceder de conformidad con lo que dispone el artículo 468.","ordenará su ingreso inmediato en prisión por el tiempo pendiente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">deducirá testimonio para proceder de conformidad con lo que dispone el artículo 468</mark></span>El <span class=\"ref-norma\">art. 37.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el juez o tribunal sentenciador deducirá testimonio para proceder de conformidad con lo que dispone el artículo 468\"</span>. Se deduce testimonio para proceder por quebrantamiento de condena. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1168","p":"Código Penal. Localización permanente. Para garantizar el cumplimiento efectivo de la localización permanente, el Juez o Tribunal podrá acordar:","o":["la presentación periódica del penado ante la autoridad judicial.","la utilización de medios mecánicos o electrónicos que permitan la localización del reo.","el ingreso del penado en un centro penitenciario los fines de semana, en los términos que se determinen reglamentariamente.","la retirada cautelar del pasaporte del penado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la utilización de medios mecánicos o electrónicos que permitan la localización del reo</mark></span>El <span class=\"ref-norma\">art. 37.4 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"podrá acordar la utilización de medios mecánicos o electrónicos que permitan la localización del reo\"</span>. Medios mecánicos o electrónicos de localización. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1208","p":"Código Penal. Localización permanente. Cuando la localización permanente esté prevista como pena principal, atendiendo a la reiteración en la comisión de la infracción y siempre que así lo disponga expresamente el concreto precepto aplicable, el Juez podrá acordar en sentencia que se cumpla los sábados, domingos y días festivos:","o":["en el domicilio del penado bajo vigilancia electrónica.","en el centro penitenciario más próximo al domicilio del penado.","en el lugar determinado por los servicios sociales penitenciarios.","en el establecimiento de cumplimiento adecuado a su grado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en el centro penitenciario más próximo al domicilio del penado</mark></span>El <span class=\"ref-norma\">art. 37.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el Juez podrá acordar en sentencia que la pena de localización permanente se cumpla los sábados, domingos y días festivos en el centro penitenciario más próximo al domicilio del penado\"</span>. En el centro penitenciario más próximo al domicilio del penado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 41","q":[{"i":"18-191","p":"Código Penal. De las penas privativas de derechos. La pena de inhabilitación absoluta produce, además, la incapacidad para obtener los mismos o cualesquiera otros honores, cargos o empleos públicos, y la de ser elegido para cargo público, durante:","o":["El tiempo de la condena y posterior a ella, según convenga.","El tiempo que el Juez estime conveniente.","El tiempo de la condena.","El tiempo que establezca el Código Penal para cada caso. *"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El tiempo de la condena.</mark></span><span class=\"ref-norma\">Art. 41 · De las Penas</span>. El tiempo de la condena. (Los efectos de la inhabilitación absoluta, según el Artículo 41 del Código Penal, se extienden por el tiempo de la condena).*"},{"i":"18-226","p":"Código Penal. De las penas privativas de derechos, señale la respuesta CORRECTA:","o":["La pena de inhabilitación absoluta produce la privación temporal de todos los honores, empleos y cargos públicos que tenga el penado, aunque sean electivos.","La pena de inhabilitación absoluta produce, además, la incapacidad para obtener los mismos o cualesquiera otros honores, cargos o empleos públicos, y la de ser elegido para cargo público, durante el tiempo de la condena.","A y B son respuestas correctas.","La pena de inhabilitación parcial produce, además, la incapacidad para obtener los mismos o cualesquiera otros honores, cargos o empleos públicos, y la de ser elegido para cargo público, durante el tiempo de la condena."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La pena de inhabilitación absoluta produce, además, la incapacidad para obtener los mismos o cualesquiera otros honores, cargos o empleos p…</mark></span><span class=\"ref-norma\">Art. 41 · De las Penas</span>. (La opción a) es incorrecta porque la inhabilitación absoluta produce la privación definitiva, no temporal, de los cargos durante el tiempo de la condena. La opción b) refleja correctamente los efectos de la inhabilitación absoluta según el Artículo 41 del CP)."},{"i":"18-ia-1217","p":"Código Penal. Inhabilitación absoluta. La pena de inhabilitación absoluta produce la privación definitiva de todos los honores, empleos y cargos públicos que tenga el penado:","o":["aunque sean electivos.","salvo los de carácter electivo.","excepto los honoríficos.","salvo los obtenidos por oposición."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">aunque sean electivos</mark></span>El <span class=\"ref-norma\">art. 41 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La pena de inhabilitación absoluta produce la privación definitiva de todos los honores, empleos y cargos públicos que tenga el penado, aunque sean electivos\"</span>. Aunque sean electivos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 48","q":[{"i":"18-200","p":"Código Penal. De las penas privativas de derechos. La prohibición de comunicarse con la víctima, o con aquellos de sus familiares u otras personas que determine el juez o tribunal, impide al penado establecer con ellas, por cualquier medio de comunicación o medio informático o telemático, contacto: señale la INCORRECTA.","o":["Visual.","Verbal.","Escrito.","Físico. *"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Físico. *</mark></span>El contacto «visual» sí figura; el «físico» no figura entre los contactos prohibidos por esta pena. Según el <span class=\"ref-norma\">art. 48 del Código Penal</span>: <span class=\"ref-concepto\">\"contacto escrito, verbal o visual\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1226","p":"Código Penal. Privación del derecho a residir; prohibición de aproximarse y de comunicarse. La privación del derecho a residir en determinados lugares o acudir a ellos impide al penado residir o acudir al lugar en que haya cometido el delito, o a aquel en que resida:","o":["la víctima, con exclusión de su familia.","el perjudicado o sus herederos, en todo caso.","la víctima o su familia, aunque coincidan con el del delito.","la víctima o su familia, si fueren distintos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la víctima o su familia, si fueren distintos</mark></span>El <span class=\"ref-norma\">art. 48.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"o a aquel en que resida la víctima o su familia, si fueren distintos\"</span>. El lugar de residencia de la víctima o su familia, si fueren distintos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1227","p":"Código Penal. Privación del derecho a residir; prohibición de aproximarse y de comunicarse. La prohibición de aproximarse a la víctima impide al penado acercarse a ella, en cualquier lugar donde se encuentre, así como a su domicilio, a sus lugares de trabajo y a cualquier otro que sea frecuentado por ellos, quedando en suspenso, respecto de los hijos, el régimen de visitas, comunicación y estancia que se hubiere reconocido en sentencia civil:","o":["durante el primer año de cumplimiento de esta pena.","hasta que lo autorice el juez de vigilancia penitenciaria.","hasta el total cumplimiento de esta pena.","durante el tiempo que determine el Ministerio Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">hasta el total cumplimiento de esta pena</mark></span>El <span class=\"ref-norma\">art. 48.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"quedando en suspenso, respecto de los hijos, el régimen de visitas, comunicación y estancia que, en su caso, se hubiere reconocido en sentencia civil hasta el total cumplimiento de esta pena\"</span>. Queda en suspenso hasta el total cumplimiento de la pena. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1228","p":"Código Penal. Privación del derecho a residir; prohibición de aproximarse y de comunicarse. La prohibición de comunicarse con la víctima, o con aquellos de sus familiares u otras personas que determine el juez o tribunal, impide al penado establecer con ellas, por cualquier medio de comunicación o medio informático o telemático, contacto:","o":["escrito o verbal, pero no visual.","escrito, verbal o visual.","directo o indirecto, aun por tercera persona.","personal o telefónico exclusivamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">escrito, verbal o visual</mark></span>El <span class=\"ref-norma\">art. 48.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"por cualquier medio de comunicación o medio informático o telemático, contacto escrito, verbal o visual\"</span>. Contacto escrito, verbal o visual. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 53 R21","q":[{"i":"18-211","p":"Código Penal. ¿En qué supuesto, los Jueces y Tribunales establecerán, según su prudente arbitrio, que la responsabilidad personal subsidiaria que proceda, no podrá exceder, en ningún caso, de un año de duración?","o":["En supuestos de multa revisable.","En supuestos de multa permanente.","En supuestos de multa proporcional.","Ninguna de las anteriores es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En supuestos de multa proporcional.</mark></span><span class=\"ref-norma\">Art. 53.1 · De las Penas</span>. (Según el Artículo 53.1 del CP, en los supuestos de multa proporcional, la responsabilidad personal subsidiaria no podrá exceder de un año)."},{"i":"18-ia-1243","p":"Código Penal. Responsabilidad personal subsidiaria por impago de multa. Tratándose de delitos leves, la responsabilidad personal subsidiaria por impago de multa podrá cumplirse mediante localización permanente. En este caso:","o":["regirá la limitación de duración de seis meses establecida para la localización permanente.","se cumplirá siempre en el centro penitenciario más próximo al domicilio del penado.","no regirá la limitación que en su duración establece el apartado 1 del artículo 37.","se exigirá la conformidad previa del penado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">no regirá la limitación que en su duración establece el apartado 1 del artículo 37</mark></span>El <span class=\"ref-norma\">art. 53.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"que, tratándose de delitos leves, podrá cumplirse mediante localización permanente. En este caso, no regirá la limitación que en su duración establece el apartado 1 del artículo 37\"</span>. No rige el límite de duración del artículo 37.1. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1244","p":"Código Penal. Responsabilidad personal subsidiaria por impago de multa. En los supuestos de multa proporcional los Jueces y Tribunales establecerán, según su prudente arbitrio, la responsabilidad personal subsidiaria que proceda, que no podrá exceder, en ningún caso, de:","o":["seis meses de duración.","un año de duración.","dos años de duración.","tres meses de duración."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">un año de duración</mark></span>El <span class=\"ref-norma\">art. 53.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"que no podrá exceder, en ningún caso, de un año de duración\"</span>. Un año de duración. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1247","p":"Código Penal. Responsabilidad personal subsidiaria por impago de multa. Si la persona jurídica condenada no satisficiere, voluntariamente o por vía de apremio, la multa impuesta en el plazo que se hubiere señalado, el Tribunal podrá acordar:","o":["su disolución y la liquidación de su patrimonio.","la suspensión de sus actividades por un plazo de hasta cinco años.","su intervención hasta el pago total de la misma.","la clausura de sus locales y establecimientos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">su intervención hasta el pago total de la misma</mark></span>El <span class=\"ref-norma\">art. 53.5 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el Tribunal podrá acordar su intervención hasta el pago total de la misma\"</span>. Intervención hasta el pago total de la multa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 9","q":[{"i":"18-216","p":"Código Penal. Las disposiciones de este Título (De las garantías penales y de la aplicación de la Ley penal) se aplicarán a los delitos que se hallen penados por leyes... Indique la respuesta CORRECTA:","o":["Generales","Especiales","Ordinarias","Anteriores"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Especiales</mark></span><span class=\"ref-norma\">Art. 6 · Título Preliminar: De las Garantías Penales y de la Aplicación de la Ley Penal</span>. (El Artículo 6 del CP establece que las disposiciones del Título I se aplican también a los delitos penados por leyes especiales)."},{"i":"18-ia-1019","p":"Código Penal. Leyes especiales. Las disposiciones del Título Preliminar se aplicarán a los delitos que se hallen penados por leyes especiales. Las restantes disposiciones del Código se aplicarán:","o":["con carácter preferente sobre lo previsto en ellas.","únicamente cuando lo disponga el Juez o Tribunal.","como supletorias en lo no previsto expresamente por aquéllas.","como complementarias, aun cuando la ley especial prevea la materia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">como supletorias en lo no previsto expresamente por aquéllas</mark></span>El <span class=\"ref-norma\">art. 9 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Las restantes disposiciones de este Código se aplicarán como supletorias en lo no previsto expresamente por aquéllas\"</span>. El Código es supletorio de las leyes penales especiales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 24 R14","q":[{"i":"18-217","p":"Código Penal. A los efectos penales se reputará autoridad al que por sí solo o como miembro de alguna corporación, tribunal u órgano colegiado tenga mando o ejerza jurisdicción propia. En todo caso, tendrán la consideración de autoridad... Señale la opción INCORRECTA:","o":["Los miembros del Congreso de los Diputados.","Los miembros del Senado.","Las Administraciones Públicas.","Los miembros de las Asambleas Legislativas de las Comunidades Autónomas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las Administraciones Públicas.</mark></span><span class=\"ref-norma\">Art. 24 · De las Penas</span>. (Las &quot;Administraciones Públicas&quot; son entidades, no personas físicas a las que se pueda reputar autoridad. El Artículo 24 del CP se refiere a personas físicas)."},{"i":"18-ia-1068","p":"Código Penal. Autoridad. A los efectos penales se reputará autoridad al que por sí solo o como miembro de alguna corporación, tribunal u órgano colegiado:","o":["tenga mando o ejerza funciones públicas.","tenga mando o ejerza jurisdicción propia.","ejerza jurisdicción propia o delegada.","participe en el ejercicio de funciones públicas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">tenga mando o ejerza jurisdicción propia</mark></span>El <span class=\"ref-norma\">art. 24.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"se reputará autoridad al que por sí solo o como miembro de alguna corporación, tribunal u órgano colegiado tenga mando o ejerza jurisdicción propia\"</span>. Autoridad: mando o jurisdicción propia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1069","p":"Código Penal. Autoridad. Señale la INCORRECTA. En todo caso, tendrán la consideración de autoridad:","o":["Los miembros de las Corporaciones Locales.","Los miembros del Congreso de los Diputados y del Senado.","Los miembros de las Asambleas Legislativas de las Comunidades Autónomas y del Parlamento Europeo.","Los funcionarios del Ministerio Fiscal y los Fiscales de la Fiscalía Europea."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los miembros de las Corporaciones Locales</mark></span>El <span class=\"ref-norma\">art. 24.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"En todo caso, tendrán la consideración de autoridad los miembros del Congreso de los Diputados, del Senado, de las Asambleas Legislativas de las Comunidades Autónomas y del Parlamento Europeo. Tendrán también la consideración de autoridad los funcionarios del Ministerio Fiscal y los Fiscales de la Fiscalía Europea\"</span>. Los miembros de las Corporaciones Locales no figuran entre los que lo son en todo caso. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1070","p":"Código Penal. Funcionario público. Se considerará funcionario público todo el que por disposición inmediata de la Ley o por elección o por nombramiento de autoridad competente:","o":["desempeñe un cargo o empleo público de carácter permanente.","tenga mando o ejerza jurisdicción propia.","ejerza funciones públicas retribuidas.","participe en el ejercicio de funciones públicas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">participe en el ejercicio de funciones públicas</mark></span>El <span class=\"ref-norma\">art. 24.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"todo el que por disposición inmediata de la Ley o por elección o por nombramiento de autoridad competente participe en el ejercicio de funciones públicas\"</span>. Funcionario: participa en el ejercicio de funciones públicas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 47","q":[{"i":"18-225","p":"Código Penal. Sobre la imposición de la pena, indique la que considere CORRECTA:","o":["La imposición de la pena de privación del derecho a conducir vehículos a motor y ciclomotores inhabilitará al penado para el ejercicio de ambos derechos durante el tiempo fijado en la sentencia.","La imposición de la pena de privación del derecho a la tenencia y porte de armas inhabilitará al penado para el ejercicio de este derecho por el tiempo fijado en la sentencia.","Cuando la pena impuesta lo fuere por un tiempo superior a dos años comportará la pérdida de vigencia del permiso o licencia que habilite para la conducción o la tenencia y porte, respectivamente.","Todas las respuestas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las respuestas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 47 del Código Penal</span>: <span class=\"ref-concepto\">\"Cuando la pena impuesta lo fuere por un tiempo superior a dos años comportará la pérdida de vigencia del permiso o licencia que habilite para la conducción o la tenencia y porte, respectivamente\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1225","p":"Código Penal. Privación del derecho a conducir y a la tenencia y porte de armas. Cuando la pena de privación del derecho a conducir vehículos a motor y ciclomotores o de la tenencia y porte de armas se imponga por un tiempo superior a dos años, comportará:","o":["la pérdida de vigencia del permiso o licencia que habilite para la conducción o la tenencia y porte, respectivamente.","la suspensión temporal del permiso o licencia durante el tiempo de la condena, salvo que la autoridad judicial disponga otra cosa.","la retirada cautelar del permiso o licencia durante cinco años.","la imposibilidad de obtener otro permiso o licencia durante diez años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la pérdida de vigencia del permiso o licencia que habilite para la conducción o la tenencia y porte, respectivamente</mark></span>El <span class=\"ref-norma\">art. 47 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Cuando la pena impuesta lo fuere por un tiempo superior a dos años comportará la pérdida de vigencia del permiso o licencia que habilite para la conducción o la tenencia y porte, respectivamente\"</span>. Más de dos años: pérdida de vigencia del permiso o licencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 49","q":[{"i":"18-228","p":"Código Penal. De las condiciones de los trabajos en beneficio de la comunidad. Los servicios sociales penitenciarios, hechas las verificaciones necesarias, comunicarán al Juez de Vigilancia Penitenciaria las incidencias relevantes de la ejecución de la pena y, en todo caso, ¿qué circunstancias? señale la INCORRECTA.","o":["Se ausenta del trabajo durante al menos dos jornadas laborales, siempre que ello suponga un rechazo voluntario por su parte al cumplimiento de la pena.","A pesar de los requerimientos del responsable del centro de trabajo, su rendimiento fuera sensiblemente superior al mínimo exigible.","Se opusiera o incumpliera de forma reiterada y manifiesta las instrucciones que se le dieren por el responsable de la ocupación referidas al desarrollo de la misma.","Por cualquier otra razón, su conducta fuere tal que el responsable del trabajo se negase a seguir manteniéndolo en el centro."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">A pesar de los requerimientos del responsable del centro de trabajo, su rendimiento fuera sensiblemente superior al mínimo exigible</mark></span>Es un rendimiento «inferior» (no «superior») al mínimo exigible. Según el <span class=\"ref-norma\">art. 49 del Código Penal</span>: <span class=\"ref-concepto\">\"b) A pesar de los requerimientos del responsable del centro de trabajo, su rendimiento fuera sensiblemente inferior al mínimo exigible\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1229","p":"Código Penal. Trabajos en beneficio de la comunidad. Los trabajos en beneficio de la comunidad no podrán imponerse sin el consentimiento de la persona condenada, y su duración diaria no podrá exceder de:","o":["ocho horas.","seis horas.","diez horas.","cuatro horas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">ocho horas</mark></span>El <span class=\"ref-norma\">art. 49 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Su duración diaria no podrá exceder de ocho horas\"</span>. Ocho horas diarias. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1231","p":"Código Penal. Trabajos en beneficio de la comunidad. Los servicios sociales penitenciarios, hechas las verificaciones necesarias, comunicarán al Juez de Vigilancia Penitenciaria las incidencias relevantes de la ejecución de la pena y, en todo caso, si el penado se ausenta del trabajo durante al menos:","o":["tres jornadas laborales, siempre que ello suponga un rechazo voluntario por su parte al cumplimiento de la pena.","dos jornadas laborales consecutivas, sin necesidad de que exista rechazo voluntario.","dos jornadas laborales, siempre que ello suponga un rechazo voluntario por su parte al cumplimiento de la pena.","cinco jornadas laborales alternas dentro del mismo mes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">dos jornadas laborales, siempre que ello suponga un rechazo voluntario por su parte al cumplimiento de la pena</mark></span>El <span class=\"ref-norma\">art. 49.6.ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Se ausenta del trabajo durante al menos dos jornadas laborales, siempre que ello suponga un rechazo voluntario por su parte al cumplimiento de la pena\"</span>. Al menos dos jornadas laborales, y siempre que suponga un rechazo voluntario al cumplimiento de la pena. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1232","p":"Código Penal. Trabajos en beneficio de la comunidad. Si el penado faltara del trabajo por causa justificada no se entenderá como abandono de la actividad. No obstante:","o":["el trabajo perdido se computará como trabajado a efectos de la liquidación de la condena.","el trabajo perdido no se le computará en la liquidación de la condena.","el juez fijará una jornada adicional por cada falta justificada.","se prorrogará la pena por un periodo igual al de ausencia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el trabajo perdido no se le computará en la liquidación de la condena</mark></span>El <span class=\"ref-norma\">art. 49.7.ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"No obstante, el trabajo perdido no se le computará en la liquidación de la condena, en la que se deberán hacer constar los días o jornadas que efectivamente hubiese trabajado del total que se le hubiera impuesto\"</span>. El trabajo perdido no se computa; se harán constar los días o jornadas efectivamente trabajados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 95","q":[{"i":"18-231","p":"Código Penal. Las medidas de seguridad, previos los informes que estime convenientes, a las personas que se encuentren en los supuestos previstos, siempre que concurran las circunstancias establecidas, se aplicarán:","o":["Por el Juez o Tribunal.","Por el Ministerio Fiscal.","Por la autoridad que les custodie.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Por el Juez o Tribunal.</mark></span><span class=\"ref-norma\">Art. 95 · De las Medidas de Seguridad</span>. (Las medidas de seguridad son aplicadas exclusivamente por el Juez o Tribunal según el Artículo 95 del CP)."},{"i":"18-ia-1340","p":"Código Penal. Medidas de seguridad en general. Las medidas de seguridad se aplicarán por el Juez o Tribunal, previos los informes que estime convenientes, a las personas que se encuentren en los supuestos previstos en el capítulo siguiente, siempre que el sujeto haya cometido un hecho previsto como delito y:","o":["del hecho y de las circunstancias personales del sujeto pueda deducirse su peligrosidad social y su necesidad de tratamiento, salvo que la autoridad judicial disponga otra cosa.","del hecho y de las circunstancias personales del sujeto pueda deducirse un pronóstico de comportamiento futuro que revele la probabilidad de comisión de nuevos delitos.","haya sido declarado inimputable por sentencia firme y exista informe médico forense.","exista un pronóstico de reincidencia confirmado por el Ministerio Fiscal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">del hecho y de las circunstancias personales del sujeto pueda deducirse un pronóstico de comportamiento futuro que revele la probabilidad de comisión de nuevos delitos</mark></span>El <span class=\"ref-norma\">art. 95.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"2.ª Que del hecho y de las circunstancias personales del sujeto pueda deducirse un pronóstico de comportamiento futuro que revele la probabilidad de comisión de nuevos delitos\"</span>. Hecho previsto como delito y pronóstico de probabilidad de nuevos delitos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1341","p":"Código Penal. Medidas de seguridad en general. Cuando la pena que hubiere podido imponerse por el delito cometido no fuere privativa de libertad, el juez o tribunal sentenciador sólo podrá acordar:","o":["alguna o algunas de las medidas no privativas de libertad.","alguna de las medidas privativas de libertad, por un máximo de un año.","cualquiera de las medidas previstas en el Código, previo informe forense.","únicamente la medida de libertad vigilada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">alguna o algunas de las medidas no privativas de libertad</mark></span>El <span class=\"ref-norma\">art. 95.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el juez o tribunal sentenciador sólo podrá acordar alguna o algunas de las medidas previstas en el artículo 96.3\"</span>. Solo medidas no privativas de libertad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 56","q":[{"i":"18-237","p":"Código Penal. En las penas de prisión inferiores a diez años, los jueces o tribunales impondrán, atendiendo a la gravedad del delito, como penas accesorias: señale la INCORRECTA.","o":["Suspensión de empleo o cargo público.","Inhabilitación especial para empleo o cargo público, profesión, oficio, industria, comercio, ejercicio de la patria potestad, tutela, curatela, guarda o acogimiento o cualquier otro derecho, la privación de la patria potestad, si estos derechos hubieren tenido relación directa con el delito cometido, debiendo determinarse expresamente en la sentencia esta vinculación.","Inhabilitación especial para el derecho de sufragio pasivo durante el tiempo de la condena.","Inhabilitación temporal para el derecho de sufragio activo durante el tiempo de la condena."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Inhabilitación temporal para el derecho de sufragio activo durante el tiempo de la condena</mark></span>El sufragio afectado es el pasivo (ser elegido), no el activo. Según el <span class=\"ref-norma\">art. 56 del Código Penal</span>: <span class=\"ref-concepto\">\"1.º Suspensión de empleo o cargo público. 2.º Inhabilitación especial para el derecho de sufragio pasivo durante el tiempo de la condena\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1251","p":"Código Penal. Penas accesorias. En las penas de prisión inferiores a diez años, los jueces o tribunales impondrán, atendiendo a la gravedad del delito, como penas accesorias, alguna o algunas de las siguientes: suspensión de empleo o cargo público, inhabilitación especial para el derecho de sufragio pasivo durante el tiempo de la condena e:","o":["inhabilitación absoluta durante un periodo igual al de la pena de prisión impuesta, con independencia de su relación con el delito, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente, salvo que la autoridad judicial disponga otra cosa.","inhabilitación especial para el derecho de sufragio activo durante el tiempo de la condena, con carácter obligatorio.","inhabilitación especial para empleo o cargo público, profesión, oficio, industria, comercio, ejercicio de la patria potestad, tutela, curatela, guarda o acogimiento o cualquier otro derecho, si estos derechos hubieran tenido relación directa con el delito cometido.","privación del derecho a la tenencia y porte de armas durante el tiempo de la condena."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">inhabilitación especial para empleo o cargo público, profesión, oficio, industria, comercio, ejercicio de la patria potestad, tutela, curatela, guarda o acogimiento o cualquier otro derecho, si estos derechos hubieran tenido relación directa con el delito cometido</mark></span>El <span class=\"ref-norma\">art. 56.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"3.º Inhabilitación especial para empleo o cargo público, profesión, oficio, industria, comercio, ejercicio de la patria potestad, tutela, curatela, guarda o acogimiento o cualquier otro derecho, la privación de la patria potestad, si estos derechos hubieran tenido relación directa con el delito cometido, debiendo determinarse expresamente en la sentencia esta vinculación\"</span>. Penas accesorias de las prisiones inferiores a diez años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 38","q":[{"i":"18-241","p":"Código Penal. Cuando el reo no estuviere preso, la duración de las penas empezará a contarse desde:","o":["Que ingrese cualquier establecimiento para ello.","Que ingrese en el establecimiento adecuado para su cumplimiento.","El día en que la sentencia condenatoria haya quedado firme.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Que ingrese en el establecimiento adecuado para su cumplimiento.</mark></span><span class=\"ref-norma\">Art. 76.2 · De las Penas</span>. (El Artículo 76.2 del CP establece que el cómputo comienza desde el ingreso en el establecimiento adecuado)."},{"i":"18-ia-1209","p":"Código Penal. Cómputo de las penas. Cuando el reo no estuviere preso, la duración de las penas empezará a contarse:","o":["desde que ingrese en el establecimiento adecuado para su cumplimiento.","desde el día en que la sentencia condenatoria haya quedado firme.","desde que sea requerido para su ingreso por el juez o tribunal sentenciador.","desde el día siguiente a la notificación de la sentencia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">desde que ingrese en el establecimiento adecuado para su cumplimiento</mark></span>El <span class=\"ref-norma\">art. 38 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Cuando el reo no estuviere preso, la duración de las penas empezará a contarse desde que ingrese en el establecimiento adecuado para su cumplimiento\"</span>. Si está preso, desde la firmeza de la sentencia; si no lo está, desde que ingrese en el establecimiento adecuado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1210","p":"Código Penal. Cómputo de las penas. Cuando el reo estuviere preso, la duración de las penas empezará a computarse:","o":["desde que ingrese en el establecimiento adecuado para su cumplimiento.","desde el día en que se dicte la sentencia condenatoria.","desde el momento de su detención por los hechos enjuiciados.","desde el día en que la sentencia condenatoria haya quedado firme."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">desde el día en que la sentencia condenatoria haya quedado firme</mark></span>El <span class=\"ref-norma\">art. 38.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Cuando el reo estuviere preso, la duración de las penas empezará a computarse desde el día en que la sentencia condenatoria haya quedado firme\"</span>. Desde la firmeza de la sentencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 32","q":[{"i":"18-242","p":"Código Penal. ¿Qué carácter pueden tener las penas que pueden imponerse con arreglo a este Código, siendo estas privativas de libertad, privativas de otros derechos y multa?","o":["Con carácter principal","Con carácter accesorio","A y B son respuestas correctas.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A y B son respuestas correctas</mark></span>Pueden ser principales o accesorias (art. 32, no 33.1). Según el <span class=\"ref-norma\">art. 32 del Código Penal</span>: <span class=\"ref-concepto\">\"Las penas que pueden imponerse con arreglo a este Código, bien con carácter principal bien como accesorias, son privativas de libertad, privativas de otros derechos y multa\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1129","p":"Código Penal. Clasificación de las penas. Las penas que pueden imponerse con arreglo al Código Penal, bien con carácter principal bien como accesorias, son:","o":["privativas de libertad, privativas de otros derechos y multa.","privativas de libertad, restrictivas de derechos y multa.","privativas de libertad, privativas de derechos, multa y trabajos en beneficio de la comunidad.","privativas de libertad y multa, con exclusión de las accesorias."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">privativas de libertad, privativas de otros derechos y multa</mark></span>El <span class=\"ref-norma\">art. 32 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"son privativas de libertad, privativas de otros derechos y multa\"</span>. Tres clases: privativas de libertad, privativas de otros derechos y multa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 71 EX ✱","q":[{"i":"18-272","p":"Código Penal. Pena inferior en grado. Cuando por aplicación de las reglas de la pena inferior en grado proceda imponer una pena de prisión inferior a tres meses, ésta será en todo caso sustituida por:","o":["Multa, trabajos en beneficio de la comunidad o localización permanente, aunque la ley no prevea estas penas para el delito de que se trate.","Multa o trabajos en beneficio de la comunidad, solo si la ley prevé estas penas para el delito de que se trate, conforme al procedimiento que reglamentariamente se establezca.","Localización permanente, exclusivamente cuando el condenado lo solicite.","Suspensión de la ejecución de la pena, con sujeción a plazo de prueba."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Multa, trabajos en beneficio de la comunidad o localización permanente, aunque la ley no prevea estas penas para el delito de que se trate</mark></span>El <span class=\"ref-norma\">art. 71.2 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"ésta será en todo caso sustituida por multa, trabajos en beneficio de la comunidad, o localización permanente, aunque la ley no prevea estas penas para el delito de que se trate\"</span>"},{"i":"18-ia-1315","p":"Código Penal. Pena inferior en grado. En la determinación de la pena inferior en grado, los jueces o tribunales no quedarán limitados por las cuantías mínimas señaladas en la ley a cada clase de pena, sino que:","o":["deberán respetarlas, salvo autorización del Ministerio Fiscal, salvo que la autoridad judicial disponga otra cosa.","podrán reducirlas hasta la mitad exclusivamente.","podrán reducirlas en la forma que resulte de la aplicación de la regla correspondiente.","podrán reducirlas únicamente en las penas de multa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">podrán reducirlas en la forma que resulte de la aplicación de la regla correspondiente</mark></span>El <span class=\"ref-norma\">art. 71.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"no quedarán limitados por las cuantías mínimas señaladas en la ley a cada clase de pena, sino que podrán reducirlas en la forma que resulte de la aplicación de la regla correspondiente\"</span>. Pueden reducirlas conforme a la regla correspondiente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1316","p":"Código Penal. Pena inferior en grado. Cuando por aplicación de las reglas anteriores proceda imponer una pena de prisión inferior a tres meses, ésta será en todo caso sustituida por multa, trabajos en beneficio de la comunidad, o localización permanente, sustituyéndose cada día de prisión por:","o":["una cuota de multa o por una jornada de trabajo o por un día de localización permanente.","dos cuotas de multa o por una jornada de trabajo o por un día de localización permanente.","dos cuotas de multa o por dos jornadas de trabajo o por un día de localización permanente.","tres cuotas de multa o por una jornada de trabajo o por dos días de localización permanente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">dos cuotas de multa o por una jornada de trabajo o por un día de localización permanente</mark></span>El <span class=\"ref-norma\">art. 71.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"sustituyéndose cada día de prisión por dos cuotas de multa o por una jornada de trabajo o por un día de localización permanente\"</span>. Dos cuotas de multa, una jornada de trabajo o un día de localización permanente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 73 ✱","q":[{"i":"18-273","p":"Código Penal. Concurso real. Al responsable de dos o más delitos o faltas se le impondrán todas las penas correspondientes a las diversas infracciones:","o":["Para su cumplimiento sucesivo, por orden de menor a mayor gravedad.","Para su cumplimiento simultáneo, en todo caso, cualquiera que sea su naturaleza, sin perjuicio de lo que establezcan los tratados internacionales.","Para su cumplimiento sucesivo, por orden cronológico de imposición.","Para su cumplimiento simultáneo, si fuera posible, por la naturaleza y efectos de las mismas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Para su cumplimiento simultáneo, si fuera posible, por la naturaleza y efectos de las mismas</mark></span>El <span class=\"ref-norma\">art. 73 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"Al responsable de dos o más delitos o faltas se le impondrán todas las penas correspondientes a las diversas infracciones para su cumplimiento simultáneo, si fuera posible, por la naturaleza y efectos de las mismas\"</span>"},{"i":"18-ia-1318","p":"Código Penal. Concurso real de delitos. Al responsable de dos o más delitos o faltas se le impondrán todas las penas correspondientes a las diversas infracciones para su cumplimiento simultáneo:","o":["en todo caso, cualquiera que sea su naturaleza.","siempre que no superen el triple de la más grave.","si así lo solicitara el penado y lo autorizara el juez, previo informe de la unidad policial competente.","si fuera posible, por la naturaleza y efectos de las mismas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">si fuera posible, por la naturaleza y efectos de las mismas</mark></span>El <span class=\"ref-norma\">art. 73 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"se le impondrán todas las penas correspondientes a las diversas infracciones para su cumplimiento simultáneo, si fuera posible, por la naturaleza y efectos de las mismas\"</span>. Simultáneo si es posible por su naturaleza y efectos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 79 EX","q":[{"i":"18-276","p":"Código Penal. Penas accesorias. Siempre que los Jueces o Tribunales impongan una pena que lleve consigo otras accesorias, condenarán también expresamente al reo:","o":["A estas últimas.","A las penas sustitutivas que procedan.","Al pago de las costas procesales.","A la responsabilidad civil derivada del delito."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A estas últimas</mark></span>El <span class=\"ref-norma\">art. 79 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"Siempre que los Jueces o Tribunales impongan una pena que lleve consigo otras accesorias condenarán también expresamente al reo a estas últimas\"</span>"},{"i":"18-ia-1339","p":"Código Penal. Penas accesorias. Siempre que los Jueces o Tribunales impongan una pena que lleve consigo otras accesorias condenarán también a estas últimas:","o":["tácitamente, por ministerio de la ley.","previo informe del Ministerio Fiscal.","expresamente al reo.","a petición de la acusación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">expresamente al reo</mark></span>El <span class=\"ref-norma\">art. 79 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"condenarán también expresamente al reo a estas últimas\"</span>. Expresamente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 118 ✱","q":[{"i":"18-285","p":"Código Penal. Exención de la responsabilidad criminal y civil. En el caso de quien actúa impulsado por miedo insuperable, responderán civilmente:","o":["Principalmente los que hayan ejecutado el hecho, y en defecto de ellos, los que hayan causado el miedo.","Solidariamente los que hayan causado el miedo y los que hayan ejecutado el hecho.","Las personas en cuyo favor se haya precavido el mal, en proporción al perjuicio que se les haya evitado.","Principalmente los que hayan causado el miedo, y en defecto de ellos, los que hayan ejecutado el hecho."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Principalmente los que hayan causado el miedo, y en defecto de ellos, los que hayan ejecutado el hecho</mark></span>El <span class=\"ref-norma\">art. 118.1.4.ª de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"ª En el caso del número 6.º, responderán principalmente los que hayan causado el miedo, y en defecto de ellos, los que hayan ejecutado el hecho\"</span>"},{"i":"18-ia-1443","p":"Código Penal. Personas civilmente responsables. En los casos de exención por anomalía o alteración psíquica y por alteraciones en la percepción, son también responsables por los hechos que ejecuten los declarados exentos de responsabilidad penal quienes ejerzan su apoyo legal o de hecho, siempre que:","o":["hayan sido designados por el Juez, con independencia de su culpa o negligencia.","convivan con el declarado exento, aunque no haya mediado culpa o negligencia.","haya mediado culpa o negligencia por su parte y sin perjuicio de la responsabilidad civil directa que pudiera corresponder a los inimputables.","haya mediado dolo por su parte, con exclusión de la responsabilidad de los inimputables, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">haya mediado culpa o negligencia por su parte y sin perjuicio de la responsabilidad civil directa que pudiera corresponder a los inimputables</mark></span>El <span class=\"ref-norma\">art. 118.1.1.ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"siempre que haya mediado culpa o negligencia por su parte y sin perjuicio de la responsabilidad civil directa que pudiera corresponder a los inimputables\"</span>. Culpa o negligencia de quien presta apoyo, sin perjuicio de la responsabilidad directa del inimputable. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 127 bis ✱","q":[{"i":"18-287","p":"Código Penal. Decomiso ampliado. El decomiso ampliado procede, entre otros, por delitos contra el patrimonio y contra el orden socioeconómico:","o":["En todo caso, cualquiera que sea su cuantía.","En los supuestos de continuidad delictiva y reincidencia.","Únicamente cuando exceda de 6.000 euros el perjuicio causado.","Solo cuando se cometan en el seno de una organización o grupo criminal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En los supuestos de continuidad delictiva y reincidencia</mark></span>El <span class=\"ref-norma\">art. 127 bis.1.d) de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"Delitos contra el patrimonio y contra el orden socioeconómico en los supuestos de continuidad delictiva y reincidencia\"</span>"},{"i":"18-ia-1505","p":"Código Penal. Decomiso ampliado. El juez o tribunal ordenará también el decomiso de los bienes, efectos y ganancias pertenecientes a una persona condenada por alguno de los delitos enumerados cuando resuelva, a partir de indicios objetivos fundados, que los bienes o efectos provienen de una actividad delictiva, y:","o":["no se acredite su origen lícito.","el condenado no los hubiera declarado.","su valor exceda de 6.000 euros.","hayan sido transferidos a terceras personas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no se acredite su origen lícito</mark></span>El <span class=\"ref-norma\">art. 127 bis.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"cuando resuelva, a partir de indicios objetivos fundados, que los bienes o efectos provienen de una actividad delictiva, y no se acredite su origen lícito\"</span>. No se acredite su origen lícito. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1507","p":"Código Penal. Decomiso ampliado. Señale la INCORRECTA. A los efectos del decomiso ampliado se valorarán especialmente, entre otros, los siguientes indicios:","o":["La desproporción entre el valor de los bienes y efectos de que se trate y los ingresos de origen lícito de la persona condenada.","La ocultación de la titularidad o de cualquier poder de disposición sobre los bienes o efectos mediante la utilización de personas físicas o jurídicas o entes sin personalidad jurídica interpuestos.","La existencia de antecedentes penales por delitos de la misma naturaleza.","La transferencia de los bienes o efectos mediante operaciones que dificulten o impidan su localización o destino y que carezcan de una justificación legal o económica válida."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La existencia de antecedentes penales por delitos de la misma naturaleza</mark></span>El <span class=\"ref-norma\">art. 127 bis.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"1.º La desproporción entre el valor de los bienes y efectos de que se trate y los ingresos de origen lícito de la persona condenada\"</span>. Los antecedentes penales no figuran entre los indicios. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1508","p":"Código Penal. Decomiso ampliado. El decomiso ampliado no será acordado cuando las actividades delictivas de las que provengan los bienes o efectos:","o":["se hubieran cometido fuera del territorio nacional o hubieran sido objeto de sobreseimiento provisional, en los términos que se determinen reglamentariamente, salvo que la autoridad judicial disponga otra cosa.","hubieran prescrito o hubieran sido ya objeto de un proceso penal resuelto por sentencia absolutoria o resolución de sobreseimiento con efectos de cosa juzgada.","hubieran sido cometidas por menores de edad o por personas exentas de responsabilidad.","hubieran prescrito, aunque no hubieran sido objeto de proceso penal alguno."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">hubieran prescrito o hubieran sido ya objeto de un proceso penal resuelto por sentencia absolutoria o resolución de sobreseimiento con efectos de cosa juzgada</mark></span>El <span class=\"ref-norma\">art. 127 bis.5 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"no será acordado cuando las actividades delictivas de las que provengan los bienes o efectos hubieran prescrito o hubieran sido ya objeto de un proceso penal resuelto por sentencia absolutoria o resolución de sobreseimiento con efectos de cosa juzgada\"</span>. Prescritas o ya enjuiciadas con sentencia absolutoria o sobreseimiento con efectos de cosa juzgada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Título Preliminar: De las Garantías Penales y de la Aplicación de la Ley Penal","q":[{"i":"18-ia-1001","p":"Código Penal. Principio de legalidad. No será castigada ninguna acción ni omisión que no esté prevista como delito por ley:","o":["anterior a su perpetración.","vigente en el momento de su enjuiciamiento.","anterior a la sentencia que ponga fin al proceso.","orgánica o por reglamento que la desarrolle."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">anterior a su perpetración</mark></span>El <span class=\"ref-norma\">art. 1.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"No será castigada ninguna acción ni omisión que no esté prevista como delito por ley anterior a su perpetración\"</span>. El principio de legalidad exige ley anterior a la perpetración, no al enjuiciamiento ni a la sentencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1002","p":"Código Penal. Principio de legalidad. Las medidas de seguridad sólo podrán aplicarse cuando concurran los presupuestos establecidos __________ por la Ley:","o":["posteriormente","reglamentariamente","judicialmente","previamente"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">previamente</mark></span>El <span class=\"ref-norma\">art. 1.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Las medidas de seguridad sólo podrán aplicarse cuando concurran los presupuestos establecidos previamente por la Ley\"</span>. Los presupuestos deben estar establecidos previamente por la Ley. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"De las Personas Criminalmente Responsables de los Delitos","q":[{"i":"18-ia-1110","p":"Código Penal. Delitos cometidos por medios de difusión. En el orden escalonado de responsabilidad por delitos cometidos por medios de difusión mecánicos, los directores de la empresa editora, emisora o difusora ocupan el lugar:","o":["segundo, en los términos que se determinen reglamentariamente.","primero.","cuarto.","tercero."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tercero</mark></span>El <span class=\"ref-norma\">art. 30.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"3.º Los directores de la empresa editora, emisora o difusora\"</span>. Son el tercer escalón. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1121","p":"Código Penal. Modelos de organización y gestión. Señale la INCORRECTA. Los modelos de organización y gestión deberán cumplir los siguientes requisitos:","o":["Establecerán un sistema de recompensas que premie la denuncia de infracciones internas.","Identificarán las actividades en cuyo ámbito puedan ser cometidos los delitos que deben ser prevenidos.","Dispondrán de modelos de gestión de los recursos financieros adecuados para impedir la comisión de los delitos que deben ser prevenidos.","Impondrán la obligación de informar de posibles riesgos e incumplimientos al organismo encargado de vigilar el funcionamiento y observancia del modelo de prevención."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Establecerán un sistema de recompensas que premie la denuncia de infracciones internas</mark></span>El <span class=\"ref-norma\">art. 31 bis.5 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"5.º Establecerán un sistema disciplinario que sancione adecuadamente el incumplimiento de las medidas que establezca el modelo\"</span>. El requisito es un sistema disciplinario que sancione el incumplimiento, no un sistema de recompensas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1123","p":"Código Penal. Responsabilidad de las personas jurídicas. La responsabilidad penal de las personas jurídicas será exigible siempre que se constate la comisión de un delito que haya tenido que cometerse por quien ostente los cargos o funciones aludidas, aun cuando la concreta persona física responsable no haya sido individualizada o no haya sido posible dirigir el procedimiento contra ella. Cuando como consecuencia de los mismos hechos se impusiere a ambas la pena de multa, los jueces o tribunales:","o":["impondrán la multa solo a la persona jurídica, quedando exenta la persona física, sin perjuicio de lo previsto en la normativa vigente.","impondrán la multa solo a la persona física, quedando exenta la persona jurídica.","modularán las respectivas cuantías, de modo que la suma resultante no sea desproporcionada en relación con la gravedad de aquéllos.","acumularán las multas sin límite alguno atendida la gravedad de los hechos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">modularán las respectivas cuantías, de modo que la suma resultante no sea desproporcionada en relación con la gravedad de aquéllos</mark></span>El <span class=\"ref-norma\">art. 31 ter.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"los jueces o tribunales modularán las respectivas cuantías, de modo que la suma resultante no sea desproporcionada en relación con la gravedad de aquéllos\"</span>. Se modulan las cuantías para evitar una suma desproporcionada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1124","p":"Código Penal. Responsabilidad de las personas jurídicas. La concurrencia, en las personas que materialmente hayan realizado los hechos, de circunstancias que afecten a la culpabilidad del acusado o agraven su responsabilidad, o el hecho de que dichas personas hayan fallecido o se hubieren sustraído a la acción de la justicia:","o":["excluirá la responsabilidad penal de las personas jurídicas.","no excluirá ni modificará la responsabilidad penal de las personas jurídicas.","atenuará la responsabilidad penal de las personas jurídicas.","suspenderá el procedimiento contra las personas jurídicas hasta su localización."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">no excluirá ni modificará la responsabilidad penal de las personas jurídicas</mark></span>El <span class=\"ref-norma\">art. 31 ter.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"no excluirá ni modificará la responsabilidad penal de las personas jurídicas\"</span>. La responsabilidad de la persona jurídica no se excluye ni modifica. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 55 ✱","q":[{"i":"18-ia-1249","p":"Código Penal. Penas accesorias. La pena de prisión igual o superior a diez años llevará consigo la inhabilitación absoluta durante el tiempo de la condena, salvo que ésta ya estuviere prevista como pena principal para el supuesto de que se trate. El Juez podrá además disponer la inhabilitación especial para el ejercicio de la patria potestad, tutela, curatela, guarda o acogimiento, o bien la privación de la patria potestad, cuando estos derechos hubieren tenido relación directa con el delito cometido. Esta vinculación deberá determinarse:","o":["expresamente en la sentencia.","motivadamente en auto posterior.","previo informe del Ministerio Fiscal.","de oficio por el Juez de Vigilancia Penitenciaria."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">expresamente en la sentencia</mark></span>El <span class=\"ref-norma\">art. 55 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Esta vinculación deberá determinarse expresamente en la sentencia\"</span>. Expresamente en la sentencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1250","p":"Código Penal. Penas accesorias. La pena de prisión igual o superior a diez años llevará consigo:","o":["la inhabilitación especial para empleo o cargo público durante el tiempo de la condena.","la suspensión de empleo o cargo público durante el tiempo de la condena.","la inhabilitación absoluta durante diez años tras el cumplimiento de la condena.","la inhabilitación absoluta durante el tiempo de la condena."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la inhabilitación absoluta durante el tiempo de la condena</mark></span>El <span class=\"ref-norma\">art. 55 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La pena de prisión igual o superior a diez años llevará consigo la inhabilitación absoluta durante el tiempo de la condena\"</span>. Pena de prisión de diez años o más: inhabilitación absoluta durante el tiempo de la condena. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"De la Aplicación de las Penas","q":[{"i":"18-ia-1264","p":"Código Penal. Reglas generales para la aplicación de las penas. Las reglas anteriores sobre la pena de la tentativa y de la complicidad no serán de aplicación:","o":["en los delitos cometidos por imprudencia grave.","en los casos en que la tentativa y la complicidad se hallen especialmente penadas por la Ley.","en los delitos que tengan señalada pena de prisión superior a quince años, en los términos que se determinen reglamentariamente.","cuando concurra la agravante de reincidencia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en los casos en que la tentativa y la complicidad se hallen especialmente penadas por la Ley</mark></span>El <span class=\"ref-norma\">art. 64 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Las reglas anteriores no serán de aplicación en los casos en que la tentativa y la complicidad se hallen especialmente penadas por la Ley\"</span>. No se aplican cuando la tentativa y la complicidad estén especialmente penadas por la Ley. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1265","p":"Código Penal. Reglas generales para la aplicación de las penas. Las circunstancias agravantes o atenuantes que consistan en cualquier causa de naturaleza personal agravarán o atenuarán la responsabilidad:","o":["sólo de aquéllos en quienes concurran.","de todos los que hayan participado en el hecho.","de los que hayan tenido conocimiento de ellas en el momento de la acción.","únicamente de los autores, y no de los cómplices."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">sólo de aquéllos en quienes concurran</mark></span>El <span class=\"ref-norma\">art. 65.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"agravarán o atenuarán la responsabilidad sólo de aquéllos en quienes concurran\"</span>. Las de naturaleza personal solo afectan a quienes concurran. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1266","p":"Código Penal. Reglas generales para la aplicación de las penas. Las circunstancias que consistan en la ejecución material del hecho o en los medios empleados para realizarla, servirán únicamente para agravar o atenuar la responsabilidad de:","o":["aquéllos en quienes concurran personalmente.","todos los que hayan intervenido en el hecho, con independencia de su conocimiento, salvo que la autoridad judicial disponga otra cosa.","los autores y cooperadores necesarios que las hubieran previsto.","los que hayan tenido conocimiento de ellas en el momento de la acción o de su cooperación para el delito."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los que hayan tenido conocimiento de ellas en el momento de la acción o de su cooperación para el delito</mark></span>El <span class=\"ref-norma\">art. 65.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"servirán únicamente para agravar o atenuar la responsabilidad de los que hayan tenido conocimiento de ellas en el momento de la acción o de su cooperación para el delito\"</span>. Solo de quienes las conocían en el momento de la acción o cooperación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1267","p":"Código Penal. Reglas generales para la aplicación de las penas. Cuando en el inductor o en el cooperador necesario no concurran las condiciones, cualidades o relaciones personales que fundamentan la culpabilidad del autor, los jueces o tribunales podrán imponer:","o":["la pena inferior en uno o dos grados a la señalada por la ley para la infracción de que se trate.","la pena en su mitad inferior a la señalada por la ley para la infracción de que se trate.","la pena inferior en grado a la señalada por la ley para la infracción de que se trate.","la misma pena que al autor, rebajada en un tercio."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la pena inferior en grado a la señalada por la ley para la infracción de que se trate</mark></span>El <span class=\"ref-norma\">art. 65.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"los jueces o tribunales podrán imponer la pena inferior en grado a la señalada por la ley para la infracción de que se trate\"</span>. Pena inferior en grado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1278","p":"Código Penal. Aplicación de las penas a las personas jurídicas. Para decidir sobre la imposición y la extensión de las penas previstas para las personas jurídicas en las letras b) a g) habrá de tenerse en cuenta, entre otros criterios, su necesidad para:","o":["reparar el daño causado a la víctima del delito.","garantizar el cobro de la responsabilidad civil derivada del delito.","asegurar el cumplimiento de las medidas cautelares acordadas.","prevenir la continuidad de la actividad delictiva o de sus efectos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">prevenir la continuidad de la actividad delictiva o de sus efectos</mark></span>El <span class=\"ref-norma\">art. 66 bis.1.ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"a) Su necesidad para prevenir la continuidad de la actividad delictiva o de sus efectos\"</span>. Necesidad para prevenir la continuidad de la actividad delictiva o de sus efectos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1279","p":"Código Penal. Aplicación de las penas a las personas jurídicas. Para la imposición de las sanciones previstas en las letras c) a g) para las personas jurídicas por un plazo superior a dos años será necesario que la persona jurídica sea reincidente o que:","o":["haya sido condenada por un delito de la misma naturaleza en los últimos cinco años.","carezca de un modelo de organización y gestión adecuado.","se utilice instrumentalmente para la comisión de ilícitos penales.","haya obtenido un beneficio económico superior a 100.000 euros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">se utilice instrumentalmente para la comisión de ilícitos penales</mark></span>El <span class=\"ref-norma\">art. 66 bis.2.ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"será necesario que se dé alguna de las dos circunstancias siguientes: a) Que la persona jurídica sea reincidente. b) Que la persona jurídica se utilice instrumentalmente para la comisión de ilícitos penales\"</span>. Reincidencia o utilización instrumental para la comisión de ilícitos penales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1280","p":"Código Penal. Aplicación de las penas a las personas jurídicas. Se entenderá que la persona jurídica se utiliza instrumentalmente para la comisión de ilícitos penales:","o":["siempre que la actividad ilegal de la persona jurídica sea al menos la mitad de su actividad total.","siempre que la actividad legal de la persona jurídica sea menos relevante que su actividad ilegal.","siempre que se hubiera constituido con la finalidad exclusiva de delinquir.","cuando hubiera sido condenada con anterioridad por dos o más delitos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">siempre que la actividad legal de la persona jurídica sea menos relevante que su actividad ilegal</mark></span>El <span class=\"ref-norma\">art. 66 bis.2.ª del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Se entenderá que se está ante este último supuesto siempre que la actividad legal de la persona jurídica sea menos relevante que su actividad ilegal\"</span>. Su actividad legal es menos relevante que la ilegal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1301","p":"Código Penal. Aplicación de las penas a las personas jurídicas. Cuando la responsabilidad de la persona jurídica derive de un incumplimiento de los deberes de supervisión, vigilancia y control que no tenga carácter grave, las penas de las letras c) a g) tendrán en todo caso una duración máxima de:","o":["dos años.","cinco años.","un año.","tres años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">dos años</mark></span>El <span class=\"ref-norma\">art. 66 bis del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"derive de un incumplimiento de los deberes de supervisión, vigilancia y control que no tenga carácter grave, estas penas tendrán en todo caso una duración máxima de dos años\"</span>. Dos años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1302","p":"Código Penal. Aplicación de las penas a las personas jurídicas. Para la imposición por un plazo superior a cinco años de las sanciones previstas en las letras e) y f), será necesario que se dé alguna de las dos circunstancias siguientes: que se esté ante el supuesto de la reincidencia cualificada o que:","o":["la persona jurídica carezca de un modelo de organización y gestión.","la persona jurídica haya obtenido un beneficio superior a 100.000 euros, en los términos que se determinen reglamentariamente.","el delito haya sido cometido por un administrador de hecho.","la persona jurídica se utilice instrumentalmente para la comisión de ilícitos penales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la persona jurídica se utilice instrumentalmente para la comisión de ilícitos penales</mark></span>El <span class=\"ref-norma\">art. 66 bis del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Que la persona jurídica se utilice instrumentalmente para la comisión de ilícitos penales\"</span>. Reincidencia cualificada o utilización instrumental de la persona jurídica. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1303","p":"Código Penal. Reglas para la aplicación de las penas. Las reglas anteriores no se aplicarán a las circunstancias agravantes o atenuantes que la Ley haya tenido en cuenta al describir o sancionar una infracción, ni a las que sean:","o":["de naturaleza personal respecto de los cómplices.","de tal manera genéricas que no guarden relación con la ejecución material del hecho, salvo que la autoridad judicial disponga otra cosa.","de tal manera inherentes al delito que sin la concurrencia de ellas no podría cometerse.","apreciadas por el jurado como muy cualificadas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">de tal manera inherentes al delito que sin la concurrencia de ellas no podría cometerse</mark></span>El <span class=\"ref-norma\">art. 67 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"ni a las que sean de tal manera inherentes al delito que sin la concurrencia de ellas no podría cometerse\"</span>. Inherentes al delito: sin ellas no podría cometerse. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1304","p":"Código Penal. Eximentes incompletas. En los casos de eximente incompleta, los jueces o tribunales impondrán la pena inferior en uno o dos grados a la señalada por la ley, atendidos el número y la entidad de los requisitos que falten o concurran, y:","o":["la peligrosidad criminal del sujeto, sin perjuicio de las medidas de seguridad que procedan.","las circunstancias personales de su autor, sin perjuicio de la aplicación de las reglas generales de aplicación de las penas.","el daño causado a la víctima, con exclusión de las reglas generales de aplicación de las penas.","las circunstancias personales de su autor, con exclusión de las reglas generales de aplicación de las penas, previo informe de la unidad policial competente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las circunstancias personales de su autor, sin perjuicio de la aplicación de las reglas generales de aplicación de las penas</mark></span>El <span class=\"ref-norma\">art. 68 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"y las circunstancias personales de su autor, sin perjuicio de la aplicación del artículo 66 del presente Código\"</span>. Pena inferior en uno o dos grados, sin perjuicio de las reglas generales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1317","p":"Código Penal. Individualización de la pena. Los jueces o tribunales, en la aplicación de la pena, con arreglo a las normas contenidas en este capítulo, razonarán en la sentencia:","o":["el grado y extensión concreta de la impuesta.","únicamente el grado de la pena impuesta.","la concurrencia de circunstancias agravantes, sin necesidad de motivar la extensión.","las razones de prevención general que justifican la pena."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el grado y extensión concreta de la impuesta</mark></span>El <span class=\"ref-norma\">art. 72 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"razonarán en la sentencia el grado y extensión concreta de la impuesta\"</span>. Grado y extensión concreta de la pena. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1322","p":"Código Penal. Cumplimiento sucesivo. Cuando todas o algunas de las penas correspondientes a las diversas infracciones no puedan ser cumplidas simultáneamente por el condenado, se seguirá:","o":["el orden cronológico de imposición para su cumplimiento sucesivo, en cuanto sea posible, salvo que la autoridad judicial disponga otra cosa.","el orden de menor a mayor gravedad para su cumplimiento sucesivo.","el orden que determine el Juez de Vigilancia Penitenciaria en cada caso.","el orden de su respectiva gravedad para su cumplimiento sucesivo, en cuanto sea posible."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el orden de su respectiva gravedad para su cumplimiento sucesivo, en cuanto sea posible</mark></span>El <span class=\"ref-norma\">art. 75 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"se seguirá el orden de su respectiva gravedad para su cumplimiento sucesivo, en cuanto sea posible\"</span>. Orden de su respectiva gravedad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1328","p":"Código Penal. Concurso ideal y medial. Las reglas del concurso real y del máximo de cumplimiento no son aplicables en el caso de que un solo hecho constituya dos o más delitos, o cuando:","o":["uno de ellos sea de mayor gravedad que el otro.","uno de ellos sea medio necesario para cometer el otro.","los delitos hayan sido cometidos en un mismo lugar, salvo que la autoridad judicial disponga otra cosa.","los delitos ofendan a un mismo sujeto pasivo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">uno de ellos sea medio necesario para cometer el otro</mark></span>El <span class=\"ref-norma\">art. 77.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"o cuando uno de ellos sea medio necesario para cometer el otro\"</span>. Concurso ideal (un hecho) y medial (medio necesario). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1329","p":"Código Penal. Concurso ideal y medial. En el caso de que un solo hecho constituya dos o más delitos, se aplicará en su mitad superior la pena prevista para la infracción más grave, sin que pueda exceder de:","o":["la que represente la suma de las que correspondería aplicar si se penaran separadamente las infracciones.","el doble de la pena prevista para la infracción más grave.","el triple de la pena prevista para la infracción más grave.","la pena superior en grado a la prevista para la infracción más grave, previo informe de la unidad policial competente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la que represente la suma de las que correspondería aplicar si se penaran separadamente las infracciones</mark></span>El <span class=\"ref-norma\">art. 77.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"sin que pueda exceder de la que represente la suma de las que correspondería aplicar si se penaran separadamente las infracciones\"</span>. No puede exceder de la suma de las penas por separado; si la excede, se sancionan por separado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1330","p":"Código Penal. Concurso ideal y medial. Cuando uno de los delitos sea medio necesario para cometer el otro, se impondrá una pena superior a la que habría correspondido, en el caso concreto, por la infracción más grave, y que no podrá exceder de:","o":["la mitad superior de la pena prevista para la infracción más grave.","el triple de la pena concreta de la infracción más grave.","la pena superior en grado a la señalada para la infracción más grave, sin perjuicio de lo previsto en la normativa vigente.","la suma de las penas concretas que hubieran sido impuestas separadamente por cada uno de los delitos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la suma de las penas concretas que hubieran sido impuestas separadamente por cada uno de los delitos</mark></span>El <span class=\"ref-norma\">art. 77.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"que no podrá exceder de la suma de las penas concretas que hubieran sido impuestas separadamente por cada uno de los delitos\"</span>. No puede exceder de la suma de las penas concretas impuestas por separado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"De la Responsabilidad Civil Derivada de los Delitos y de las Costas Procesales","q":[{"i":"18-ia-1444","p":"Código Penal. Personas civilmente responsables. El Juez o Tribunal que dicte sentencia absolutoria por estimar la concurrencia de alguna de las causas de exención, procederá a fijar las responsabilidades civiles:","o":["en todo caso, sin posibilidad de reserva de acciones, sin perjuicio de lo previsto en la normativa vigente.","salvo que se haya hecho expresa reserva de las acciones para reclamarlas en la vía que corresponda.","únicamente si lo solicita el Ministerio Fiscal.","salvo que el absuelto carezca de patrimonio."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">salvo que se haya hecho expresa reserva de las acciones para reclamarlas en la vía que corresponda</mark></span>El <span class=\"ref-norma\">art. 119 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"procederá a fijar las responsabilidades civiles salvo que se haya hecho expresa reserva de las acciones para reclamarlas en la vía que corresponda\"</span>. Salvo reserva expresa de acciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1446","p":"Código Penal. Responsabilidad civil subsidiaria de la Administración. El Estado, la Comunidad Autónoma, la provincia, la isla, el municipio y demás entes públicos, según los casos, responden subsidiariamente de los daños causados por los penalmente responsables de los delitos dolosos o culposos, cuando éstos sean autoridad, agentes y contratados de la misma o funcionarios públicos en el ejercicio de sus cargos o funciones siempre que:","o":["la lesión sea consecuencia indirecta del funcionamiento de los servicios públicos que les estuvieren confiados.","el delito se haya cometido dentro de las dependencias del servicio público.","el penalmente responsable haya actuado por orden de un superior jerárquico.","la lesión sea consecuencia directa del funcionamiento de los servicios públicos que les estuvieren confiados."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la lesión sea consecuencia directa del funcionamiento de los servicios públicos que les estuvieren confiados</mark></span>El <span class=\"ref-norma\">art. 121 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"siempre que la lesión sea consecuencia directa del funcionamiento de los servicios públicos que les estuvieren confiados, sin perjuicio de la responsabilidad patrimonial\"</span>. Responsabilidad subsidiaria si la lesión es consecuencia directa del funcionamiento de los servicios públicos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1447","p":"Código Penal. Responsabilidad civil subsidiaria de la Administración. En la responsabilidad civil subsidiaria de la Administración por los daños causados por sus agentes, la responsabilidad patrimonial derivada del funcionamiento normal o anormal de los servicios públicos se entiende sin que, en ningún caso:","o":["pueda moderarse el importe de la indemnización.","pueda exigirse al funcionario la repetición del importe.","pueda darse una duplicidad indemnizatoria.","pueda reclamarse en la vía contencioso-administrativa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">pueda darse una duplicidad indemnizatoria</mark></span>El <span class=\"ref-norma\">art. 121 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"y sin que, en ningún caso, pueda darse una duplicidad indemnizatoria\"</span>. No puede darse duplicidad indemnizatoria. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]}];
